-- 4. functions (pg_get_functiondef of the source catalog; bodies byte-exact)
CREATE OR REPLACE FUNCTION giro_authority.actor_valid_v1(p_actor text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
  SELECT p_actor IS NOT NULL AND btrim(p_actor) <> '' AND length(btrim(p_actor)) <= 128
$function$;

CREATE OR REPLACE FUNCTION giro_authority.bump_facts_signal_v1()
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
BEGIN
  INSERT INTO public.config (chiave, valore)
    VALUES ('GIRO_FACTS_SIGNAL', jsonb_build_object('version', 1, 'updated_at', now())::text)
  ON CONFLICT (chiave) DO UPDATE
    SET valore = jsonb_build_object(
          'version', COALESCE((public.config.valore::jsonb->>'version')::bigint, 0) + 1,
          'updated_at', now()
        )::text;
END $function$;

CREATE OR REPLACE FUNCTION giro_authority.cancelled_states_v1()
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
  -- language-guard: allow-legacy the legacy forced-close literal of ordenes.estado (same set as rolloverClassifier.TERMINAL_ORDER_STATES)
  SELECT ARRAY['CANCELADO', 'CANCELLED', 'ANULADO', 'CHIUSO_FORZATO']::text[]
$function$;

CREATE OR REPLACE FUNCTION giro_authority.capture_giro_intent_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  v_in            jsonb := NEW.pending_giro_intent;
  v_code          text;
  v_kind          text;
  v_ref           text;
  v_actor         text;
  v_sv            bigint;
  v_giro_id       text;
  v_anchor_uid    uuid;
  v_business_date date;
  v_fingerprint   text;
  v_delivery_type text;
  v_context       jsonb;
  v_sqlstate      text;
BEGIN
  NEW.pending_giro_intent := NULL;
  IF v_in IS NULL THEN
    RETURN NEW;
  END IF;

  BEGIN
    -- language-guard: allow-legacy tipo_consegna is the existing ordenes column name, read-only here
    v_delivery_type := upper(COALESCE(NEW.tipo_consegna, ''));
    v_context := jsonb_build_object('zona', NEW.zona, 'hora', NEW.hora, 'delivery_type', v_delivery_type,
                                    'service_session_id', NEW.service_session_id);
    SELECT ss.business_date INTO v_business_date
      FROM public.service_sessions ss WHERE ss.id = NEW.service_session_id;

    IF jsonb_typeof(v_in) IS DISTINCT FROM 'object'
       OR jsonb_typeof(v_in->'v') IS DISTINCT FROM 'number' OR (v_in->>'v') IS DISTINCT FROM '1'
       OR jsonb_typeof(v_in->'target_kind') IS DISTINCT FROM 'string'
       OR (v_in->>'target_kind') NOT IN ('GIRO', 'ANCHOR')
       OR jsonb_typeof(v_in->'target_ref') IS DISTINCT FROM 'string'
       OR length(btrim(v_in->>'target_ref')) NOT BETWEEN 1 AND 64 THEN
      v_code := 'CAPTURE_MALFORMED';
    ELSE
      v_kind := v_in->>'target_kind';
      v_ref := btrim(v_in->>'target_ref');
      IF (v_in->>'source') IS DISTINCT FROM 'operator_http'
         OR jsonb_typeof(v_in->'source') IS DISTINCT FROM 'string'
         OR jsonb_typeof(v_in->'actor') IS DISTINCT FROM 'string'
         OR NOT giro_authority.actor_valid_v1(v_in->>'actor')
         OR jsonb_typeof(v_in->'sv') IS DISTINCT FROM 'number'
         OR (v_in->>'sv') !~ '^[0-9]{1,18}$' THEN
        v_code := 'CAPTURE_UNTRUSTED_SOURCE';
      ELSE
        v_actor := btrim(v_in->>'actor');
        v_sv := (v_in->>'sv')::bigint;
        IF v_delivery_type <> 'DOMICILIO' OR NEW.table_session_id IS NOT NULL
           OR NEW.service_session_id IS NULL OR v_business_date IS NULL THEN
          v_code := 'CAPTURE_NOT_ELIGIBLE';
        ELSIF v_kind = 'GIRO' THEN
          SELECT mg.id INTO v_giro_id
            FROM public.manual_giros mg
           WHERE mg.id = v_ref AND mg.business_date = v_business_date;
          IF v_giro_id IS NULL THEN v_code := 'CAPTURE_TARGET_NOT_FOUND'; END IF;
        ELSE
          SELECT o.order_uid INTO v_anchor_uid
            FROM public.ordenes o
           WHERE o.id = v_ref AND o.id <> NEW.id
             AND o.service_session_id = NEW.service_session_id AND o.order_uid IS NOT NULL;
          IF v_anchor_uid IS NULL THEN v_code := 'CAPTURE_TARGET_NOT_FOUND'; END IF;
        END IF;
      END IF;
    END IF;

    IF v_code IS NULL THEN
      v_fingerprint := giro_authority.target_fingerprint_v1(v_kind, v_giro_id, v_anchor_uid);
      INSERT INTO giro_authority.giro_intents
        (order_uid, target_kind, target_ref, target_giro_id, target_order_uid, target_fingerprint,
         order_context, business_date, actor, sv, status, phase)
      VALUES (NEW.order_uid, v_kind, v_ref, v_giro_id, v_anchor_uid, v_fingerprint,
              v_context, v_business_date, v_actor, v_sv, 'PENDING', 'CAPTURE');
    ELSE
      INSERT INTO giro_authority.giro_intents
        (order_uid, target_kind, target_ref, order_context, business_date, actor, sv,
         status, phase, resolved_at, resolution_code)
      VALUES (NEW.order_uid, v_kind, v_ref, v_context, v_business_date, v_actor, v_sv,
              'REJECTED', 'CAPTURE', now(), v_code);
    END IF;
  EXCEPTION WHEN others THEN
    GET STACKED DIAGNOSTICS v_sqlstate = RETURNED_SQLSTATE;
    BEGIN
      INSERT INTO giro_authority.giro_intents (order_uid, status, phase, resolved_at, resolution_code, resolution_detail)
      VALUES (NEW.order_uid, 'REJECTED', 'CAPTURE', now(), 'CAPTURE_INTERNAL', jsonb_build_object('sqlstate', v_sqlstate));
    EXCEPTION WHEN others THEN
      RAISE WARNING 'GIRO_INTENT_CAPTURE_DIAGNOSTIC_LOST order_id=% sqlstate=%', NEW.id, v_sqlstate;
    END;
  END;
  RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION giro_authority.delivered_states_v1()
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
  -- language-guard: allow-legacy the legacy terminal-state literal of ordenes.estado (same set as rolloverClassifier.TERMINAL_ORDER_STATES)
  SELECT ARRAY['RETIRADO', 'COMPLETADO', 'COMPLETATO']::text[]
$function$;

CREATE OR REPLACE FUNCTION giro_authority.derive_giros_v1(p_giro_ids text[], p_scope uuid[], p_trip jsonb)
 RETURNS TABLE(giro_id text, seq integer, business_date date, hora_ref text, anchor_order_uid uuid, created_at timestamp with time zone, created_by text, dissolved_at timestamp with time zone, dissolved_by text, giro_state text, state_reason text, effective_order_uids uuid[], effective_order_ids text[], active_order_uids uuid[], salida text, salida_source text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
  WITH trip AS (
    SELECT ARRAY(SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(p_trip->'order_ids') = 'array'
                                                       THEN p_trip->'order_ids' ELSE '[]'::jsonb END)) AS order_ids,
           ARRAY(SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(p_trip->'giro_ids') = 'array'
                                                       THEN p_trip->'giro_ids' ELSE '[]'::jsonb END)) AS giro_ids
  ),
  g AS (
    SELECT mg.id, mg.seq, mg.business_date, mg.hora_ref, mg.anchor_order_uid, mg.created_at,
           mg.created_by, mg.dissolved_at, mg.dissolved_by
      FROM public.manual_giros mg
     WHERE mg.id = ANY (p_giro_ids)
  ),
  -- W6.4: the canonical trip (at most one, enforced by trips_one_trip_per_giro_v1) that
  -- this giro departed as. Its existence -- not its status -- is what makes Trip
  -- Authority the membership authority from here on.
  ct AS (
    SELECT t.giro_id AS g_id, t.trip_id, t.status AS trip_status, t.departed_at
      FROM trip_authority.trips t
     WHERE t.giro_id = ANY (p_giro_ids)
  ),
  -- The immutable frozen membership. Never filtered by delivery state: progress is a
  -- separate derivation (ca.n_outstanding below), never a deletion from this set.
  ctm AS (
    SELECT ct.g_id, ct.trip_id, tm.order_uid AS uid, tm.stop_seq, o.id AS oid, o.estado,
           (o.id IS NOT NULL AND NOT (o.estado = ANY (trip_authority.progress_terminal_states_v1()))) AS still_out
      FROM ct
      JOIN trip_authority.trip_members tm ON tm.trip_id = ct.trip_id
      LEFT JOIN public.ordenes o ON o.order_uid = tm.order_uid
  ),
  ca AS (
    SELECT ctm.g_id, count(*) AS n_members, count(*) FILTER (WHERE ctm.still_out) AS n_outstanding
      FROM ctm GROUP BY ctm.g_id
  ),
  k AS (
    SELECT gm.giro_id AS g_id, gm.order_uid AS uid, o.id AS oid, o.estado, o.forno_out,
           (o.id IS NOT NULL) AS present,
           COALESCE(o.id = ANY (t.order_ids), false) AS in_active_trip,
           COALESCE(p_scope IS NULL OR o.service_session_id = ANY (p_scope), false) AS in_scope
      FROM giro_authority.giro_members gm
      CROSS JOIN trip t
      LEFT JOIN public.ordenes o ON o.order_uid = gm.order_uid
     WHERE gm.giro_id = ANY (p_giro_ids)
  ),
  kc AS (
    SELECT k.*,
           (k.present AND (k.in_active_trip OR k.estado = 'EN_ENTREGA')) AS departed_live,
           (k.present AND k.estado = ANY (giro_authority.delivered_states_v1())) AS delivered,
           (k.present AND k.estado IN ('EN_COCINA', 'LISTO') AND NOT k.in_active_trip) AS pre_departure
      FROM k
  ),
  a AS (
    SELECT kc.g_id,
           count(*) FILTER (WHERE kc.departed_live)                  AS n_departed,
           count(*) FILTER (WHERE kc.delivered)                      AS n_delivered,
           count(*) FILTER (WHERE kc.pre_departure AND kc.in_scope)  AS n_pre_scope,
           count(*) FILTER (WHERE kc.pre_departure)                  AS n_pre_any
      FROM kc GROUP BY kc.g_id
  ),
  st AS (
    SELECT g.*, ct.trip_id AS ct_trip_id, ct.trip_status AS ct_status, ct.departed_at AS ct_departed_at,
           CASE WHEN g.dissolved_at IS NOT NULL THEN 'DISSOLVED'
                -- W6.4 canonical arm: IN_TRIP while the linked trip is ACTIVE and at
                -- least one frozen member is still non-terminal; DONE once every frozen
                -- member is terminal OR the linked trip is CLOSED. Never reverts to the
                -- current giro_members, in any of those phases.
                WHEN ct.trip_id IS NOT NULL THEN
                  CASE WHEN ct.trip_status = 'ACTIVE' AND COALESCE(ca.n_outstanding, 0) > 0
                       THEN 'IN_TRIP' ELSE 'DONE' END
                WHEN COALESCE(a.n_departed, 0) > 0 OR g.id = ANY (t.giro_ids) THEN 'IN_TRIP'
                WHEN COALESCE(a.n_delivered, 0) > 0 THEN 'DONE'
                WHEN COALESCE(a.n_pre_scope, 0) >= 2 THEN 'PLANNED'
                ELSE 'DISSOLVED' END AS g_state,
           CASE WHEN g.dissolved_at IS NOT NULL THEN 'EXPLICIT'
                WHEN ct.trip_id IS NOT NULL THEN
                  CASE WHEN ct.trip_status = 'ACTIVE' AND COALESCE(ca.n_outstanding, 0) > 0
                       THEN 'DEPARTED' ELSE 'DELIVERED' END
                WHEN COALESCE(a.n_departed, 0) > 0 OR g.id = ANY (t.giro_ids) THEN 'DEPARTED'
                WHEN COALESCE(a.n_delivered, 0) > 0 THEN 'DELIVERED'
                WHEN COALESCE(a.n_pre_scope, 0) >= 2 THEN 'OPERATIVE'
                WHEN COALESCE(a.n_pre_any, 0) >= 2 THEN 'SERVICE_CLOSED'
                ELSE 'BELOW_MIN_MEMBERS' END AS g_reason
      FROM g CROSS JOIN trip t
      LEFT JOIN a ON a.g_id = g.id
      LEFT JOIN ct ON ct.g_id = g.id
      LEFT JOIN ca ON ca.g_id = g.id
  )
  SELECT st.id, st.seq, st.business_date, st.hora_ref, st.anchor_order_uid, st.created_at,
         st.created_by, st.dissolved_at, st.dissolved_by, st.g_state, st.g_reason,
         COALESCE(eff.uids, '{}'::uuid[]), COALESCE(eff.oids, '{}'::text[]), COALESCE(act.uids, '{}'::uuid[]),
         CASE WHEN st.g_state = 'DISSOLVED' THEN NULL
              -- W6.4: the REAL departure replaces the planned salida once the giro has
              -- departed. hora_ref (the operator-planned fact) is read-only here and is
              -- never overwritten -- it keeps flowing out on its own column.
              WHEN st.ct_trip_id IS NOT NULL THEN trip_authority.departed_hhmm_v1(st.ct_departed_at)
              WHEN giro_authority.hhmm_norm(st.hora_ref) IS NOT NULL THEN giro_authority.hhmm_norm(st.hora_ref)
              ELSE px.salida END,
         CASE WHEN st.g_state = 'DISSOLVED' THEN 'NONE'
              WHEN st.ct_trip_id IS NOT NULL THEN 'DEPARTED'
              WHEN giro_authority.hhmm_norm(st.hora_ref) IS NOT NULL THEN 'OPERATOR'
              WHEN px.salida IS NOT NULL THEN 'PROXY_MAX_FORNO'
              ELSE 'NONE' END
    FROM st
    LEFT JOIN LATERAL (
      SELECT array_agg(e.uid ORDER BY e.uid) AS uids, array_agg(e.oid ORDER BY e.uid) AS oids
        FROM (
          -- Canonical: the exact immutable frozen membership, every phase, unfiltered.
          SELECT ctm.uid, ctm.oid FROM ctm
           WHERE st.ct_trip_id IS NOT NULL AND ctm.g_id = st.id
          UNION ALL
          -- Legacy (no canonical trip): the pre-135 derivation, unchanged.
          SELECT kc.uid, kc.oid FROM kc
           WHERE st.ct_trip_id IS NULL AND kc.g_id = st.id
             AND (   (st.g_state = 'PLANNED' AND kc.pre_departure AND kc.in_scope)
                  OR (st.g_state = 'IN_TRIP' AND (kc.departed_live OR kc.delivered))
                  OR (st.g_state = 'DONE'    AND kc.delivered))
        ) AS e
    ) eff ON true
    LEFT JOIN LATERAL (
      SELECT array_agg(kc.uid ORDER BY kc.uid) AS uids
        FROM kc
       WHERE kc.g_id = st.id AND kc.present AND kc.estado IN ('EN_COCINA', 'LISTO', 'EN_ENTREGA')
    ) act ON true
    LEFT JOIN LATERAL (
      SELECT giro_authority.hhmm_norm(kc.forno_out) AS salida
        FROM kc
       WHERE kc.g_id = st.id AND kc.uid = ANY (COALESCE(eff.uids, '{}'::uuid[]))
         AND giro_authority.service_day_minutes(kc.forno_out) IS NOT NULL
       ORDER BY giro_authority.service_day_minutes(kc.forno_out) DESC
       LIMIT 1
    ) px ON true
$function$;

CREATE OR REPLACE FUNCTION giro_authority.giro_intents_one_shot_guard_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'GIRO_INTENT_APPEND_ONLY' USING ERRCODE = 'P0001';
  END IF;
  IF OLD.status <> 'PENDING' THEN
    RAISE EXCEPTION 'GIRO_INTENT_ALREADY_RESOLVED' USING ERRCODE = 'P0001';
  END IF;
  IF NEW.order_uid IS DISTINCT FROM OLD.order_uid
     OR NEW.target_kind IS DISTINCT FROM OLD.target_kind
     OR NEW.target_ref IS DISTINCT FROM OLD.target_ref
     OR NEW.target_giro_id IS DISTINCT FROM OLD.target_giro_id
     OR NEW.target_order_uid IS DISTINCT FROM OLD.target_order_uid
     OR NEW.target_fingerprint IS DISTINCT FROM OLD.target_fingerprint
     OR NEW.order_context IS DISTINCT FROM OLD.order_context
     OR NEW.captured_at IS DISTINCT FROM OLD.captured_at
     OR NEW.business_date IS DISTINCT FROM OLD.business_date
     OR NEW.actor IS DISTINCT FROM OLD.actor
     OR NEW.sv IS DISTINCT FROM OLD.sv THEN
    RAISE EXCEPTION 'GIRO_INTENT_CAPTURE_FACTS_IMMUTABLE' USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION giro_authority.hhmm_norm(p_value text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  v text;
  h integer;
  m integer;
BEGIN
  IF p_value IS NULL THEN RETURN NULL; END IF;
  v := btrim(p_value);
  IF v !~ '^[0-9]{1,2}:[0-9]{2}$' THEN RETURN NULL; END IF;
  h := split_part(v, ':', 1)::integer;
  m := split_part(v, ':', 2)::integer;
  IF h > 23 OR m > 59 THEN RETURN NULL; END IF;
  RETURN lpad(h::text, 2, '0') || ':' || lpad(m::text, 2, '0');
END $function$;

CREATE OR REPLACE FUNCTION giro_authority.insert_giro_v1(p_business_date date, p_hora_ref text, p_anchor uuid, p_actor text)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  v_seq     integer;
  v_id      text;
  v_attempt integer := 0;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('giro_authority.seq'), hashtext(p_business_date::text));
  SELECT COALESCE(max(mg.seq), 0) INTO v_seq FROM public.manual_giros mg WHERE mg.giro_day = p_business_date;
  LOOP
    v_attempt := v_attempt + 1;
    v_seq := v_seq + 1;
    v_id := 'mg_' || to_char(p_business_date, 'YYMMDD') || '_' || v_seq::text;
    INSERT INTO public.manual_giros (id, seq, giro_day, business_date, created_by, hora_ref, anchor_order_uid)
    VALUES (v_id, v_seq, p_business_date, p_business_date, btrim(p_actor), p_hora_ref, p_anchor)
    ON CONFLICT DO NOTHING;
    IF FOUND THEN RETURN v_id; END IF;
    IF v_attempt >= 5 THEN
      RAISE EXCEPTION 'GIRO_SEQ_ALLOCATION_FAILED' USING ERRCODE = 'P0001';
    END IF;
  END LOOP;
END $function$;

CREATE OR REPLACE FUNCTION giro_authority.intent_outcome_v1(p_intent giro_authority.giro_intents, p_replay boolean)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
  SELECT jsonb_build_object(
    'ok', true, 'code', p_intent.status, 'status', p_intent.status,
    'resolution_code', p_intent.resolution_code, 'resulting_giro_id', p_intent.resulting_giro_id,
    'target_kind', p_intent.target_kind, 'target_ref', p_intent.target_ref,
    'resolved_at', p_intent.resolved_at, 'replay', p_replay)
$function$;

CREATE OR REPLACE FUNCTION giro_authority.lock_orders_v1(p_order_uids uuid[])
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid;
BEGIN
  FOR v_uid IN SELECT DISTINCT x FROM unnest(p_order_uids) AS x WHERE x IS NOT NULL ORDER BY 1 LOOP
    PERFORM pg_advisory_xact_lock(hashtext('giro_authority.order'), hashtext(v_uid::text));
  END LOOP;
END $function$;

CREATE OR REPLACE FUNCTION giro_authority.member_refusal_v1(p_present boolean, p_estado text, p_delivery_type text, p_table_session uuid, p_in_active_trip boolean, p_session uuid, p_scope uuid[])
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
  SELECT CASE
    WHEN NOT COALESCE(p_present, false) THEN 'ORDER_NOT_FOUND'
    WHEN p_delivery_type IS DISTINCT FROM 'DOMICILIO' THEN 'NOT_DOMICILIO'
    WHEN p_table_session IS NOT NULL THEN 'TABLE_ORDER'
    WHEN COALESCE(p_in_active_trip, false) OR p_estado = 'EN_ENTREGA' THEN 'DEPARTED'
    WHEN p_estado IS NULL OR p_estado NOT IN ('EN_COCINA', 'LISTO') THEN 'NOT_OPERATIVE_STATE'
    WHEN NOT COALESCE(p_session = ANY (p_scope), false) THEN 'OUT_OF_SCOPE'
  END
$function$;

CREATE OR REPLACE FUNCTION giro_authority.order_effective_giro_v1(p_order_uid uuid, p_scope uuid[], p_trip jsonb)
 RETURNS text
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
  SELECT d.giro_id
    FROM giro_authority.giro_members gm
    CROSS JOIN LATERAL giro_authority.derive_giros_v1(ARRAY[gm.giro_id], p_scope, p_trip) d
   WHERE gm.order_uid = p_order_uid
     AND p_order_uid = ANY (d.effective_order_uids)
$function$;

CREATE OR REPLACE FUNCTION giro_authority.order_facts_v1(p_order_uids uuid[], p_trip jsonb)
 RETURNS TABLE(order_uid uuid, order_id text, present boolean, estado text, delivery_type text, table_session_id uuid, service_session_id uuid, business_date date, zona text, hora text, in_active_trip boolean)
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
  SELECT u.uid, o.id, (o.id IS NOT NULL), o.estado,
         -- language-guard: allow-legacy tipo_consegna is the existing ordenes column name, read-only here
         upper(COALESCE(o.tipo_consegna, '')),
         o.table_session_id, o.service_session_id, ss.business_date, o.zona, o.hora,
         COALESCE(o.id IN (SELECT jsonb_array_elements_text(CASE WHEN jsonb_typeof(p_trip->'order_ids') = 'array'
                                                                 THEN p_trip->'order_ids' ELSE '[]'::jsonb END)), false)
    FROM unnest(p_order_uids) AS u(uid)
    LEFT JOIN public.ordenes o ON o.order_uid = u.uid
    LEFT JOIN public.service_sessions ss ON ss.id = o.service_session_id
$function$;

CREATE OR REPLACE FUNCTION giro_authority.put_member_v1(p_order_uid uuid, p_giro_id text, p_actor text)
 RETURNS void
 LANGUAGE sql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
  INSERT INTO giro_authority.giro_members (order_uid, giro_id, created_by)
  VALUES (p_order_uid, p_giro_id, btrim(p_actor))
  ON CONFLICT (order_uid) DO UPDATE
    SET giro_id = EXCLUDED.giro_id, created_at = now(), created_by = EXCLUDED.created_by
$function$;

CREATE OR REPLACE FUNCTION giro_authority.refusal_v1(p_code text, p_detail jsonb)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
  SELECT jsonb_build_object('ok', false, 'code', p_code) || COALESCE(p_detail, '{}'::jsonb)
$function$;

CREATE OR REPLACE FUNCTION giro_authority.resolve_intent_v1(p_order_uid uuid, p_status text, p_phase text, p_code text, p_giro_id text, p_actor text, p_detail jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  v_row giro_authority.giro_intents;
BEGIN
  UPDATE giro_authority.giro_intents gi
     SET status = p_status, phase = p_phase, resolution_code = p_code, resulting_giro_id = p_giro_id,
         resolved_at = now(), resolved_by = btrim(p_actor), resolution_detail = p_detail
   WHERE gi.order_uid = p_order_uid AND gi.status = 'PENDING'
  RETURNING gi.* INTO v_row;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'GIRO_INTENT_CAS_LOST' USING ERRCODE = 'P0001';
  END IF;
  RETURN giro_authority.intent_outcome_v1(v_row, false);
END $function$;

CREATE OR REPLACE FUNCTION giro_authority.scope_valid_v1(p_scope uuid[])
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
  SELECT p_scope IS NOT NULL AND cardinality(p_scope) > 0 AND array_position(p_scope, NULL) IS NULL
$function$;

CREATE OR REPLACE FUNCTION giro_authority.service_day_minutes(p_value text)
 RETURNS integer
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  v text := giro_authority.hhmm_norm(p_value);
  h integer;
BEGIN
  IF v IS NULL THEN RETURN NULL; END IF;
  h := split_part(v, ':', 1)::integer;
  RETURN h * 60 + split_part(v, ':', 2)::integer + CASE WHEN h < 4 THEN 1440 ELSE 0 END;
END $function$;

CREATE OR REPLACE FUNCTION giro_authority.target_fingerprint_v1(p_kind text, p_giro_id text, p_anchor_uid uuid)
 RETURNS text
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
  SELECT encode(sha256(convert_to(
           CASE p_kind
             WHEN 'GIRO' THEN 'GIRO|' || COALESCE(p_giro_id, '') || '|' ||
               COALESCE((SELECT array_to_string(d.active_order_uids, ',')
                           FROM giro_authority.derive_giros_v1(ARRAY[p_giro_id], NULL, '{}'::jsonb) d), 'GONE')
             WHEN 'ANCHOR' THEN 'ANCHOR|' || COALESCE(p_anchor_uid::text, '') || '|' ||
               COALESCE(giro_authority.order_effective_giro_v1(p_anchor_uid, NULL, '{}'::jsonb), 'NONE')
           END, 'UTF8')), 'hex')
$function$;

CREATE OR REPLACE FUNCTION giro_authority.trip_facts_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  v_raw    text;
  v_ds     jsonb;
  v_active jsonb;
  v_giros  jsonb;
  v_canon  jsonb;
BEGIN
  -- W6.2 compatibility fallback (D-1): canonical trip_authority data wins whenever a
  -- canonical trip exists; this is temporary, not a second authority. Empty on
  -- staging today (nothing writes to trip_authority.trips yet), so this branch is
  -- provably a no-op for every current read -- proven by the harness's equivalence
  -- group, not merely asserted here.
  v_canon := trip_authority.trip_facts_canonical_v1();
  IF (v_canon->>'canonical_trip_exists')::boolean IS TRUE THEN
    RETURN v_canon - 'canonical_trip_exists';
  END IF;

  SELECT c.valore INTO v_raw FROM public.config c WHERE c.chiave = 'DRIVER_STATO';
  IF NOT FOUND OR v_raw IS NULL OR btrim(v_raw) = '' THEN
    RETURN jsonb_build_object('available', true, 'active', false, 'order_ids', '[]'::jsonb, 'giro_ids', '[]'::jsonb);
  END IF;
  BEGIN
    v_ds := v_raw::jsonb;
  EXCEPTION WHEN others THEN
    RETURN jsonb_build_object('available', false, 'reason', 'DRIVER_STATO_UNPARSEABLE');
  END;
  IF jsonb_typeof(v_ds) IS DISTINCT FROM 'object' THEN
    RETURN jsonb_build_object('available', false, 'reason', 'DRIVER_STATO_NOT_OBJECT');
  END IF;
  v_active := NULLIF(v_ds->'active_trip', 'null'::jsonb);
  IF v_active IS NULL THEN
    RETURN jsonb_build_object('available', true, 'active', false, 'order_ids', '[]'::jsonb, 'giro_ids', '[]'::jsonb);
  END IF;
  IF jsonb_typeof(v_active) <> 'object' THEN
    RETURN jsonb_build_object('available', false, 'reason', 'ACTIVE_TRIP_MALFORMED');
  END IF;
  IF (v_active->>'status') IS DISTINCT FROM 'ACTIVE' THEN
    RETURN jsonb_build_object('available', true, 'active', false, 'order_ids', '[]'::jsonb, 'giro_ids', '[]'::jsonb);
  END IF;
  IF jsonb_typeof(v_active->'order_ids') IS DISTINCT FROM 'array' THEN
    RETURN jsonb_build_object('available', false, 'reason', 'ACTIVE_TRIP_MALFORMED');
  END IF;
  v_giros := COALESCE(NULLIF(v_active->'manual_giro_ids', 'null'::jsonb), '[]'::jsonb);
  IF jsonb_typeof(v_giros) <> 'array' THEN
    RETURN jsonb_build_object('available', false, 'reason', 'ACTIVE_TRIP_MALFORMED');
  END IF;
  RETURN jsonb_build_object('available', true, 'active', true, 'trip_id', v_active->>'trip_id',
                            'order_ids', v_active->'order_ids', 'giro_ids', v_giros);
END $function$;

CREATE OR REPLACE FUNCTION public._ledger_write_payment(p_order_id text, p_payment_method text, p_reason text, p_by_actor text, p_by_role text, p_ip_hash text, p_meta jsonb, p_idem_scope_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_ord public.ordenes%ROWTYPE;
  v_existing public.order_financial_events%ROWTYPE;
  v_existing_basis public.order_financial_events%ROWTYPE;
  v_new public.order_financial_events%ROWTYPE;
  v_role text := p_by_role; v_method text; v_reason text; v_amount numeric(10,2);
  v_meta jsonb := COALESCE(p_meta, '{}'::jsonb);
  v_canon jsonb; v_digest text; v_replay_digest text;
BEGIN
  IF jsonb_typeof(v_meta) <> 'object' THEN RAISE EXCEPTION 'AUTH_META_INVALID' USING ERRCODE='22023'; END IF;
  IF length(v_meta::text) > 2048 THEN RAISE EXCEPTION 'AUTH_META_TOO_LARGE' USING ERRCODE='22023'; END IF;
  IF EXISTS (SELECT 1 FROM jsonb_object_keys(v_meta) k WHERE lower(k) = ANY (ARRAY[
       'pin','pin_hash','password','token','access_token','refresh_token','jwt','secret',
       'recovery_secret','authorization','api_key','apikey','bearer','cookie','raw_ip','confirmation']))
  THEN RAISE EXCEPTION 'AUTH_META_SENSITIVE_KEY' USING ERRCODE='22023'; END IF;
  IF p_ip_hash IS NULL OR btrim(p_ip_hash) = '' THEN RAISE EXCEPTION 'AUTH_IP_HASH_REQUIRED' USING ERRCODE='22023'; END IF;
  IF length(p_ip_hash) > 64 THEN RAISE EXCEPTION 'AUTH_IP_HASH_TOO_LONG' USING ERRCODE='22023'; END IF;
  IF p_idem_scope_key IS NULL OR char_length(p_idem_scope_key) < 8 OR char_length(p_idem_scope_key) > 128
     OR p_idem_scope_key !~ '^[A-Za-z0-9_-]+$'
  THEN RAISE EXCEPTION 'AUTH_IDEM_KEY_INVALID' USING ERRCODE='22023'; END IF;

  v_method := lower(btrim(COALESCE(p_payment_method, '')));
  IF v_method NOT IN ('efectivo','tarjeta','bizum') THEN RAISE EXCEPTION 'AUTH_METHOD_INVALID' USING ERRCODE='22023'; END IF;

  IF p_reason IS NOT NULL AND btrim(p_reason) = '' THEN RAISE EXCEPTION 'AUTH_REASON_BLANK' USING ERRCODE='22023'; END IF;
  v_reason := CASE WHEN p_reason IS NULL THEN NULL ELSE btrim(p_reason) END;

  IF p_by_actor IS NULL OR btrim(p_by_actor) = '' THEN RAISE EXCEPTION 'AUTH_ACTOR_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  IF v_role IS NULL OR btrim(v_role) = '' THEN RAISE EXCEPTION 'AUTH_FORBIDDEN_ROLE' USING ERRCODE='22023'; END IF;

  SELECT * INTO v_ord FROM public.ordenes WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'AUTH_ORDER_NOT_FOUND' USING ERRCODE='P0002'; END IF;

  -- E-2 (Economic Writer Hardening V1, migration 126). This legacy family is the only
  -- payment authority that incasses ordenes.totale instead of the canonical obligation
  -- (F-1/F-2 of the audit). Refuse BEFORE the idempotency replay lookup or anything else:
  --   (a) Mesa orders have their own canonical, per-line writer (mesa_post_payment_v1) and
  --       must never be reachable by an unfenced legacy path (N-5 blocker L-1);
  --   (b) any order whose canonical obligation has diverged from totale (a commercial
  --       adjustment or a cancellation happened) would be over- or under-charged by a
  --       totale-based collection.
  -- The normal, still-required rider path (non-Mesa, obligation == totale, no adjustment)
  -- is completely unaffected: both conditions below are false for it.
  IF v_ord.table_session_id IS NOT NULL THEN
    RAISE EXCEPTION 'LEGACY_COLLECTION_NOT_ALLOWED' USING ERRCODE='22023',
      DETAIL = format('order_id=%s is Mesa-owned (table_session_id=%s) -- legacy OFE-only collection is not permitted on table orders', p_order_id, v_ord.table_session_id);
  END IF;
  IF round(public.order_canonical_obligation_v1(v_ord.order_uid), 2) IS DISTINCT FROM round(v_ord.totale, 2) THEN
    RAISE EXCEPTION 'LEGACY_COLLECTION_NOT_ALLOWED' USING ERRCODE='22023',
      DETAIL = format('order_id=%s canonical_obligation=%s totale=%s -- legacy collection refused: the canonical obligation has diverged from the order total',
                       p_order_id, round(public.order_canonical_obligation_v1(v_ord.order_uid), 2), round(v_ord.totale, 2));
  END IF;

  -- Same-scope replay is based on immutable event snapshots, not mutable order fields.
  -- Scoped by service_session_id (IS NOT DISTINCT FROM handles the legacy NULL-session
  -- case) to match the partitioned unique indexes from 2026-07-26_two_service_identity.sql
  -- (order_financial_events_one_payment_session_uq / _legacy_uq): an order id/number
  -- recycled into a LATER service session must never match an EARLIER session's event.
  SELECT * INTO v_existing FROM public.order_financial_events
    WHERE order_id = p_order_id AND type = 'payment' AND idem_scope_key = p_idem_scope_key
      AND service_session_id IS NOT DISTINCT FROM v_ord.service_session_id;
  IF FOUND THEN
    IF v_existing.type <> 'payment'
       OR v_existing.amount IS NULL OR v_existing.amount <= 0
       OR v_existing.payment_method NOT IN ('efectivo','tarjeta','bizum')
       OR v_existing.legacy IS DISTINCT FROM false
       OR v_existing.prev_pay_state <> 'unpaid' OR v_existing.new_pay_state <> 'paid'
       OR v_existing.prev_estado IS DISTINCT FROM v_existing.new_estado
       OR v_existing.original_giro_id IS NOT NULL
    THEN RAISE EXCEPTION 'AUTH_IDEMPOTENCY_CONFLICT' USING ERRCODE='22023'; END IF;

    v_replay_digest := lower(encode(sha256(convert_to((jsonb_build_object(
      'order_id', p_order_id, 'type', 'payment', 'idem_scope_key', p_idem_scope_key,
      'by_actor', p_by_actor, 'by_role', v_role, 'reason', v_reason,
      'prev_estado', v_existing.prev_estado, 'new_estado', v_existing.new_estado,
      'prev_pay_state', v_existing.prev_pay_state, 'new_pay_state', v_existing.new_pay_state,
      'amount', v_existing.amount, 'payment_method', v_method, 'legacy', false))::text, 'UTF8')), 'hex'));
    IF v_existing.payload_digest = v_replay_digest THEN
      RETURN jsonb_build_object('event_id', v_existing.id, 'order_id', v_existing.order_id,
        'type', v_existing.type, 'amount', v_existing.amount, 'payment_method', v_existing.payment_method,
        'prev_estado', v_existing.prev_estado, 'new_estado', v_existing.new_estado,
        'prev_pay_state', v_existing.prev_pay_state, 'new_pay_state', v_existing.new_pay_state,
        'legacy', v_existing.legacy, 'idempotent', true, 'created_at', v_existing.created_at);
    END IF;
    -- A different actor/role/amount under the same key is a genuine conflict, never a
    -- silent second charge. This is what refuses a rider collection followed by an
    -- operator one on the same order.
    RAISE EXCEPTION 'AUTH_IDEMPOTENCY_CONFLICT' USING ERRCODE='22023';
  END IF;

  -- SERVER-DERIVED amount. No caller — Node, rider or operator — can supply or override it.
  v_amount := round(v_ord.totale, 2);
  IF v_amount IS NULL OR v_amount <= 0 THEN RAISE EXCEPTION 'AUTH_AMOUNT_INVALID' USING ERRCODE='22023'; END IF;

  -- Key order and value types are byte-significant: the digest is sha256 over the jsonb
  -- text. Reproduced EXACTLY as in 2026-07-19_b7_payment_basis_historical_replay_fix.sql.
  v_canon := jsonb_build_object(
    'order_id', p_order_id, 'type', 'payment', 'idem_scope_key', p_idem_scope_key,
    'by_actor', p_by_actor, 'by_role', v_role, 'reason', v_reason,
    'prev_estado', v_ord.estado, 'new_estado', v_ord.estado,
    'prev_pay_state', 'unpaid', 'new_pay_state', 'paid',
    'amount', v_amount, 'payment_method', v_method, 'legacy', false);
  v_digest := lower(encode(sha256(convert_to(v_canon::text, 'UTF8')), 'hex'));

  -- Same session-scoping as the replay check above: one basis per order PER SESSION, so a
  -- recycled order id/number starts a fresh basis in a later session instead of colliding
  -- with a since-archived one.
  SELECT * INTO v_existing_basis FROM public.order_financial_events
    WHERE order_id = p_order_id AND type IN ('payment','payment_imported')
      AND service_session_id IS NOT DISTINCT FROM v_ord.service_session_id
    ORDER BY created_at ASC LIMIT 1;
  IF FOUND THEN
    RAISE EXCEPTION 'AUTH_BASIS_EXISTS' USING ERRCODE='22023';
  END IF;

  IF v_ord.ya_pagado IS TRUE OR v_ord.cobrado IS TRUE THEN
    RAISE EXCEPTION 'AUTH_LEGACY_IMPORT_REQUIRED' USING ERRCODE='22023';
  END IF;

  INSERT INTO public.order_financial_events(
    order_id, type, amount, payment_method, reason, legacy, by_actor, by_role,
    prev_estado, new_estado, prev_pay_state, new_pay_state, original_giro_id,
    ip_hash, meta, idem_scope_key, payload_digest)
  VALUES (p_order_id, 'payment', v_amount, v_method, v_reason, false, p_by_actor, v_role,
    v_ord.estado, v_ord.estado, 'unpaid', 'paid', NULL,
    p_ip_hash, v_meta, p_idem_scope_key, v_digest)
  RETURNING * INTO v_new;

  UPDATE public.ordenes SET ya_pagado = true, cobrado = true, metodo_pago = v_method
   WHERE id = p_order_id;

  RETURN jsonb_build_object('event_id', v_new.id, 'order_id', v_new.order_id,
    'type', v_new.type, 'amount', v_new.amount, 'payment_method', v_new.payment_method,
    'prev_estado', v_new.prev_estado, 'new_estado', v_new.new_estado,
    'prev_pay_state', v_new.prev_pay_state, 'new_pay_state', v_new.new_pay_state,
    'legacy', v_new.legacy, 'idempotent', false, 'created_at', v_new.created_at);
END;
$function$;

CREATE OR REPLACE FUNCTION public.acquire_closeout_attempt(p_service_session_id uuid, p_actor text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_row public.service_closeout_attempts%ROWTYPE;
BEGIN
  IF p_service_session_id IS NULL THEN
    RETURN jsonb_build_object('ok',false,'code','INVALID_ARGUMENTS');
  END IF;
  IF p_actor IS NULL OR btrim(p_actor) = '' THEN
    RETURN jsonb_build_object('ok',false,'code','INVALID_ACTOR');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.service_sessions WHERE id = p_service_session_id) THEN
    RETURN jsonb_build_object('ok',false,'code','SERVICE_SESSION_NOT_FOUND');
  END IF;

  INSERT INTO public.service_closeout_attempts(service_session_id, status, created_by)
  VALUES (p_service_session_id, 'active', p_actor)
  ON CONFLICT (service_session_id) WHERE status = 'active' DO NOTHING
  RETURNING * INTO v_row;

  IF FOUND THEN
    RETURN jsonb_build_object('ok',true,'code','ACQUIRED','created',true,'attempt',to_jsonb(v_row));
  END IF;

  SELECT * INTO v_row FROM public.service_closeout_attempts
   WHERE service_session_id = p_service_session_id AND status = 'active';
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'code','ACQUIRE_RACE_UNRESOLVED');
  END IF;
  RETURN jsonb_build_object('ok',true,'code','ALREADY_ACTIVE','created',false,'attempt',to_jsonb(v_row));
END;
$function$;

