     WHERE workspace_id = p_ws AND user_id = auth.uid() AND status = 'active');
$function$;

CREATE OR REPLACE FUNCTION public.ladieci_schema_migrations_immutability_v1()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_existing_checksum text;
BEGIN
  IF TG_OP = 'INSERT' THEN
    SELECT checksum_sha256 INTO v_existing_checksum
      FROM public.ladieci_schema_migrations WHERE filename = NEW.filename;
    IF v_existing_checksum IS NOT NULL AND v_existing_checksum <> NEW.checksum_sha256 THEN
      RAISE EXCEPTION 'ladieci_schema_migrations: % already recorded with a DIFFERENT checksum (existing=%, attempted=%) -- a changed migration file must use a new filename, never overwrite', NEW.filename, v_existing_checksum, NEW.checksum_sha256
        USING ERRCODE = '23505';
    END IF;
    RETURN NEW;
  END IF;

  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'ladieci_schema_migrations is append-only: DELETE is forbidden (filename=%)', OLD.filename
      USING ERRCODE = '0A000';
  END IF;

  -- TG_OP = 'UPDATE' from here. The only lawful UPDATE is the single
  -- promotion transition bootstrapped_unverified -> verified; every
  -- immutable fact must be byte-identical to OLD.
  IF OLD.filename           IS DISTINCT FROM NEW.filename
     OR OLD.checksum_sha256 IS DISTINCT FROM NEW.checksum_sha256
     OR OLD.apply_order     IS DISTINCT FROM NEW.apply_order
     OR OLD.kind            IS DISTINCT FROM NEW.kind
     OR OLD.applied_at      IS DISTINCT FROM NEW.applied_at
     OR OLD.applied_by      IS DISTINCT FROM NEW.applied_by
  THEN
    RAISE EXCEPTION 'ladieci_schema_migrations: immutable fact changed on % (filename/checksum_sha256/apply_order/kind/applied_at/applied_by can never change)', OLD.filename
      USING ERRCODE = '0A000';
  END IF;

  IF OLD.verification_status = 'verified' THEN
    RAISE EXCEPTION 'ladieci_schema_migrations: % is already verified -- no further UPDATE is lawful (regression forbidden)', OLD.filename
      USING ERRCODE = '0A000';
  END IF;

  IF NEW.verification_status <> 'verified' THEN
    RAISE EXCEPTION 'ladieci_schema_migrations: % -- the only lawful UPDATE is bootstrapped_unverified -> verified', OLD.filename
      USING ERRCODE = '0A000';
  END IF;

  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.menu_set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.mesa_append_only_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  RAISE EXCEPTION 'MESA_APPEND_ONLY' USING ERRCODE='55000';
END
$function$;

CREATE OR REPLACE FUNCTION public.mesa_close_session_v1(p_workspace_id uuid, p_by_actor text, p_table_session_id uuid, p_force boolean DEFAULT false, p_confirm_over_collected boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE
  v_actor public.auth_actors%ROWTYPE; v_session public.table_sessions%ROWTYPE;
  v_total_cents bigint; v_paid_cents bigint; v_unpaid_cents bigint; v_over_cents bigint;
  v_now timestamptz := now(); v_forced_count integer := 0;
  v_incident jsonb;
BEGIN
  IF p_workspace_id IS NULL OR p_table_session_id IS NULL
     OR p_by_actor IS NULL OR btrim(p_by_actor) = ''
  THEN RAISE EXCEPTION 'MESA_INVALID_REQUEST' USING ERRCODE='22023'; END IF;
  PERFORM 1 FROM public.workspaces WHERE id = p_workspace_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'MESA_WORKSPACE_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  SELECT * INTO v_actor FROM public.auth_actors
   WHERE workspace_id = p_workspace_id AND actor = p_by_actor FOR UPDATE;
  IF NOT FOUND OR v_actor.active IS NOT TRUE
     OR v_actor.role NOT IN ('admin','operator','owner','cashier','waiter','legacy_operator')
  THEN RAISE EXCEPTION 'MESA_CLOSE_FORBIDDEN' USING ERRCODE='42501'; END IF;
  SELECT * INTO v_session FROM public.table_sessions
   WHERE id = p_table_session_id AND workspace_id = p_workspace_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'MESA_SESSION_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  IF v_session.status <> 'open' THEN RAISE EXCEPTION 'MESA_SESSION_NOT_OPEN' USING ERRCODE='55000'; END IF;
  SELECT COALESCE(round(sum(
      CASE WHEN EXISTS (SELECT 1 FROM public.order_obligations ob WHERE ob.order_uid = o.order_uid)
                OR EXISTS (SELECT 1 FROM public.table_order_lines l
                            WHERE l.table_session_id = v_session.id AND l.order_id = o.id)
           THEN public.order_canonical_obligation_v1(o.order_uid)
           ELSE 0::numeric END) * 100), 0)::bigint
    INTO v_total_cents
    FROM public.ordenes o
   WHERE o.table_session_id = v_session.id AND o.order_uid IS NOT NULL;
  SELECT COALESCE(round(sum(CASE WHEN t.kind='refund' THEN -a.amount ELSE a.amount END) * 100), 0)::bigint
    INTO v_paid_cents
    FROM public.payment_allocations a
    JOIN public.payment_transactions t ON t.id = a.payment_transaction_id
   WHERE t.table_session_id = v_session.id;
  v_unpaid_cents := GREATEST(0, v_total_cents - v_paid_cents);
  v_over_cents   := GREATEST(0, v_paid_cents - v_total_cents);
  IF v_unpaid_cents > 0 THEN RAISE EXCEPTION 'MESA_TABLE_NOT_SETTLED' USING ERRCODE='55000'; END IF;
  IF v_over_cents > 0 AND NOT COALESCE(p_confirm_over_collected, false) THEN
    RAISE EXCEPTION 'MESA_CLOSE_OVER_COLLECTED' USING ERRCODE='55000',
      DETAIL = format('overCollected=%s', v_over_cents / 100.0);
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.ordenes o
     WHERE o.table_session_id = v_session.id
       AND (o.estado IS NULL OR upper(o.estado) NOT IN (
         'RETIRADO','COMPLETADO','COMPLETATO','CANCELADO','CANCELLED','ANULADO','CHIUSO_FORZATO'  -- language-guard: allow-legacy COMPLETATO / CHIUSO_FORZATO are the pre-existing OPERATIONAL terminal-state literals mesa_close_session_v1 already checks; CREATE needs the whole body, restated verbatim, not new vocabulary
       ))
  ) THEN
    IF NOT p_force THEN RAISE EXCEPTION 'MESA_TABLE_HAS_ACTIVE_ORDERS' USING ERRCODE='55000'; END IF;
    WITH orphaned AS (
      SELECT o.id, o.estado AS current_estado
        FROM public.ordenes o
       WHERE o.table_session_id = v_session.id
         AND (o.estado IS NULL OR upper(o.estado) NOT IN (
           'RETIRADO','COMPLETADO','COMPLETATO','CANCELADO','CANCELLED','ANULADO','CHIUSO_FORZATO'  -- language-guard: allow-legacy COMPLETATO / CHIUSO_FORZATO are the same pre-existing OPERATIONAL terminal-state literals, restated verbatim for the same reason
         ))
       FOR UPDATE OF o
    ),
    logged AS (
      INSERT INTO public.orden_estado_logs(
        orden_id, numero_ordine, estado_from, estado_to, event_type,  -- language-guard: allow-legacy numero_ordine is the existing orden_estado_logs column name; CREATE needs the whole body, restated verbatim, not new vocabulary
        actor_type, actor_id, origin, metadata
      )
      SELECT t.id, t.id, t.current_estado, COALESCE(t.current_estado, 'EN_COCINA'), 'table_closed_forced',
        'operator', p_by_actor, 'mesa_close_session_force',
        jsonb_build_object('table_session_id', v_session.id,
          'reason', 'operator_forced_close_with_pending_kitchen_work')
      FROM orphaned t
      RETURNING 1
    )
    SELECT count(*) INTO v_forced_count FROM logged;
  END IF;
  IF v_over_cents > 0 THEN
    v_incident := public.create_service_incident(
      p_service_session_id => v_session.service_session_id,
      p_closeout_correlation_id => md5('mesa_close_over_collected:' || v_session.id::text)::uuid,
      p_incident_type => 'OVER_COLLECTED_AT_CLOSE',
      p_category => 'financial',
      p_severity => 'warning',
      p_detected_by => p_by_actor,
      p_entity_type => 'table_session',
      p_entity_id => v_session.id::text,
      p_table_session_id => v_session.id,
      p_financial_exposure_cents => v_over_cents::integer);
    IF COALESCE((v_incident->>'ok')::boolean, false) IS NOT TRUE THEN
      RAISE EXCEPTION 'MESA_CLOSE_INCIDENT_PERSISTENCE_FAILED' USING ERRCODE='55000',
        DETAIL = format('create_service_incident=%s', COALESCE(v_incident->>'code', '<null>'));
    END IF;
  END IF;
  UPDATE public.table_sessions SET
    status = 'closed', settled_at = v_now, closed_at = v_now,
    updated_at = v_now, updated_by = p_by_actor
  WHERE id = v_session.id;
  RETURN jsonb_build_object(
    'ok', true, 'tableId', v_session.table_id, 'status', 'closed',
    'forced', v_forced_count > 0, 'forcedOrderCount', v_forced_count,
    'obligation', v_total_cents / 100.0, 'netCollected', v_paid_cents / 100.0,
    'unpaid', v_unpaid_cents / 100.0, 'overCollected', v_over_cents / 100.0,
    'overCollectedAcknowledged', (v_over_cents > 0 AND COALESCE(p_confirm_over_collected, false)),
    'incidentId', CASE WHEN v_over_cents > 0 THEN v_incident->'incident'->>'id' ELSE NULL END
  );
END
$function$;

CREATE OR REPLACE FUNCTION public.mesa_complete_reservation_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF OLD.status = 'open' AND NEW.status = 'closed' THEN
    UPDATE public.table_reservations SET
      status = 'completed', completed_at = COALESCE(NEW.settled_at, now()),
      version = version + 1, updated_at = COALESCE(NEW.settled_at, now()),
      updated_by = COALESCE(NEW.updated_by, updated_by)
    WHERE table_session_id = NEW.id AND status = 'seated';
  END IF;
  RETURN NEW;
END
$function$;

CREATE OR REPLACE FUNCTION public.mesa_guard_covers_monotonic_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF OLD.covers_total IS NOT NULL AND (
    NEW.covers_total IS NULL OR NEW.covers_total < OLD.covers_total
  ) THEN
    RAISE EXCEPTION 'MESA_COVERS_IMMUTABLE' USING ERRCODE='55000';
  END IF;
  RETURN NEW;
END
$function$;

CREATE OR REPLACE FUNCTION public.mesa_guard_reserved_table_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF OLD.active IS TRUE AND NEW.active IS FALSE AND EXISTS (
    SELECT 1 FROM public.table_reservations r
     WHERE r.table_id = OLD.id AND r.workspace_id = OLD.workspace_id
       AND r.status = 'booked' AND r.reserved_at >= now()
  ) THEN
    RAISE EXCEPTION 'MESA_TABLE_HAS_RESERVATIONS' USING ERRCODE='55000';
  END IF;
  RETURN NEW;
END
$function$;

CREATE OR REPLACE FUNCTION public.mesa_open_reservation_v1(p_workspace_id uuid, p_by_actor text, p_reservation_id uuid, p_expected_version integer, p_service_session_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_actor public.auth_actors%ROWTYPE;
  v_reservation public.table_reservations%ROWTYPE;
  v_table public.restaurant_tables%ROWTYPE;
  v_service public.service_sessions%ROWTYPE;
  v_session public.table_sessions%ROWTYPE;
  v_now timestamptz := now();
  v_current_business_date date;
BEGIN
  IF p_workspace_id IS NULL OR p_reservation_id IS NULL OR p_service_session_id IS NULL
     OR p_by_actor IS NULL OR btrim(p_by_actor) = ''
     OR p_expected_version IS NULL OR p_expected_version < 1
  THEN RAISE EXCEPTION 'MESA_RESERVATION_INVALID' USING ERRCODE='22023'; END IF;

  PERFORM 1 FROM public.workspaces WHERE id = p_workspace_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'MESA_WORKSPACE_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  SELECT * INTO v_actor FROM public.auth_actors
   WHERE workspace_id = p_workspace_id AND actor = p_by_actor FOR UPDATE;
  IF NOT FOUND OR v_actor.active IS NOT TRUE OR v_actor.role NOT IN (
    'admin','operator','owner','cashier','legacy_operator'
  ) THEN RAISE EXCEPTION 'MESA_OPEN_FORBIDDEN' USING ERRCODE='42501'; END IF;

  SELECT * INTO v_service FROM public.service_sessions
   WHERE id = p_service_session_id FOR UPDATE;
  IF NOT FOUND OR v_service.status <> 'open' THEN
    RAISE EXCEPTION 'MESA_SERVICE_NOT_OPEN' USING ERRCODE='55000';
  END IF;

  IF v_service.lifecycle_semantics <> 'operational_service_v1' THEN
    v_current_business_date := (public.get_order_intake_context_v1()->>'businessDate')::date;
    IF v_current_business_date IS NULL THEN
      RAISE EXCEPTION 'MESA_BUSINESS_DATE_UNRESOLVED' USING ERRCODE='55000';
    END IF;
    IF v_service.business_date IS DISTINCT FROM v_current_business_date THEN
      RAISE EXCEPTION 'MESA_SERVICE_NOT_CURRENT' USING ERRCODE='55000';
    END IF;
  END IF;

  SELECT * INTO v_reservation FROM public.table_reservations
   WHERE id = p_reservation_id AND workspace_id = p_workspace_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'MESA_RESERVATION_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  IF v_reservation.status <> 'booked' THEN
    RAISE EXCEPTION 'MESA_RESERVATION_NOT_BOOKED' USING ERRCODE='55000';
  END IF;
  IF v_reservation.version <> p_expected_version THEN
    RAISE EXCEPTION 'MESA_RESERVATION_VERSION_CONFLICT' USING ERRCODE='40001';
  END IF;

  PERFORM 1 FROM public.table_sessions
   WHERE workspace_id = p_workspace_id AND table_id = v_reservation.table_id
     AND status = 'open'
   ORDER BY id FOR UPDATE;
  IF FOUND THEN RAISE EXCEPTION 'MESA_TABLE_ACCOUNT_OPEN' USING ERRCODE='23505'; END IF;

  SELECT * INTO v_table FROM public.restaurant_tables
   WHERE id = v_reservation.table_id AND workspace_id = p_workspace_id FOR UPDATE;
  IF NOT FOUND OR v_table.active IS NOT TRUE THEN
    RAISE EXCEPTION 'MESA_TABLE_UNAVAILABLE' USING ERRCODE='55000';
  END IF;

  INSERT INTO public.table_sessions(
    workspace_id, table_id, service_session_id, table_ref, status,
    covers_total, assigned_waiter_actor, created_by, updated_by
  ) VALUES (
    p_workspace_id, v_table.id, p_service_session_id, v_table.display_name, 'open',
    v_reservation.covers_total, CASE WHEN v_actor.role='waiter' THEN p_by_actor ELSE NULL END,
    p_by_actor, p_by_actor
  ) RETURNING * INTO v_session;

  IF v_actor.role='waiter' THEN
    INSERT INTO public.table_session_assignment_history(
      workspace_id, table_session_id, previous_waiter_actor, new_waiter_actor,
      by_actor, action, created_at
    ) VALUES (
      p_workspace_id, v_session.id, NULL, p_by_actor, p_by_actor, 'assigned', v_now
    );
  END IF;

  UPDATE public.table_reservations SET
    status = 'seated', table_session_id = v_session.id, seated_at = v_now,
    version = version + 1, updated_at = v_now, updated_by = p_by_actor
  WHERE id = v_reservation.id RETURNING * INTO v_reservation;

  RETURN jsonb_build_object(
    'ok', true, 'sessionId', v_session.id, 'reservationId', v_reservation.id,
    'reservationVersion', v_reservation.version, 'tableId', v_table.id,
    'tableNumber', v_table.table_number, 'displayName', v_table.display_name,
    'coversTotal', v_session.covers_total, 'status', v_session.status,
    'openedAt', v_session.opened_at
  );
END
$function$;

CREATE OR REPLACE FUNCTION public.mesa_open_session_v1(p_workspace_id uuid, p_by_actor text, p_table_id uuid, p_service_session_id uuid, p_covers_total integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_actor public.auth_actors%ROWTYPE;
  v_table public.restaurant_tables%ROWTYPE;
  v_service public.service_sessions%ROWTYPE;
  v_session public.table_sessions%ROWTYPE;
  v_current_business_date date;
BEGIN
  IF p_workspace_id IS NULL OR p_table_id IS NULL OR p_service_session_id IS NULL
     OR p_by_actor IS NULL OR btrim(p_by_actor) = ''
     OR (p_covers_total IS NOT NULL AND p_covers_total NOT BETWEEN 1 AND 99)
  THEN RAISE EXCEPTION 'MESA_INVALID_REQUEST' USING ERRCODE='22023'; END IF;

  PERFORM 1 FROM public.workspaces WHERE id = p_workspace_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'MESA_WORKSPACE_NOT_FOUND' USING ERRCODE='P0002'; END IF;

  SELECT * INTO v_actor FROM public.auth_actors
   WHERE workspace_id = p_workspace_id AND actor = p_by_actor FOR UPDATE;
  IF NOT FOUND OR v_actor.active IS NOT TRUE THEN
    RAISE EXCEPTION 'MESA_ACTOR_UNAVAILABLE' USING ERRCODE='42501';
  END IF;
  IF v_actor.role NOT IN ('admin','operator','owner','cashier','waiter','legacy_operator') THEN
    RAISE EXCEPTION 'MESA_OPEN_FORBIDDEN' USING ERRCODE='42501';
  END IF;

  SELECT * INTO v_service FROM public.service_sessions
   WHERE id = p_service_session_id FOR UPDATE;
  IF NOT FOUND OR v_service.status <> 'open' THEN
    RAISE EXCEPTION 'MESA_SERVICE_NOT_OPEN' USING ERRCODE='55000';
  END IF;

  IF v_service.lifecycle_semantics <> 'operational_service_v1' THEN
    v_current_business_date := (public.get_order_intake_context_v1()->>'businessDate')::date;
    IF v_current_business_date IS NULL THEN
      RAISE EXCEPTION 'MESA_BUSINESS_DATE_UNRESOLVED' USING ERRCODE='55000';
    END IF;
    IF v_service.business_date IS DISTINCT FROM v_current_business_date THEN
      RAISE EXCEPTION 'MESA_SERVICE_NOT_CURRENT' USING ERRCODE='55000';
    END IF;
  END IF;

  PERFORM 1 FROM public.table_sessions
   WHERE workspace_id = p_workspace_id AND table_id = p_table_id
     AND status = 'open'
   ORDER BY id FOR UPDATE;
  IF FOUND THEN
    RAISE EXCEPTION 'MESA_TABLE_ACCOUNT_OPEN' USING ERRCODE='23505';
  END IF;

  SELECT * INTO v_table FROM public.restaurant_tables
   WHERE id = p_table_id AND workspace_id = p_workspace_id FOR UPDATE;
  IF NOT FOUND OR v_table.active IS NOT TRUE THEN
    RAISE EXCEPTION 'MESA_TABLE_UNAVAILABLE' USING ERRCODE='55000';
  END IF;

  BEGIN
    INSERT INTO public.table_sessions(
      workspace_id, table_id, service_session_id, table_ref, status,
      covers_total, assigned_waiter_actor, created_by, updated_by
    ) VALUES (
      p_workspace_id, p_table_id, p_service_session_id, v_table.display_name, 'open',
      p_covers_total, CASE WHEN v_actor.role='waiter' THEN p_by_actor ELSE NULL END,
      p_by_actor, p_by_actor
    ) RETURNING * INTO v_session;
  EXCEPTION WHEN unique_violation THEN
    RAISE EXCEPTION 'MESA_TABLE_ACCOUNT_OPEN' USING ERRCODE='23505';
  END;

  IF v_actor.role='waiter' THEN
    INSERT INTO public.table_session_assignment_history(
      workspace_id, table_session_id, previous_waiter_actor, new_waiter_actor,
      by_actor, action, created_at
    ) VALUES (
      p_workspace_id, v_session.id, NULL, p_by_actor, p_by_actor, 'assigned', now()
    );
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'sessionId', v_session.id,
    'tableId', v_session.table_id,
    'tableNumber', v_table.table_number,
    'displayName', v_table.display_name,
    'coversTotal', v_session.covers_total,
    'status', v_session.status,
    'openedAt', v_session.opened_at
  );
END
$function$;

CREATE OR REPLACE FUNCTION public.mesa_post_commercial_adjustment_v1(p_workspace_id uuid, p_by_actor text, p_by_sid_hash text, p_table_session_id uuid, p_order_uid uuid, p_new_gross numeric, p_reason text, p_client_request_id text, p_request_hash text, p_expected_current_gross numeric DEFAULT NULL::numeric, p_meta jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_actor public.auth_actors%ROWTYPE; v_session public.table_sessions%ROWTYPE; v_ord public.ordenes%ROWTYPE;
  v_meta jsonb := COALESCE(p_meta, '{}'::jsonb); v_res jsonb; v_net numeric; v_current numeric;
BEGIN
  IF p_workspace_id IS NULL OR p_table_session_id IS NULL OR p_order_uid IS NULL
     OR p_by_actor IS NULL OR btrim(p_by_actor) = ''
     OR p_by_sid_hash IS NULL OR p_by_sid_hash !~ '^[0-9a-f]{64}$'
     OR p_client_request_id IS NULL OR char_length(p_client_request_id) NOT BETWEEN 8 AND 128
     OR p_client_request_id !~ '^[A-Za-z0-9_-]+$'
     OR p_request_hash IS NULL OR p_request_hash !~ '^[0-9a-f]{64}$'
     OR jsonb_typeof(v_meta) <> 'object' OR length(v_meta::text) > 2048
  THEN RAISE EXCEPTION 'MESA_ADJUSTMENT_INVALID' USING ERRCODE='22023'; END IF;
  IF EXISTS (SELECT 1 FROM jsonb_object_keys(v_meta) k WHERE lower(k) = ANY (ARRAY[
    'pin','pin_hash','password','token','access_token','refresh_token','jwt','secret',
    'authorization','api_key','apikey','bearer','cookie','raw_ip','sid','proof'
  ])) THEN RAISE EXCEPTION 'MESA_ADJUSTMENT_META_INVALID' USING ERRCODE='22023'; END IF;
  IF p_reason IS NULL OR btrim(p_reason) = '' THEN
    RAISE EXCEPTION 'MESA_ADJUSTMENT_REASON_REQUIRED' USING ERRCODE='22023'; END IF;
  PERFORM 1 FROM public.workspaces WHERE id = p_workspace_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'MESA_WORKSPACE_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  SELECT * INTO v_actor FROM public.auth_actors
   WHERE workspace_id = p_workspace_id AND actor = p_by_actor FOR UPDATE;
  IF NOT FOUND OR v_actor.active IS NOT TRUE OR v_actor.role NOT IN ('admin','owner')
  THEN RAISE EXCEPTION 'MESA_ADJUSTMENT_FORBIDDEN' USING ERRCODE='42501'; END IF;
  SELECT * INTO v_session FROM public.table_sessions
   WHERE id = p_table_session_id AND workspace_id = p_workspace_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'MESA_SESSION_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  SELECT * INTO v_ord FROM public.ordenes WHERE order_uid = p_order_uid FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'MESA_ADJUSTMENT_ORDER_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  IF v_ord.table_session_id IS DISTINCT FROM v_session.id THEN
    RAISE EXCEPTION 'MESA_ADJUSTMENT_ORDER_MISMATCH' USING ERRCODE='22023'; END IF;
  v_res := public.order_obligation_apply_adjustment_v1(
    p_order_uid, p_new_gross, 'manual', p_reason,
    p_by_actor, v_actor.role, p_client_request_id, p_request_hash, p_expected_current_gross);
  IF (v_res->>'changed')::boolean IS NOT TRUE AND (v_res->>'idempotent')::boolean IS NOT TRUE THEN
    RAISE EXCEPTION 'MESA_ADJUSTMENT_NO_CHANGE' USING ERRCODE='55000'; END IF;
  IF (v_res->>'idempotent')::boolean IS NOT TRUE THEN
    INSERT INTO public.auth_audit(event, target_actor, by_actor, meta)
    VALUES ('MESA_COMMERCIAL_ADJUSTMENT', NULL, p_by_actor, jsonb_build_object(
      'orderUid', p_order_uid, 'orderId', v_ord.id, 'tableSessionId', v_session.id,
      'previousObligation', v_res->'previousObligation', 'currentObligation', v_res->'currentObligation',
      'revision', v_res->'revision', 'cause', 'manual', 'bootstrapped', v_res->'bootstrapped',
      'clientRequestId', p_client_request_id, 'bySidHash', p_by_sid_hash, 'byRole', v_actor.role));
  END IF;
  SELECT COALESCE(sum(CASE WHEN t.kind = 'refund' THEN -a.amount ELSE a.amount END), 0)
    INTO v_net FROM public.payment_allocations a
    JOIN public.payment_transactions t ON t.id = a.payment_transaction_id
   WHERE a.order_id = v_ord.id AND t.table_session_id = v_session.id;
  v_current := (v_res->>'currentObligation')::numeric;
  RETURN v_res || jsonb_build_object(
    'orderId', v_ord.id, 'tableSessionId', v_session.id, 'netCollected', round(v_net, 2),
    'unpaid', GREATEST(0, round(v_current - v_net, 2)),
    'overCollected', GREATEST(0, round(v_net - v_current, 2)));
END;
$function$;

CREATE OR REPLACE FUNCTION public.mesa_post_payment_v1(p_workspace_id uuid, p_by_actor text, p_by_sid_hash text, p_table_session_id uuid, p_payment_method text, p_mode text, p_client_request_id text, p_request_hash text, p_amount numeric DEFAULT NULL::numeric, p_covers_settled integer DEFAULT NULL::integer, p_line_ids uuid[] DEFAULT NULL::uuid[], p_meta jsonb DEFAULT '{}'::jsonb, p_confirm_duplicate boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE
  v_actor public.auth_actors%ROWTYPE; v_session public.table_sessions%ROWTYPE;
  v_existing public.payment_transactions%ROWTYPE; v_tx public.payment_transactions%ROWTYPE;
  v_line record; v_order record; v_total_cents bigint; v_paid_cents bigint; v_outstanding_cents bigint;
  v_amount_cents bigint; v_to_allocate_cents bigint; v_line_remaining_cents bigint; v_allocation_cents bigint;
  v_remaining_covers integer; v_covers_settled integer; v_selected_count integer; v_selected_distinct integer;
  v_selected_matched integer; v_scope text; v_prev_state text; v_new_state text; v_order_total_cents bigint;
  v_order_paid_before_cents bigint; v_order_allocation_cents bigint; v_table_remaining_cents bigint;
  v_order_caps jsonb := '{}'::jsonb; v_order_cap_cents bigint; v_now timestamptz := now();
  v_meta jsonb := COALESCE(p_meta, '{}'::jsonb); v_duplicate_candidate boolean; v_receipt_service_id uuid;
BEGIN
  IF p_workspace_id IS NULL OR p_table_session_id IS NULL
     OR p_by_actor IS NULL OR btrim(p_by_actor) = ''
     OR p_by_sid_hash IS NULL OR p_by_sid_hash !~ '^[0-9a-f]{64}$'
     OR p_payment_method NOT IN ('efectivo','tarjeta','bizum')
     OR p_mode NOT IN ('full','equal_split','item_selection','custom_amount')
     OR p_client_request_id IS NULL OR length(p_client_request_id) NOT BETWEEN 8 AND 128
     OR p_client_request_id !~ '^[A-Za-z0-9_-]+$'
     OR p_request_hash IS NULL OR p_request_hash !~ '^[0-9a-f]{64}$'
     OR jsonb_typeof(v_meta) <> 'object' OR length(v_meta::text) > 2048
  THEN RAISE EXCEPTION 'MESA_PAYMENT_INVALID' USING ERRCODE='22023'; END IF;
  IF EXISTS (SELECT 1 FROM jsonb_object_keys(v_meta) k WHERE lower(k) = ANY (ARRAY[
    'pin','pin_hash','password','token','access_token','refresh_token','jwt','secret',
    'authorization','api_key','apikey','bearer','cookie','raw_ip','sid','proof'
  ])) THEN RAISE EXCEPTION 'MESA_PAYMENT_META_INVALID' USING ERRCODE='22023'; END IF;
  PERFORM 1 FROM public.workspaces WHERE id = p_workspace_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'MESA_WORKSPACE_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  SELECT * INTO v_actor FROM public.auth_actors
   WHERE workspace_id = p_workspace_id AND actor = p_by_actor FOR UPDATE;
  IF NOT FOUND OR v_actor.active IS NOT TRUE
     OR v_actor.role NOT IN ('admin','operator','owner','cashier','legacy_operator')
  THEN RAISE EXCEPTION 'MESA_PAYMENT_FORBIDDEN' USING ERRCODE='42501'; END IF;
  SELECT * INTO v_existing FROM public.payment_transactions
   WHERE workspace_id = p_workspace_id AND client_request_id = p_client_request_id;
  IF FOUND THEN
    IF v_existing.request_hash <> p_request_hash THEN
      RAISE EXCEPTION 'MESA_PAYMENT_IDEMPOTENCY_CONFLICT' USING ERRCODE='23505'; END IF;
    IF p_by_actor <> v_existing.by_actor THEN
      INSERT INTO public.auth_audit(event, target_actor, by_actor, meta)
      VALUES ('PAYMENT_REPLAY_DIFFERENT_ACTOR', v_existing.by_actor, p_by_actor,
        jsonb_build_object('transactionId', v_existing.id, 'clientRequestId', p_client_request_id,
          'originalBySidHash', v_existing.by_sid_hash, 'replayingBySidHash', p_by_sid_hash,
          'replayingRole', v_actor.role));
    END IF;
    RETURN jsonb_build_object('ok', true, 'idempotent', true, 'transactionId', v_existing.id,
      'amount', v_existing.amount, 'paymentMethod', v_existing.payment_method,
      'mode', v_existing.mode, 'coversSettled', v_existing.covers_settled);
  END IF;
  SELECT * INTO v_session FROM public.table_sessions
   WHERE id = p_table_session_id AND workspace_id = p_workspace_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'MESA_SESSION_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  IF v_session.status <> 'open' THEN RAISE EXCEPTION 'MESA_SESSION_NOT_OPEN' USING ERRCODE='55000'; END IF;
  IF v_session.covers_total IS NULL THEN RAISE EXCEPTION 'MESA_COVERS_NOT_SET' USING ERRCODE='55000'; END IF;

  -- PATCH B (Economic Writer Hardening V1, migration 126; closes N-5 blocker L-1). Lock
  -- every ordenes row of this table session BEFORE the first obligation/outstanding
  -- computation below, in the SAME deterministic order (id) every lock-ordering analysis
  -- in this codebase relies on, so the economic anchor cannot move between this snapshot
  -- and the allocation loop later in this function. Previously this writer only locked
  -- table_sessions and left `ordenes` unlocked until its own final UPDATE at the very end
  -- of the transaction -- exactly the race the legacy writer (E-2) and a raw editor (E-1)
  -- could win against. No payment formula, allocation rule, mode, idempotency key or
  -- refund/mirror semantic changes below this line.
  PERFORM 1 FROM public.ordenes o
   WHERE o.table_session_id = v_session.id
   ORDER BY o.id
   FOR UPDATE;

  SELECT COALESCE(round(sum(
      CASE WHEN EXISTS (SELECT 1 FROM public.order_obligations ob WHERE ob.order_uid = o.order_uid)
                OR EXISTS (SELECT 1 FROM public.table_order_lines l
                            WHERE l.table_session_id = v_session.id AND l.order_id = o.id)
           THEN public.order_canonical_obligation_v1(o.order_uid)
           ELSE 0::numeric END) * 100), 0)::bigint
    INTO v_total_cents
    FROM public.ordenes o
   WHERE o.table_session_id = v_session.id AND o.order_uid IS NOT NULL;
  SELECT COALESCE(round(sum(CASE WHEN t.kind='refund' THEN -a.amount ELSE a.amount END) * 100), 0)::bigint
    INTO v_paid_cents
    FROM public.payment_allocations a
    JOIN public.payment_transactions t ON t.id = a.payment_transaction_id
   WHERE t.table_session_id = v_session.id;
  v_outstanding_cents := GREATEST(0, v_total_cents - v_paid_cents);
  IF v_outstanding_cents <= 0 THEN RAISE EXCEPTION 'MESA_ALREADY_SETTLED' USING ERRCODE='55000'; END IF;
  SELECT v_session.covers_total - COALESCE(sum(
    CASE WHEN kind='payment' THEN covers_settled ELSE -covers_settled END
  ), 0)::integer INTO v_remaining_covers
    FROM public.payment_transactions WHERE table_session_id = v_session.id;
  v_remaining_covers := GREATEST(0, v_remaining_covers);
  IF p_mode = 'full' THEN
    v_amount_cents := v_outstanding_cents; v_covers_settled := v_remaining_covers;
  ELSIF p_mode = 'equal_split' THEN
    IF v_remaining_covers < 1 THEN RAISE EXCEPTION 'MESA_NO_COVERS_REMAINING' USING ERRCODE='55000'; END IF;
    v_amount_cents := ceil(v_outstanding_cents::numeric / v_remaining_covers)::bigint;
    v_covers_settled := 1;
  ELSIF p_mode = 'item_selection' THEN
    SELECT count(*), count(DISTINCT line_id) INTO v_selected_count, v_selected_distinct
      FROM unnest(COALESCE(p_line_ids, ARRAY[]::uuid[])) AS selected(line_id);
    IF v_selected_count < 1 OR v_selected_count <> v_selected_distinct THEN
      RAISE EXCEPTION 'MESA_LINE_SELECTION_INVALID' USING ERRCODE='22023'; END IF;
    SELECT count(*) INTO v_selected_matched
      FROM public.table_order_lines l
      JOIN public.ordenes o ON o.id=l.order_id AND o.table_session_id=l.table_session_id
     WHERE l.table_session_id=v_session.id AND l.id=ANY(p_line_ids)
       AND upper(COALESCE(o.estado,'')) NOT IN ('ANULADO','CANCELADO','CANCELLED');
    IF v_selected_matched <> v_selected_count THEN
      RAISE EXCEPTION 'MESA_LINE_SELECTION_INVALID' USING ERRCODE='22023'; END IF;
    SELECT COALESCE(sum(remaining_cents),0)::bigint INTO v_amount_cents FROM (
      SELECT GREATEST(0,
        round(l.net_amount * 100)::bigint - COALESCE(sum(
          CASE WHEN t.kind='refund' THEN -round(a.amount * 100)::bigint ELSE round(a.amount * 100)::bigint END
        ),0)
      ) AS remaining_cents
      FROM public.table_order_lines l
      JOIN public.ordenes o ON o.id=l.order_id AND o.table_session_id=l.table_session_id
      LEFT JOIN public.payment_allocations a ON a.table_order_line_id = l.id
      LEFT JOIN public.payment_transactions t ON t.id = a.payment_transaction_id
      WHERE l.table_session_id = v_session.id AND l.id = ANY(p_line_ids)
        AND upper(COALESCE(o.estado,'')) NOT IN ('ANULADO','CANCELADO','CANCELLED')
      GROUP BY l.id, l.net_amount
    ) selected;
    IF v_amount_cents <= 0 THEN RAISE EXCEPTION 'MESA_LINE_SELECTION_SETTLED' USING ERRCODE='55000'; END IF;
    v_covers_settled := COALESCE(p_covers_settled, 1);
  ELSE
    v_amount_cents := round(COALESCE(p_amount, 0) * 100)::bigint;
    v_covers_settled := COALESCE(p_covers_settled, 1);
  END IF;
  IF v_amount_cents <= 0 OR v_amount_cents > v_outstanding_cents
     OR v_covers_settled < 0 OR v_covers_settled > v_remaining_covers
  THEN RAISE EXCEPTION 'MESA_PAYMENT_AMOUNT_INVALID' USING ERRCODE='22023'; END IF;
  IF v_amount_cents = v_outstanding_cents THEN v_covers_settled := v_remaining_covers; END IF;
  SELECT EXISTS (
    SELECT 1 FROM public.payment_transactions pt
     WHERE pt.table_session_id = v_session.id
       AND pt.client_request_id <> p_client_request_id
       AND pt.kind = 'payment' AND pt.mode = p_mode
       AND pt.amount = (v_amount_cents / 100.0) AND pt.payment_method = p_payment_method
       AND pt.covers_settled = v_covers_settled
       AND pt.created_at > (v_now - interval '120 seconds')
  ) INTO v_duplicate_candidate;
  IF v_duplicate_candidate AND NOT p_confirm_duplicate THEN
    RAISE EXCEPTION 'MESA_POSSIBLE_DUPLICATE_PAYMENT' USING ERRCODE='55000';
  ELSIF v_duplicate_candidate AND p_confirm_duplicate THEN
    INSERT INTO public.auth_audit(event, target_actor, by_actor, meta)
    VALUES ('PAYMENT_DUPLICATE_CONFIRMED', NULL, p_by_actor,
      jsonb_build_object('tableSessionId', v_session.id, 'clientRequestId', p_client_request_id,
        'amount', v_amount_cents / 100.0, 'mode', p_mode, 'paymentMethod', p_payment_method,
        'coversSettled', v_covers_settled));
  END IF;
  SELECT ss.id INTO v_receipt_service_id
    FROM public.service_session_state sst
    JOIN public.service_sessions ss ON ss.id = sst.current_session_id AND ss.status = 'open'
   WHERE sst.singleton = true;
  INSERT INTO public.payment_transactions(
    workspace_id, table_session_id, service_session_id, kind, mode, amount,
    payment_method, covers_settled, by_actor, by_role, by_sid_hash,
    client_request_id, request_hash, meta, created_at
  ) VALUES (
    p_workspace_id, v_session.id, v_receipt_service_id, 'payment', p_mode,
    v_amount_cents / 100.0, p_payment_method, v_covers_settled,
    p_by_actor, v_actor.role, p_by_sid_hash, p_client_request_id,
    p_request_hash, v_meta, v_now
  ) RETURNING * INTO v_tx;
  v_to_allocate_cents := v_amount_cents;
  FOR v_line IN
    SELECT l.id, l.order_id, l.net_amount, o.order_uid,
      GREATEST(0, round(l.net_amount * 100)::bigint - COALESCE((
        SELECT sum(CASE WHEN t.kind='refund' THEN -round(a.amount*100)::bigint ELSE round(a.amount*100)::bigint END)
          FROM public.payment_allocations a
          JOIN public.payment_transactions t ON t.id=a.payment_transaction_id
         WHERE a.table_order_line_id=l.id
      ),0)) AS remaining_cents
    FROM public.table_order_lines l
    JOIN public.ordenes o ON o.id=l.order_id AND o.table_session_id=l.table_session_id
    WHERE l.table_session_id = v_session.id
      AND (p_mode <> 'item_selection' OR l.id = ANY(p_line_ids))
      AND upper(COALESCE(o.estado,'')) NOT IN ('ANULADO','CANCELADO','CANCELLED')
    ORDER BY l.created_at, l.order_id, l.source_line_index, l.unit_index, l.id
  LOOP
    EXIT WHEN v_to_allocate_cents <= 0;
    v_line_remaining_cents := v_line.remaining_cents;
    IF v_line_remaining_cents <= 0 THEN CONTINUE; END IF;
    IF NOT (v_order_caps ? v_line.order_id) THEN
      v_order_cap_cents := GREATEST(0,
        round(public.order_canonical_obligation_v1(v_line.order_uid) * 100)::bigint
        - COALESCE((
            SELECT sum(CASE WHEN t.kind='refund' THEN -round(a.amount*100)::bigint
                            ELSE round(a.amount*100)::bigint END)
              FROM public.payment_allocations a
              JOIN public.payment_transactions t ON t.id=a.payment_transaction_id
             WHERE a.order_id = v_line.order_id AND t.table_session_id = v_session.id
          ), 0));
      v_order_caps := v_order_caps || jsonb_build_object(v_line.order_id, v_order_cap_cents);
    END IF;
    v_order_cap_cents := (v_order_caps->>v_line.order_id)::bigint;
    IF v_order_cap_cents <= 0 THEN CONTINUE; END IF;
    v_allocation_cents := LEAST(v_to_allocate_cents, v_line_remaining_cents, v_order_cap_cents);
    IF v_allocation_cents <= 0 THEN CONTINUE; END IF;
    INSERT INTO public.payment_allocations(
      payment_transaction_id, table_order_line_id, order_id, amount, created_at
    ) VALUES (v_tx.id, v_line.id, v_line.order_id, v_allocation_cents / 100.0, v_now);
    v_to_allocate_cents := v_to_allocate_cents - v_allocation_cents;
    v_order_caps := jsonb_set(v_order_caps, ARRAY[v_line.order_id],
                              to_jsonb(v_order_cap_cents - v_allocation_cents));
  END LOOP;
  IF v_to_allocate_cents <> 0 THEN RAISE EXCEPTION 'MESA_ALLOCATION_MISMATCH' USING ERRCODE='23514'; END IF;
  FOR v_order IN
    SELECT a.order_id, round(sum(a.amount) * 100)::bigint AS allocated_cents,
      o.service_session_id AS obligation_service_session_id, o.order_uid
      FROM public.payment_allocations a
      JOIN public.ordenes o ON o.id = a.order_id AND o.table_session_id = v_session.id
     WHERE a.payment_transaction_id = v_tx.id
     GROUP BY a.order_id, o.service_session_id, o.order_uid ORDER BY a.order_id
  LOOP
    v_order_total_cents := round(public.order_canonical_obligation_v1(v_order.order_uid) * 100)::bigint;
    SELECT COALESCE(round(sum(CASE WHEN e.type='refund' THEN -e.amount ELSE e.amount END)*100),0)::bigint
      INTO v_order_paid_before_cents
      FROM public.order_financial_events e
     WHERE e.service_session_id=v_order.obligation_service_session_id AND e.order_id=v_order.order_id
       AND e.type IN ('payment','payment_imported','refund');
    v_order_allocation_cents := v_order.allocated_cents;
    v_prev_state := CASE
      WHEN v_order_paid_before_cents <= 0 THEN 'unpaid'
      WHEN v_order_paid_before_cents >= v_order_total_cents THEN 'paid'
      ELSE 'partially_paid' END;
    v_new_state := CASE
      WHEN v_order_paid_before_cents + v_order_allocation_cents >= v_order_total_cents THEN 'paid'
      ELSE 'partially_paid' END;
    v_scope := 'mesa_' || replace(v_tx.id::text, '-', '');
    INSERT INTO public.order_financial_events(
      order_id, type, amount, payment_method, reason, legacy, by_actor, by_role,
      prev_estado, new_estado, prev_pay_state, new_pay_state, original_giro_id,
      ip_hash, meta, idem_scope_key, payload_digest, service_session_id,
      event_service_session_id, payment_transaction_id, created_at
    )
    SELECT o.id, 'payment', v_order_allocation_cents / 100.0, p_payment_method,
      NULL, false, p_by_actor, v_actor.role, o.estado, o.estado,
      v_prev_state, v_new_state, NULL, NULL,
      jsonb_build_object('source','mesa','mode',p_mode,'transaction_id',v_tx.id),
      v_scope,
      encode(digest(concat_ws('|', o.id, v_tx.id::text, v_order_allocation_cents::text,
        p_payment_method, p_by_actor, p_request_hash), 'sha256'), 'hex'),
      v_session.service_session_id, v_receipt_service_id, v_tx.id, v_now
    FROM public.ordenes o WHERE o.id=v_order.order_id AND o.table_session_id=v_session.id;
  END LOOP;
  UPDATE public.ordenes o SET
    cobrado = calc.is_paid, ya_pagado = calc.is_paid,
    metodo_pago = CASE WHEN calc.is_paid THEN calc.method_projection ELSE COALESCE(o.metodo_pago,'') END
  FROM (
    SELECT src.id AS order_id,
      CASE WHEN src.obligation_cents <= 0 THEN src.collected_cents > 0
           ELSE src.collected_cents >= src.obligation_cents END AS is_paid,
      CASE WHEN src.method_count > 1 THEN 'MIXTO' ELSE src.method_max END AS method_projection
    FROM (
      SELECT o2.id,
        round(public.order_canonical_obligation_v1(o2.order_uid) * 100)::bigint AS obligation_cents,
        COALESCE((SELECT round(sum(CASE WHEN e.type='refund' THEN -e.amount ELSE e.amount END)*100)
                    FROM public.order_financial_events e
                   WHERE e.service_session_id=o2.service_session_id AND e.order_id=o2.id
                     AND e.type IN ('payment','payment_imported','refund')),0)::bigint AS collected_cents,
        (SELECT count(DISTINCT e.payment_method) FROM public.order_financial_events e
          WHERE e.service_session_id=o2.service_session_id AND e.order_id=o2.id
            AND e.type IN ('payment','payment_imported')) AS method_count,
        (SELECT max(e.payment_method) FROM public.order_financial_events e
          WHERE e.service_session_id=o2.service_session_id AND e.order_id=o2.id
            AND e.type IN ('payment','payment_imported')) AS method_max
      FROM public.ordenes o2
      WHERE o2.table_session_id = v_session.id AND o2.order_uid IS NOT NULL
    ) src
  ) calc
  WHERE o.id=calc.order_id AND o.table_session_id=v_session.id;
  v_table_remaining_cents := v_outstanding_cents - v_amount_cents;
  RETURN jsonb_build_object(
    'ok', true, 'idempotent', false, 'transactionId', v_tx.id,
    'amount', v_tx.amount, 'paymentMethod', v_tx.payment_method, 'mode', v_tx.mode,
    'coversSettled', v_tx.covers_settled,
    'coversRemaining', GREATEST(0, v_remaining_covers - v_tx.covers_settled),
    'tableTotal', v_total_cents / 100.0,
    'outstandingBefore', v_outstanding_cents / 100.0,
    'outstandingAfter', v_table_remaining_cents / 100.0,
    'overCollected', GREATEST(0, (v_paid_cents + v_amount_cents - v_total_cents)) / 100.0,
    'tableStatus', 'open'
  );
END
$function$;

CREATE OR REPLACE FUNCTION public.mesa_post_refund_v1(p_workspace_id uuid, p_by_actor text, p_by_sid_hash text, p_table_session_id uuid, p_original_transaction_id uuid, p_reason text, p_client_request_id text, p_request_hash text, p_amount numeric DEFAULT NULL::numeric, p_meta jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE
  v_actor public.auth_actors%ROWTYPE;
  v_session public.table_sessions%ROWTYPE;
  v_existing public.payment_transactions%ROWTYPE;
  v_original public.payment_transactions%ROWTYPE;
  v_refund_tx public.payment_transactions%ROWTYPE;
  v_alloc record;
  v_order record;
  v_now timestamptz := now();
  v_meta jsonb := COALESCE(p_meta, '{}'::jsonb);
  v_reason text;
  v_remaining_cents bigint;
  v_amount_cents bigint;
  v_to_reverse_cents bigint;
  v_take_cents bigint;
  v_order_total_cents bigint;
  v_order_paid_before_cents bigint;
  v_order_allocation_cents bigint;
  v_new_paid_cents bigint;
  v_prev_state text;
  v_new_state text;
  v_scope text;
  v_settlement text;
  v_receipt_service_id uuid;
  v_table_total_cents bigint;
  v_table_paid_cents bigint;
  v_table_outstanding_cents bigint;
  v_remaining_after_cents bigint;
  v_reversed_allocations jsonb;
  v_affected_orders jsonb;
  v_order_ids jsonb;
  v_audit_id bigint;
BEGIN
  IF p_workspace_id IS NULL OR p_table_session_id IS NULL OR p_original_transaction_id IS NULL
     OR p_by_actor IS NULL OR btrim(p_by_actor) = ''
     OR p_by_sid_hash IS NULL OR p_by_sid_hash !~ '^[0-9a-f]{64}$'
     OR p_client_request_id IS NULL OR length(p_client_request_id) NOT BETWEEN 8 AND 128
     OR p_client_request_id !~ '^[A-Za-z0-9_-]+$'
     OR p_request_hash IS NULL OR p_request_hash !~ '^[0-9a-f]{64}$'
     OR jsonb_typeof(v_meta) <> 'object' OR length(v_meta::text) > 2048
  THEN RAISE EXCEPTION 'MESA_REFUND_INVALID' USING ERRCODE='22023'; END IF;

  IF p_reason IS NULL OR btrim(p_reason) = '' THEN
    RAISE EXCEPTION 'MESA_REFUND_REASON_REQUIRED' USING ERRCODE='22023';
  END IF;
  v_reason := btrim(p_reason);

  IF p_amount IS NOT NULL AND p_amount <= 0 THEN
    RAISE EXCEPTION 'MESA_REFUND_AMOUNT_INVALID' USING ERRCODE='22023';
  END IF;

  IF EXISTS (SELECT 1 FROM jsonb_object_keys(v_meta) k WHERE lower(k) = ANY (ARRAY[
    'pin','pin_hash','password','token','access_token','refresh_token','jwt','secret',
    'authorization','api_key','apikey','bearer','cookie','raw_ip','sid','proof'
  ])) THEN RAISE EXCEPTION 'MESA_REFUND_META_INVALID' USING ERRCODE='22023'; END IF;

  PERFORM 1 FROM public.workspaces WHERE id = p_workspace_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'MESA_WORKSPACE_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  SELECT * INTO v_actor FROM public.auth_actors
   WHERE workspace_id = p_workspace_id AND actor = p_by_actor FOR UPDATE;
  -- REFUND_ROLES -- narrower than PAYMENT_ROLES on purpose: the role that takes
  -- money should not be the one that can silently return it (admin/owner only).
  IF NOT FOUND OR v_actor.active IS NOT TRUE
     OR v_actor.role NOT IN ('admin','owner')
  THEN RAISE EXCEPTION 'MESA_REFUND_FORBIDDEN' USING ERRCODE='42501'; END IF;

  -- Idempotency -- reuses payment_transactions_idempotency_uq (workspace_id,
  -- client_request_id) verbatim; refunds and payments share the same table and the
  -- same identity rule.
  SELECT * INTO v_existing FROM public.payment_transactions
   WHERE workspace_id = p_workspace_id AND client_request_id = p_client_request_id;
  IF FOUND THEN
    IF v_existing.request_hash <> p_request_hash THEN
      RAISE EXCEPTION 'MESA_REFUND_IDEMPOTENCY_CONFLICT' USING ERRCODE='23505';
    END IF;
    IF p_by_actor <> v_existing.by_actor THEN
      INSERT INTO public.auth_audit(event, target_actor, by_actor, meta)
      VALUES (
        'PAYMENT_REPLAY_DIFFERENT_ACTOR',
        v_existing.by_actor,
        p_by_actor,
        jsonb_build_object(
          'transactionId', v_existing.id,
          'clientRequestId', p_client_request_id,
          'originalBySidHash', v_existing.by_sid_hash,
          'replayingBySidHash', p_by_sid_hash,
          'replayingRole', v_actor.role
        )
      );
    END IF;
    SELECT (round(pt.amount*100)::bigint - COALESCE((
        SELECT sum(round(r.amount*100))::bigint FROM public.payment_transactions r
         WHERE r.kind='refund' AND r.reverses_transaction_id = pt.id
      ),0)) INTO v_remaining_after_cents
      FROM public.payment_transactions pt WHERE pt.id = v_existing.reverses_transaction_id;
    SELECT jsonb_agg(jsonb_build_object('tableOrderLineId', a.table_order_line_id,
        'orderId', a.order_id, 'amount', a.amount) ORDER BY a.created_at, a.id)
      INTO v_reversed_allocations
      FROM public.payment_allocations a WHERE a.payment_transaction_id = v_existing.id;
    SELECT jsonb_agg(jsonb_build_object('orderId', e.order_id, 'amount', e.amount,
        'prevPayState', e.prev_pay_state, 'newPayState', e.new_pay_state) ORDER BY e.order_id)
      INTO v_affected_orders
      FROM public.order_financial_events e WHERE e.payment_transaction_id = v_existing.id;
    RETURN jsonb_build_object(
      'ok', true, 'idempotent', true,
      'refundTransactionId', v_existing.id, 'reversesTransactionId', v_existing.reverses_transaction_id,
      'amount', v_existing.amount, 'paymentMethod', v_existing.payment_method,
      'refundableRemainingOnOriginal', COALESCE(v_remaining_after_cents,0) / 100.0,
      'reversedAllocations', COALESCE(v_reversed_allocations, '[]'::jsonb),
      'affectedOrders', COALESCE(v_affected_orders, '[]'::jsonb)
    );
  END IF;

  -- Closed tables are accepted deliberately (¬ßJ.2 of the contract): a refund never
  -- reopens a table session, never touches status/settled_at/closed_at.
  SELECT * INTO v_session FROM public.table_sessions
   WHERE id = p_table_session_id AND workspace_id = p_workspace_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'MESA_SESSION_NOT_FOUND' USING ERRCODE='P0002'; END IF;

  -- Lock the ORIGINAL transaction -- this is what makes concurrent over-refund
  -- attempts serialise and the second recompute a now-lower remaining balance.
  SELECT * INTO v_original FROM public.payment_transactions
   WHERE id = p_original_transaction_id AND workspace_id = p_workspace_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'MESA_TRANSACTION_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  IF v_original.kind <> 'payment' THEN RAISE EXCEPTION 'MESA_REFUND_NOT_REFUNDABLE' USING ERRCODE='55000'; END IF;
  -- CHECK-CENTRIC UNIVERSAL CASH V1 (migration 122) -- NULL-safe fix, owner-approved
  -- (¬ß5/¬ß28 of the brief). table_session_id is nullable as of this migration; the old
  -- `<>` evaluated to NULL (never TRUE) when the LEFT side was NULL, so a check-centric
  -- transaction (table_session_id IS NULL) could slip past this scope assertion. For
  -- every existing Mesa transaction (table_session_id always non-null) this is
  -- behaviorally IDENTICAL to the old comparison -- not a Mesa semantic change.
  IF v_original.table_session_id IS DISTINCT FROM p_table_session_id THEN
    RAISE EXCEPTION 'MESA_REFUND_TRANSACTION_MISMATCH' USING ERRCODE='55000';
  END IF;

  SELECT round(v_original.amount*100)::bigint - COALESCE((
      SELECT sum(round(r.amount*100))::bigint FROM public.payment_transactions r
       WHERE r.kind='refund' AND r.reverses_transaction_id = v_original.id
    ),0) INTO v_remaining_cents;
  IF v_remaining_cents <= 0 THEN RAISE EXCEPTION 'MESA_REFUND_ALREADY_FULL' USING ERRCODE='55000'; END IF;

  v_amount_cents := CASE WHEN p_amount IS NULL THEN v_remaining_cents ELSE round(p_amount*100)::bigint END;
  IF v_amount_cents <= 0 THEN RAISE EXCEPTION 'MESA_REFUND_AMOUNT_INVALID' USING ERRCODE='22023'; END IF;
  IF v_amount_cents > v_remaining_cents THEN RAISE EXCEPTION 'MESA_REFUND_EXCEEDS_REMAINING' USING ERRCODE='55000'; END IF;

  SELECT ss.id INTO v_receipt_service_id
    FROM public.service_session_state sst
    JOIN public.service_sessions ss ON ss.id = sst.current_session_id AND ss.status = 'open'
   WHERE sst.singleton = true;

  -- ¬ßH.4 -- record, don't claim: tarjeta/bizum note that La Dieci is RECORDING an
  -- externally executed return, never that it executed a bank/POS operation.
  v_settlement := CASE WHEN v_original.payment_method = 'efectivo' THEN 'drawer' ELSE 'external' END;

  -- The refund's payment_method is FORCED from the original -- no caller-supplied
  -- method exists in this signature (¬ß9 of the brief, frozen for V1).
  INSERT INTO public.payment_transactions(
    workspace_id, table_session_id, service_session_id, kind, mode, amount,
    payment_method, covers_settled, reverses_transaction_id, by_actor, by_role,
    by_sid_hash, client_request_id, request_hash, meta, created_at
  ) VALUES (
    p_workspace_id, v_session.id, v_session.service_session_id, 'refund', 'refund',
    v_amount_cents / 100.0, v_original.payment_method, 0, v_original.id,
    p_by_actor, v_actor.role, p_by_sid_hash, p_client_request_id, p_request_hash, v_meta, v_now
  ) RETURNING * INTO v_refund_tx;

  -- Reversal allocation loop -- reverses PT-A's OWN allocations, in
  -- mesa_post_payment_v1's own deterministic line order, capped per (PT-A, line) by
  -- what PT-A itself put there minus what prior refunds against PT-A already took.
  -- The operator never chooses lines; this loop is not a fresh allocation.
  v_to_reverse_cents := v_amount_cents;
  FOR v_alloc IN
    SELECT a.id, a.table_order_line_id, a.order_id, a.amount,
      round(a.amount * 100)::bigint - COALESCE((
        SELECT sum(round(ra.amount * 100))::bigint
          FROM public.payment_allocations ra
          JOIN public.payment_transactions rt ON rt.id = ra.payment_transaction_id
         WHERE rt.kind = 'refund' AND rt.reverses_transaction_id = v_original.id
           AND ra.table_order_line_id = a.table_order_line_id
      ), 0) AS reversible_cents
    FROM public.payment_allocations a
    JOIN public.table_order_lines l ON l.id = a.table_order_line_id
    WHERE a.payment_transaction_id = v_original.id
    ORDER BY l.created_at, l.order_id, l.source_line_index, l.unit_index, l.id
  LOOP
    EXIT WHEN v_to_reverse_cents <= 0;
    CONTINUE WHEN v_alloc.reversible_cents <= 0;
    v_take_cents := LEAST(v_to_reverse_cents, v_alloc.reversible_cents);
    INSERT INTO public.payment_allocations(
      payment_transaction_id, table_order_line_id, order_id, amount, created_at
    ) VALUES (v_refund_tx.id, v_alloc.table_order_line_id, v_alloc.order_id, v_take_cents / 100.0, v_now);
    v_to_reverse_cents := v_to_reverse_cents - v_take_cents;
  END LOOP;
  IF v_to_reverse_cents <> 0 THEN RAISE EXCEPTION 'MESA_REFUND_ALLOCATION_MISMATCH' USING ERRCODE='23514'; END IF;

  -- One order_financial_events row per order that actually received a reversal
  -- allocation -- never zero-amount rows, never an order untouched by this refund.
  FOR v_order IN
    SELECT a.order_id, round(sum(a.amount) * 100)::bigint AS allocated_cents,
      o.service_session_id AS obligation_service_session_id, o.estado
      FROM public.payment_allocations a
      JOIN public.ordenes o ON o.id = a.order_id
     WHERE a.payment_transaction_id = v_refund_tx.id
     GROUP BY a.order_id, o.service_session_id, o.estado ORDER BY a.order_id
  LOOP
    SELECT COALESCE(round(sum(net_amount)*100),0)::bigint INTO v_order_total_cents
      FROM public.table_order_lines WHERE table_session_id=v_session.id AND order_id=v_order.order_id;
    SELECT COALESCE(round(sum(CASE WHEN e.type='refund' THEN -e.amount ELSE e.amount END)*100),0)::bigint
      INTO v_order_paid_before_cents
      FROM public.order_financial_events e
     WHERE e.service_session_id=v_order.obligation_service_session_id AND e.order_id=v_order.order_id
       AND e.type IN ('payment','payment_imported','refund');
    v_order_allocation_cents := v_order.allocated_cents;
    v_prev_state := CASE
      WHEN v_order_paid_before_cents <= 0 THEN 'unpaid'
      WHEN v_order_paid_before_cents >= v_order_total_cents THEN 'paid'
      ELSE 'partially_paid' END;
    v_new_paid_cents := v_order_paid_before_cents - v_order_allocation_cents;
    v_new_state := CASE
      WHEN v_new_paid_cents <= 0 THEN 'unpaid'
      WHEN v_new_paid_cents >= v_order_total_cents THEN 'paid'
      ELSE 'partially_paid' END;
    v_scope := 'mesa_' || replace(v_refund_tx.id::text, '-', '');

    INSERT INTO public.order_financial_events(
      order_id, type, amount, payment_method, reason, legacy, by_actor, by_role,
      prev_estado, new_estado, prev_pay_state, new_pay_state, original_giro_id,
      ip_hash, meta, idem_scope_key, payload_digest, service_session_id,
      event_service_session_id, payment_transaction_id, created_at
    )
    SELECT o.id, 'refund', v_order_allocation_cents / 100.0, v_original.payment_method,
      v_reason, false, p_by_actor, v_actor.role, o.estado, o.estado,
      v_prev_state, v_new_state, NULL, NULL,
      jsonb_build_object('source','mesa','mode','refund','transaction_id',v_refund_tx.id,
        'reverses_transaction_id', v_original.id, 'settlement', v_settlement),
      v_scope,
      encode(digest(concat_ws('|', o.id, v_refund_tx.id::text, v_order_allocation_cents::text,
        v_original.payment_method, p_by_actor, p_request_hash), 'sha256'), 'hex'),
      v_session.service_session_id, v_receipt_service_id, v_refund_tx.id, v_now
    FROM public.ordenes o WHERE o.id=v_order.order_id AND o.table_session_id=v_session.id;
  END LOOP;

  -- Same projection expression mesa_post_payment_v1 uses -- one source of truth,
  -- copied verbatim rather than reimplemented. cobrado/ya_pagado/metodo_pago only;
  -- ordenes.refunded is never set (it means "fully refunded" in the LEGACY sense
  -- and would misstate a partial reversal).
  UPDATE public.ordenes o SET
    cobrado = calc.is_paid,
    ya_pagado = calc.is_paid,
    metodo_pago = CASE WHEN calc.is_paid THEN calc.method_projection ELSE COALESCE(o.metodo_pago,'') END
  FROM (
    SELECT l.order_id,
      COALESCE(sum(l.net_amount),0) <= COALESCE((
        SELECT sum(CASE WHEN e.type='refund' THEN -e.amount ELSE e.amount END)
          FROM public.order_financial_events e
         WHERE e.service_session_id=l.service_session_id AND e.order_id=l.order_id
           AND e.type IN ('payment','payment_imported','refund')
      ),0) AS is_paid,
      CASE WHEN (
        SELECT count(DISTINCT e.payment_method) FROM public.order_financial_events e
         WHERE e.service_session_id=l.service_session_id AND e.order_id=l.order_id
           AND e.type IN ('payment','payment_imported')
      ) > 1 THEN 'MIXTO' ELSE (
        SELECT max(e.payment_method) FROM public.order_financial_events e
         WHERE e.service_session_id=l.service_session_id AND e.order_id=l.order_id
           AND e.type IN ('payment','payment_imported')
      ) END AS method_projection
    FROM public.table_order_lines l WHERE l.table_session_id=v_session.id GROUP BY l.order_id, l.service_session_id
  ) calc
  WHERE o.id=calc.order_id AND o.table_session_id=v_session.id;

  v_remaining_after_cents := v_remaining_cents - v_amount_cents;

  SELECT COALESCE(round(sum(l.net_amount) * 100), 0)::bigint INTO v_table_total_cents
    FROM public.table_order_lines l
    JOIN public.ordenes o ON o.id = l.order_id AND o.table_session_id = l.table_session_id
   WHERE l.table_session_id = v_session.id
     AND upper(COALESCE(o.estado,'')) NOT IN ('ANULADO','CANCELADO','CANCELLED','CHIUSO_FORZATO'); -- language-guard: allow-legacy CHIUSO_FORZATO is the pre-existing terminal-estado literal mesa_post_payment_v1 already filters on, reproduced verbatim in this new writer's own table-outstanding query, not new vocabulary
  SELECT COALESCE(round(sum(CASE WHEN t.kind='refund' THEN -a.amount ELSE a.amount END) * 100), 0)::bigint
    INTO v_table_paid_cents
    FROM public.payment_allocations a
    JOIN public.payment_transactions t ON t.id = a.payment_transaction_id
   WHERE t.table_session_id = v_session.id;
  v_table_outstanding_cents := GREATEST(0, v_table_total_cents - v_table_paid_cents);

  SELECT jsonb_agg(jsonb_build_object('tableOrderLineId', a.table_order_line_id,
      'orderId', a.order_id, 'amount', a.amount) ORDER BY a.created_at, a.id)
    INTO v_reversed_allocations
    FROM public.payment_allocations a WHERE a.payment_transaction_id = v_refund_tx.id;
  SELECT jsonb_agg(jsonb_build_object('orderId', e.order_id, 'amount', e.amount,
      'prevPayState', e.prev_pay_state, 'newPayState', e.new_pay_state) ORDER BY e.order_id)
    INTO v_affected_orders
    FROM public.order_financial_events e WHERE e.payment_transaction_id = v_refund_tx.id;
  SELECT jsonb_agg(DISTINCT a.order_id) INTO v_order_ids
    FROM public.payment_allocations a WHERE a.payment_transaction_id = v_refund_tx.id;

  INSERT INTO public.auth_audit(event, target_actor, by_actor, meta)
  VALUES (
    'MESA_PAYMENT_REFUNDED',
    v_original.by_actor,
    p_by_actor,
    jsonb_build_object(
      'tableSessionId', v_session.id, 'originalTransactionId', v_original.id,
      'refundTransactionId', v_refund_tx.id, 'amount', v_amount_cents / 100.0,
      'paymentMethod', v_original.payment_method, 'reason', v_reason,
      'clientRequestId', p_client_request_id,
      'orderIds', COALESCE(v_order_ids, '[]'::jsonb),
      'refundableRemainingAfter', v_remaining_after_cents / 100.0
    )
  ) RETURNING id INTO v_audit_id;

  RETURN jsonb_build_object(
    'ok', true, 'idempotent', false,
    'refundTransactionId', v_refund_tx.id, 'reversesTransactionId', v_original.id,
    'amount', v_refund_tx.amount, 'paymentMethod', v_refund_tx.payment_method,
    'originalAmount', v_original.amount,
    'refundedTotalOnOriginal', (round(v_original.amount*100)::bigint - v_remaining_after_cents) / 100.0,
    'refundableRemainingOnOriginal', v_remaining_after_cents / 100.0,
    'reversedAllocations', COALESCE(v_reversed_allocations, '[]'::jsonb),
    'affectedOrders', COALESCE(v_affected_orders, '[]'::jsonb),
    'tableTotal', v_table_total_cents / 100.0,
    'tableOutstandingAfter', v_table_outstanding_cents / 100.0,
    'tableStatus', v_session.status,
    'auditId', v_audit_id
  );
END
$function$;

CREATE OR REPLACE FUNCTION public.mesa_prepare_table_order_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_session public.table_sessions%ROWTYPE;
  v_table public.restaurant_tables%ROWTYPE;
  v_item jsonb;
  v_items jsonb := '[]'::jsonb;
  v_source_line_id uuid;
  v_raw_id text;
  v_covers_total integer;
BEGIN
  IF NEW.table_session_id IS NULL THEN RETURN NEW; END IF;

  SELECT * INTO v_session FROM public.table_sessions
   WHERE id = NEW.table_session_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'MESA_SESSION_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  IF v_session.status <> 'open' THEN RAISE EXCEPTION 'MESA_SESSION_NOT_OPEN' USING ERRCODE='55000'; END IF;

  -- First comanda on a walk-in Mesa: require and lock in the real covers count.
  -- Any later comanda already has v_session.covers_total set, so this is a no-op
  -- and a stray table_covers_total_input value on that request is simply ignored.
  v_covers_total := v_session.covers_total;
  IF v_covers_total IS NULL THEN
    IF NEW.table_covers_total_input IS NULL
       OR NEW.table_covers_total_input NOT BETWEEN 1 AND 99
    THEN RAISE EXCEPTION 'MESA_COVERS_REQUIRED' USING ERRCODE='22023'; END IF;
    v_covers_total := NEW.table_covers_total_input;
  END IF;
  NEW.table_covers_total_input := NULL;

  SELECT * INTO v_table FROM public.restaurant_tables
   WHERE id = v_session.table_id FOR SHARE;
  IF NOT FOUND OR v_table.active IS NOT TRUE THEN
    RAISE EXCEPTION 'MESA_TABLE_UNAVAILABLE' USING ERRCODE='55000';
  END IF;

  IF jsonb_typeof(NEW.items) <> 'array' OR jsonb_array_length(NEW.items) = 0 THEN
    RAISE EXCEPTION 'MESA_ITEMS_REQUIRED' USING ERRCODE='22023';
  END IF;

  FOR v_item IN SELECT value FROM jsonb_array_elements(NEW.items)
  LOOP
    v_raw_id := v_item ->> 'lineId';
    BEGIN
      v_source_line_id := CASE WHEN v_raw_id IS NULL THEN gen_random_uuid() ELSE v_raw_id::uuid END;
    EXCEPTION WHEN invalid_text_representation THEN
      RAISE EXCEPTION 'MESA_LINE_ID_INVALID' USING ERRCODE='22023';
    END;
    v_items := v_items || jsonb_build_array(
      jsonb_set(v_item, '{lineId}', to_jsonb(v_source_line_id::text), true)
    );
  END LOOP;

  NEW.items := v_items;
  -- SLICE 3.1 FIX — removed: NEW.service_session_id := v_session.service_session_id;
  -- ordenes_assign_service_session (fires next, alphabetically) is now the
  -- SOLE writer of ordenes.service_session_id for every order, Mesa or not —
  -- see PART 1 header above for the full rationale.
  NEW.table_number_snapshot := v_table.table_number;
  NEW.table_name_snapshot := v_table.display_name;
  NEW.table_command_number := v_session.next_command_number;
  NEW.canal := 'BANCO';
  -- language-guard: allow-legacy tipo_consegna/RITIRO are the existing column assignment and value from mesa_prepare_table_order_v1's pre-3.1 body, restated verbatim because CREATE OR REPLACE requires the full function body, not new vocabulary
  NEW.tipo_consegna := 'RITIRO';
  NEW.delivery_fee := 0;

  -- Single UPDATE: covers (first comanda only) and the command-number advance
  -- commit together with the rest of this same INSERT statement/transaction.
  UPDATE public.table_sessions
     SET covers_total = v_covers_total,
         next_command_number = next_command_number + 1,
         updated_at = now()
   WHERE id = v_session.id;

  RETURN NEW;
END
$function$;

CREATE OR REPLACE FUNCTION public.mesa_release_empty_session_auto_v1(p_workspace_id uuid, p_table_session_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_session public.table_sessions%ROWTYPE;
  v_now timestamptz := now();
BEGIN
  IF p_workspace_id IS NULL OR p_table_session_id IS NULL THEN
    RAISE EXCEPTION 'MESA_INVALID_REQUEST' USING ERRCODE='22023';
  END IF;

  PERFORM 1 FROM public.workspaces WHERE id = p_workspace_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'MESA_WORKSPACE_NOT_FOUND' USING ERRCODE='P0002'; END IF;

  SELECT * INTO v_session FROM public.table_sessions
   WHERE id = p_table_session_id AND workspace_id = p_workspace_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'MESA_SESSION_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  IF v_session.status <> 'open' THEN RAISE EXCEPTION 'MESA_SESSION_NOT_OPEN' USING ERRCODE='55000'; END IF;
  IF v_session.covers_total IS NOT NULL THEN
    RAISE EXCEPTION 'MESA_TABLE_HAS_ORDERS' USING ERRCODE='55000';
  END IF;

  UPDATE public.table_sessions SET
    status = 'closed', settled_at = v_now, closed_at = v_now,
    updated_at = v_now, updated_by = 'system'
  WHERE id = v_session.id;

  RETURN jsonb_build_object('ok', true, 'tableId', v_session.table_id, 'status', 'closed');
END
$function$;

CREATE OR REPLACE FUNCTION public.mesa_release_empty_session_v1(p_workspace_id uuid, p_by_actor text, p_table_session_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_actor public.auth_actors%ROWTYPE;
  v_session public.table_sessions%ROWTYPE;
  v_now timestamptz := now();
BEGIN
  IF p_workspace_id IS NULL OR p_table_session_id IS NULL
     OR p_by_actor IS NULL OR btrim(p_by_actor) = ''
  THEN RAISE EXCEPTION 'MESA_INVALID_REQUEST' USING ERRCODE='22023'; END IF;

  PERFORM 1 FROM public.workspaces WHERE id = p_workspace_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'MESA_WORKSPACE_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  SELECT * INTO v_actor FROM public.auth_actors
   WHERE workspace_id = p_workspace_id AND actor = p_by_actor FOR UPDATE;
  IF NOT FOUND OR v_actor.active IS NOT TRUE
     OR v_actor.role NOT IN ('admin','operator','owner','cashier','waiter','legacy_operator')
  THEN RAISE EXCEPTION 'MESA_OPEN_FORBIDDEN' USING ERRCODE='42501'; END IF;

  SELECT * INTO v_session FROM public.table_sessions
   WHERE id = p_table_session_id AND workspace_id = p_workspace_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'MESA_SESSION_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  IF v_session.status <> 'open' THEN RAISE EXCEPTION 'MESA_SESSION_NOT_OPEN' USING ERRCODE='55000'; END IF;
  IF v_session.covers_total IS NOT NULL THEN
    RAISE EXCEPTION 'MESA_TABLE_HAS_ORDERS' USING ERRCODE='55000';
  END IF;

  UPDATE public.table_sessions SET
    status = 'closed', settled_at = v_now, closed_at = v_now,
    updated_at = v_now, updated_by = p_by_actor
  WHERE id = v_session.id;

  RETURN jsonb_build_object('ok', true, 'tableId', v_session.table_id, 'status', 'closed');
END
$function$;

CREATE OR REPLACE FUNCTION public.mesa_save_reservation_v1(p_workspace_id uuid, p_by_actor text, p_reservation_id uuid, p_table_id uuid, p_guest_name text, p_guest_phone text, p_covers_total integer, p_reserved_local_date text, p_reserved_local_time text, p_note text, p_expected_version integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_actor public.auth_actors%ROWTYPE;
  v_table public.restaurant_tables%ROWTYPE;
  v_reservation public.table_reservations%ROWTYPE;
  v_reserved_at timestamptz;
  v_date date;
  v_time time;
  v_guest_name text := btrim(COALESCE(p_guest_name,''));
  v_guest_phone text := NULLIF(btrim(COALESCE(p_guest_phone,'')), '');
  v_note text := NULLIF(btrim(COALESCE(p_note,'')), '');
BEGIN
  IF p_workspace_id IS NULL OR p_table_id IS NULL
     OR p_by_actor IS NULL OR btrim(p_by_actor) = ''
     OR v_guest_name = '' OR length(v_guest_name) > 120
     OR v_guest_name ~ '[[:cntrl:]]'
     OR (v_guest_phone IS NOT NULL AND (length(v_guest_phone) > 40 OR v_guest_phone ~ '[[:cntrl:]]'))
     OR p_covers_total IS NULL OR p_covers_total NOT BETWEEN 1 AND 99
     OR p_reserved_local_date IS NULL OR p_reserved_local_date !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
     OR p_reserved_local_time IS NULL OR p_reserved_local_time !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
     OR (v_note IS NOT NULL AND length(v_note) > 1000)
     OR (p_reservation_id IS NULL AND p_expected_version IS NOT NULL)
     OR (p_reservation_id IS NOT NULL AND (p_expected_version IS NULL OR p_expected_version < 1))
  THEN RAISE EXCEPTION 'MESA_RESERVATION_INVALID' USING ERRCODE='22023'; END IF;

  BEGIN
    v_date := p_reserved_local_date::date;
    v_time := p_reserved_local_time::time;
    IF to_char(v_date, 'YYYY-MM-DD') <> p_reserved_local_date
       OR to_char(v_time, 'HH24:MI') <> p_reserved_local_time
    THEN RAISE EXCEPTION 'invalid local timestamp'; END IF;
    v_reserved_at := (v_date + v_time) AT TIME ZONE 'Europe/Madrid';
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'MESA_RESERVATION_TIME_INVALID' USING ERRCODE='22023';
  END;

  PERFORM 1 FROM public.workspaces WHERE id = p_workspace_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'MESA_WORKSPACE_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  SELECT * INTO v_actor FROM public.auth_actors
   WHERE workspace_id = p_workspace_id AND actor = p_by_actor FOR UPDATE;
  IF NOT FOUND OR v_actor.active IS NOT TRUE OR v_actor.role NOT IN (
    'admin','operator','owner','cashier','waiter','shift_manager','legacy_operator'
  ) THEN RAISE EXCEPTION 'MESA_RESERVATION_FORBIDDEN' USING ERRCODE='42501'; END IF;

  IF p_reservation_id IS NOT NULL THEN
    SELECT * INTO v_reservation FROM public.table_reservations
     WHERE id = p_reservation_id AND workspace_id = p_workspace_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'MESA_RESERVATION_NOT_FOUND' USING ERRCODE='P0002'; END IF;
    IF v_reservation.status <> 'booked' THEN
      RAISE EXCEPTION 'MESA_RESERVATION_NOT_BOOKED' USING ERRCODE='55000';
    END IF;
    IF v_reservation.version <> p_expected_version THEN
      RAISE EXCEPTION 'MESA_RESERVATION_VERSION_CONFLICT' USING ERRCODE='40001';
    END IF;
  END IF;

  SELECT * INTO v_table FROM public.restaurant_tables
   WHERE id = p_table_id AND workspace_id = p_workspace_id FOR UPDATE;
  IF NOT FOUND OR v_table.active IS NOT TRUE THEN
    RAISE EXCEPTION 'MESA_TABLE_UNAVAILABLE' USING ERRCODE='55000';
  END IF;
  IF v_table.capacity IS NOT NULL AND p_covers_total > v_table.capacity THEN
    RAISE EXCEPTION 'MESA_RESERVATION_CAPACITY_EXCEEDED' USING ERRCODE='23514';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.table_reservations r
     WHERE r.workspace_id = p_workspace_id AND r.table_id = p_table_id
       AND r.status IN ('booked','seated')
       AND (p_reservation_id IS NULL OR r.id <> p_reservation_id)
       AND r.reserved_at < v_reserved_at + interval '120 minutes'
       AND r.reserved_at + make_interval(mins => r.duration_minutes) > v_reserved_at
  ) THEN RAISE EXCEPTION 'MESA_RESERVATION_OVERLAP' USING ERRCODE='23P01'; END IF;

  IF p_reservation_id IS NULL THEN
    INSERT INTO public.table_reservations(
      workspace_id, table_id, status, guest_name, guest_phone, covers_total,
      reserved_at, duration_minutes, note, version, created_by, updated_by
    ) VALUES (
      p_workspace_id, p_table_id, 'booked', v_guest_name, v_guest_phone,
      p_covers_total, v_reserved_at, 120, v_note, 1, p_by_actor, p_by_actor
    ) RETURNING * INTO v_reservation;
  ELSE
    UPDATE public.table_reservations SET
      table_id = p_table_id,
      guest_name = v_guest_name,
      guest_phone = v_guest_phone,
      covers_total = p_covers_total,
      reserved_at = v_reserved_at,
      note = v_note,
      version = version + 1,
      updated_at = now(),
      updated_by = p_by_actor
    WHERE id = p_reservation_id RETURNING * INTO v_reservation;
  END IF;

  RETURN jsonb_build_object(
    'ok', true, 'reservationId', v_reservation.id, 'version', v_reservation.version,
    'status', v_reservation.status, 'tableId', v_reservation.table_id,
    'tableNumber', v_table.table_number, 'guestName', v_reservation.guest_name,
    'guestPhone', v_reservation.guest_phone, 'coversTotal', v_reservation.covers_total,
    'reservedAt', v_reservation.reserved_at, 'durationMinutes', v_reservation.duration_minutes,
    'note', v_reservation.note
  );
END
$function$;

CREATE OR REPLACE FUNCTION public.mesa_save_table_v1(p_workspace_id uuid, p_by_actor text, p_table_id uuid, p_table_number integer, p_display_name text, p_capacity integer, p_position_x numeric, p_position_y numeric, p_shape text, p_active boolean, p_shape_preset text DEFAULT 'standard'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_actor public.auth_actors%ROWTYPE;
  v_table public.restaurant_tables%ROWTYPE;
  v_preset text := COALESCE(p_shape_preset, 'standard');
BEGIN
  IF p_table_number IS NULL OR p_table_number NOT BETWEEN 1 AND 999 OR p_display_name IS NULL
     OR btrim(p_display_name) = '' OR length(p_display_name) > 80
     OR p_position_x IS NULL OR p_position_x NOT BETWEEN 0 AND 100
     OR p_position_y IS NULL OR p_position_y NOT BETWEEN 0 AND 100
     OR p_shape NOT IN ('round','square','rectangle')
     OR NOT (
       (p_shape = 'round' AND v_preset = 'standard')
       OR (p_shape = 'square' AND v_preset = 'standard')
       OR (p_shape = 'rectangle' AND v_preset IN ('standard','long'))
     )
     OR (p_capacity IS NOT NULL AND p_capacity NOT BETWEEN 1 AND 99)
     OR p_active IS NULL
  THEN RAISE EXCEPTION 'MESA_TABLE_INVALID' USING ERRCODE='22023'; END IF;

  PERFORM 1 FROM public.workspaces WHERE id = p_workspace_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'MESA_WORKSPACE_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  SELECT * INTO v_actor FROM public.auth_actors
   WHERE workspace_id = p_workspace_id AND actor = p_by_actor FOR UPDATE;
  IF NOT FOUND OR v_actor.active IS NOT TRUE OR v_actor.role NOT IN ('admin','owner') THEN
    RAISE EXCEPTION 'MESA_LAYOUT_FORBIDDEN' USING ERRCODE='42501';
  END IF;

  IF p_table_id IS NULL THEN
    INSERT INTO public.restaurant_tables(
      workspace_id, table_number, display_name, capacity, position_x, position_y,
      shape, shape_preset, active, created_by, updated_by
    ) VALUES (
      p_workspace_id, p_table_number, btrim(p_display_name), p_capacity,
      p_position_x, p_position_y, p_shape, v_preset, p_active, p_by_actor, p_by_actor
    ) RETURNING * INTO v_table;
  ELSE
    PERFORM 1 FROM public.table_sessions
     WHERE workspace_id = p_workspace_id AND table_id = p_table_id
       AND status = 'open'
     ORDER BY id FOR UPDATE;
    SELECT * INTO v_table FROM public.restaurant_tables
     WHERE id = p_table_id AND workspace_id = p_workspace_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'MESA_TABLE_NOT_FOUND' USING ERRCODE='P0002'; END IF;
    IF p_active IS FALSE AND EXISTS (
      SELECT 1 FROM public.table_sessions
       WHERE workspace_id = p_workspace_id AND table_id = p_table_id AND status = 'open'
    ) THEN
      RAISE EXCEPTION 'MESA_TABLE_NOT_RELEASED' USING ERRCODE='55000';
    END IF;
    UPDATE public.restaurant_tables
       SET table_number = p_table_number, display_name = btrim(p_display_name),
           capacity = p_capacity, position_x = p_position_x, position_y = p_position_y,
           shape = p_shape, shape_preset = v_preset, active = p_active,
           updated_at = now(), updated_by = p_by_actor
     WHERE id = p_table_id RETURNING * INTO v_table;
  END IF;

  RETURN jsonb_build_object(
    'ok', true, 'tableId', v_table.id, 'tableNumber', v_table.table_number,
    'displayName', v_table.display_name, 'capacity', v_table.capacity,
    'positionX', v_table.position_x, 'positionY', v_table.position_y,
    'shape', v_table.shape, 'shapePreset', v_table.shape_preset, 'active', v_table.active
  );
END
$function$;

CREATE OR REPLACE FUNCTION public.mesa_set_reservation_status_v1(p_workspace_id uuid, p_by_actor text, p_reservation_id uuid, p_expected_version integer, p_status text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_actor public.auth_actors%ROWTYPE;
  v_reservation public.table_reservations%ROWTYPE;
  v_now timestamptz := now();
BEGIN
  IF p_workspace_id IS NULL OR p_reservation_id IS NULL
     OR p_by_actor IS NULL OR btrim(p_by_actor) = ''
     OR p_expected_version IS NULL OR p_expected_version < 1
     OR p_status NOT IN ('cancelled','no_show')
  THEN RAISE EXCEPTION 'MESA_RESERVATION_INVALID' USING ERRCODE='22023'; END IF;

  PERFORM 1 FROM public.workspaces WHERE id = p_workspace_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'MESA_WORKSPACE_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  SELECT * INTO v_actor FROM public.auth_actors
   WHERE workspace_id = p_workspace_id AND actor = p_by_actor FOR UPDATE;
  IF NOT FOUND OR v_actor.active IS NOT TRUE OR v_actor.role NOT IN (
    'admin','operator','owner','cashier','waiter','shift_manager','legacy_operator'
  ) THEN RAISE EXCEPTION 'MESA_RESERVATION_FORBIDDEN' USING ERRCODE='42501'; END IF;

  SELECT * INTO v_reservation FROM public.table_reservations
   WHERE id = p_reservation_id AND workspace_id = p_workspace_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'MESA_RESERVATION_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  IF v_reservation.status <> 'booked' THEN
    RAISE EXCEPTION 'MESA_RESERVATION_NOT_BOOKED' USING ERRCODE='55000';
  END IF;
  IF v_reservation.version <> p_expected_version THEN
    RAISE EXCEPTION 'MESA_RESERVATION_VERSION_CONFLICT' USING ERRCODE='40001';
  END IF;

  UPDATE public.table_reservations SET
    status = p_status,
    version = version + 1,
    updated_at = v_now,
    updated_by = p_by_actor,
    cancelled_at = CASE WHEN p_status = 'cancelled' THEN v_now ELSE NULL END,
    no_show_at = CASE WHEN p_status = 'no_show' THEN v_now ELSE NULL END
  WHERE id = p_reservation_id RETURNING * INTO v_reservation;

  RETURN jsonb_build_object(
    'ok', true, 'reservationId', v_reservation.id,
    'version', v_reservation.version, 'status', v_reservation.status
  );
END
$function$;

CREATE OR REPLACE FUNCTION public.mesa_set_session_covers_v1(p_workspace_id uuid, p_by_actor text, p_table_session_id uuid, p_covers_total integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_actor public.auth_actors%ROWTYPE;
  v_session public.table_sessions%ROWTYPE;
  v_now timestamptz := now();
BEGIN
  IF p_workspace_id IS NULL OR p_table_session_id IS NULL
     OR p_by_actor IS NULL OR btrim(p_by_actor) = ''
     OR p_covers_total IS NULL OR p_covers_total NOT BETWEEN 1 AND 99
  THEN RAISE EXCEPTION 'MESA_INVALID_REQUEST' USING ERRCODE='22023'; END IF;

  PERFORM 1 FROM public.workspaces WHERE id = p_workspace_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'MESA_WORKSPACE_NOT_FOUND' USING ERRCODE='P0002'; END IF;

  SELECT * INTO v_actor FROM public.auth_actors
   WHERE workspace_id = p_workspace_id AND actor = p_by_actor FOR UPDATE;
  IF NOT FOUND OR v_actor.active IS NOT TRUE THEN
    RAISE EXCEPTION 'MESA_ACTOR_UNAVAILABLE' USING ERRCODE='42501';
  END IF;
  IF v_actor.role NOT IN ('admin','operator','owner','cashier','waiter','legacy_operator') THEN
    RAISE EXCEPTION 'MESA_OPEN_FORBIDDEN' USING ERRCODE='42501';
  END IF;

  SELECT * INTO v_session FROM public.table_sessions
   WHERE id = p_table_session_id AND workspace_id = p_workspace_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'MESA_SESSION_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  IF v_session.status <> 'open' THEN RAISE EXCEPTION 'MESA_SESSION_NOT_OPEN' USING ERRCODE='55000'; END IF;
  IF v_session.assigned_waiter_actor IS NOT NULL AND v_actor.role = 'waiter'
     AND v_session.assigned_waiter_actor <> p_by_actor
  THEN RAISE EXCEPTION 'MESA_WAITER_NOT_ASSIGNED' USING ERRCODE='42501'; END IF;

  -- The pre-existing monotonic guard trigger (table_sessions_guard_covers_
  -- monotonic_v1, unchanged by this migration) makes this UPDATE safe by
  -- construction: raising an already-set count to the same or a higher
  -- value always succeeds (a natural retry/re-select of the same or a
  -- larger party is a no-op or a legitimate correction); attempting to
  -- shrink or null an already-set count is rejected there
  -- (MESA_COVERS_IMMUTABLE), never here.
  UPDATE public.table_sessions
     SET covers_total = p_covers_total, updated_at = v_now, updated_by = p_by_actor
   WHERE id = v_session.id
  RETURNING * INTO v_session;

  RETURN jsonb_build_object(
    'ok', true,
    'sessionId', v_session.id,
    'tableId', v_session.table_id,
    'coversTotal', v_session.covers_total,
    'status', v_session.status
  );
END
$function$;

CREATE OR REPLACE FUNCTION public.mesa_singleton_workspace_v1()
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_id uuid; v_n integer;
BEGIN
  SELECT count(*) INTO v_n FROM public.workspaces;
  IF v_n <> 1 THEN
    RAISE EXCEPTION 'MESA_WORKSPACE_AMBIGUOUS' USING ERRCODE='P0001',
      DETAIL = format('workspaces=%s; order_entity_anchor needs an explicit workspace', v_n);
  END IF;
  SELECT id INTO v_id FROM public.workspaces;
  RETURN v_id;
END $function$;

CREATE OR REPLACE FUNCTION public.mesa_snapshot_order_lines_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_session public.table_sessions%ROWTYPE;
  v_item jsonb;
  v_line_index integer;
  v_quantity integer;
  v_unit_index integer;
  v_total_units integer := 0;
  v_seen_units integer := 0;
  v_source_line_id uuid;
  v_description text;
  v_unit_gross_cents bigint;
  v_total_gross_cents bigint := 0;
  v_gross_remaining_cents bigint;
  v_net_total_cents bigint;
  v_net_remaining_cents bigint;
  v_unit_net_cents bigint;
BEGIN
  IF NEW.table_session_id IS NULL THEN RETURN NEW; END IF;

  SELECT * INTO v_session FROM public.table_sessions WHERE id = NEW.table_session_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'MESA_SESSION_NOT_FOUND' USING ERRCODE='P0002'; END IF;

  FOR v_item, v_line_index IN
    SELECT value, ordinality::integer FROM jsonb_array_elements(NEW.items) WITH ORDINALITY
  LOOP
    v_quantity := COALESCE((v_item ->> 'quantity')::integer, (v_item ->> 'q')::integer, 1);
    v_unit_gross_cents := round(COALESCE(
      (v_item ->> 'finalUnitPrice')::numeric,
      (v_item ->> 'p')::numeric
    ) * 100)::bigint;
    IF v_quantity < 1 OR v_unit_gross_cents < 0 THEN
      RAISE EXCEPTION 'MESA_ITEM_SNAPSHOT_INVALID' USING ERRCODE='22023';
    END IF;
    v_total_units := v_total_units + v_quantity;
    v_total_gross_cents := v_total_gross_cents + (v_quantity * v_unit_gross_cents);
  END LOOP;

  v_net_total_cents := round(COALESCE(NEW.totale, 0) * 100)::bigint;
  IF v_total_units < 1 OR v_total_gross_cents <= 0 OR v_net_total_cents < 0
     OR v_net_total_cents > v_total_gross_cents THEN
    RAISE EXCEPTION 'MESA_ORDER_TOTAL_INVALID' USING ERRCODE='22023';
  END IF;
  v_net_remaining_cents := v_net_total_cents;
  v_gross_remaining_cents := v_total_gross_cents;

  FOR v_item, v_line_index IN
    SELECT value, ordinality::integer FROM jsonb_array_elements(NEW.items) WITH ORDINALITY
  LOOP
    v_quantity := COALESCE((v_item ->> 'quantity')::integer, (v_item ->> 'q')::integer, 1);
    v_source_line_id := (v_item ->> 'lineId')::uuid;
    v_description := left(COALESCE(NULLIF(v_item ->> 'fantasyName',''), NULLIF(v_item ->> 'n',''), NULLIF(v_item ->> 'classicName',''), 'Producto'), 240);
    v_unit_gross_cents := round(COALESCE(
      (v_item ->> 'finalUnitPrice')::numeric,
      (v_item ->> 'p')::numeric
    ) * 100)::bigint;

    FOR v_unit_index IN 1..v_quantity
    LOOP
      v_seen_units := v_seen_units + 1;
      IF v_seen_units = v_total_units THEN
        v_unit_net_cents := v_net_remaining_cents;
      ELSE
        v_unit_net_cents := floor(
          (v_net_remaining_cents::numeric * v_unit_gross_cents::numeric) / v_gross_remaining_cents::numeric
        )::bigint;
      END IF;
      v_net_remaining_cents := v_net_remaining_cents - v_unit_net_cents;
      v_gross_remaining_cents := v_gross_remaining_cents - v_unit_gross_cents;

      INSERT INTO public.table_order_lines(
        workspace_id, table_session_id, service_session_id, order_id,
        source_line_id, source_line_index, unit_index, description,
        product_snapshot, gross_amount, discount_amount, net_amount
      ) VALUES (
        v_session.workspace_id, v_session.id, NEW.service_session_id, NEW.id,
        v_source_line_id, v_line_index, v_unit_index, v_description,
        v_item, v_unit_gross_cents / 100.0,
        (v_unit_gross_cents - v_unit_net_cents) / 100.0,
        v_unit_net_cents / 100.0
      );
    END LOOP;
  END LOOP;

  RETURN NEW;
END
$function$;

CREATE OR REPLACE FUNCTION public.open_operational_service_v1(p_opened_by text, p_open_reason text, p_source text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_bd_state public.business_day_lifecycle_state%ROWTYPE;
  v_ss_state public.service_session_state%ROWTYPE;
  v_day      public.business_days%ROWTYPE;
  v_active   public.service_sessions%ROWTYPE;
  v_has_any  boolean;
  v_new      public.service_sessions%ROWTYPE;
BEGIN
  IF p_opened_by IS NULL OR btrim(p_opened_by) = '' THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_ACTOR');
  END IF;
  -- G-1 — three reasons, three distinct meanings, never interchangeable:
  --   first_open_of_business_day    the Business Day has NEVER had a service
  --   next_service_of_business_day  it has, none is active, and real
  --                                 operational activity is resuming by
  --                                 itself (no human decision involved)
  --   explicit_reopen               a deliberate, human-triggered reopen
  -- Only the middle one is new. The other two keep their exact F-6/F-9
  -- semantics and their exact guards below.
  IF p_open_reason IS NULL OR p_open_reason NOT IN ('first_open_of_business_day', 'next_service_of_business_day', 'explicit_reopen') THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_OPEN_REASON');
  END IF;
  IF p_source IS NULL OR btrim(p_source) = '' THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_SOURCE');
  END IF;

  PERFORM pg_advisory_xact_lock(hashtext('service_session_lifecycle'));

  SELECT * INTO v_bd_state FROM public.business_day_lifecycle_state WHERE singleton = true FOR UPDATE;
  SELECT * INTO v_ss_state FROM public.service_session_state       WHERE singleton = true FOR UPDATE;

  IF v_bd_state.current_business_day_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'NO_CURRENT_BUSINESS_DAY');
  END IF;

  SELECT * INTO v_day FROM public.business_days WHERE id = v_bd_state.current_business_day_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'code', 'BUSINESS_DAY_NOT_FOUND');
  END IF;

  SELECT * INTO v_active FROM public.service_sessions WHERE status IN ('open', 'closing') FOR UPDATE;
  IF FOUND THEN
    IF v_active.business_day_id IS DISTINCT FROM v_day.id THEN
      RETURN jsonb_build_object('ok', false, 'code', 'ACTIVE_SERVICE_BUSINESS_DAY_MISMATCH', 'session', to_jsonb(v_active));
    END IF;
    RETURN jsonb_build_object('ok', true, 'code', 'REUSED', 'created', false, 'session', to_jsonb(v_active));
  END IF;

  v_has_any := EXISTS (SELECT 1 FROM public.service_sessions WHERE business_day_id = v_day.id);

  IF p_open_reason = 'first_open_of_business_day' THEN
    IF v_has_any THEN
      RETURN jsonb_build_object('ok', false, 'code', 'SERVICE_REOPEN_REQUIRED');
    END IF;
  ELSE
    -- Both 'next_service_of_business_day' and 'explicit_reopen' describe a
    -- SUBSEQUENT service of a Business Day that already has history. The rule
    -- is identical and pre-existing; only the stated reason differs, and it
    -- differs durably via the caller's own source string.
    IF NOT v_has_any THEN
      RETURN jsonb_build_object('ok', false, 'code', 'NO_PRIOR_SERVICE_TO_REOPEN');
    END IF;
  END IF;

  INSERT INTO public.service_sessions (
    business_date, status, opened_by, open_source, service_kind, lifecycle_semantics
  ) VALUES (
    v_day.business_date, 'open', p_opened_by, p_source, NULL, 'operational_service_v1'
  ) RETURNING * INTO v_new;

  IF v_new.business_day_id IS DISTINCT FROM v_day.id THEN
    RAISE EXCEPTION 'OPEN_OPERATIONAL_SERVICE_BUSINESS_DAY_DERIVE_MISMATCH' USING ERRCODE = 'P0001';
  END IF;

  PERFORM set_config('ladieci.business_day_pointer_authorized', 'true', true);
  UPDATE public.business_day_lifecycle_state
     SET current_period_id = v_new.id, updated_at = now()
   WHERE singleton = true;

  UPDATE public.service_session_state
     SET current_session_id = v_new.id, updated_at = now()
   WHERE singleton = true;

  INSERT INTO public.service_session_audit(service_session_id, event_type, by_actor, source)
  VALUES (v_new.id, 'opened', p_opened_by, p_source);

  IF (SELECT current_period_id FROM public.business_day_lifecycle_state WHERE singleton = true) IS DISTINCT FROM v_new.id THEN
    RAISE EXCEPTION 'OPEN_OPERATIONAL_SERVICE_POINTER_MISMATCH' USING ERRCODE = 'P0001';
  END IF;
  IF (SELECT current_session_id FROM public.service_session_state WHERE singleton = true) IS DISTINCT FROM v_new.id THEN
    RAISE EXCEPTION 'OPEN_OPERATIONAL_SERVICE_SHADOW_MISMATCH' USING ERRCODE = 'P0001';
  END IF;

  RETURN jsonb_build_object('ok', true, 'code', 'CREATED', 'created', true, 'session', to_jsonb(v_new));
END;
$function$;

CREATE OR REPLACE FUNCTION public.open_service_session(p_opened_by text, p_source text DEFAULT 'backend'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  RETURN jsonb_build_object('ok',false,'code','SERVICE_KIND_REQUIRED');
END $function$;

CREATE OR REPLACE FUNCTION public.order_apply_commercial_adjustment_v1(p_workspace_id uuid, p_by_actor text, p_by_sid_hash text, p_order_uid uuid, p_new_gross numeric, p_reason text, p_client_request_id text, p_request_hash text, p_expected_current_gross numeric, p_meta jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_actor public.auth_actors%ROWTYPE;
  v_entity public.order_entities%ROWTYPE;
  v_ord public.ordenes%ROWTYPE;
  v_meta jsonb := COALESCE(p_meta, '{}'::jsonb);
  v_res jsonb;
  v_net numeric;
  v_current numeric;
BEGIN
  IF p_workspace_id IS NULL OR p_order_uid IS NULL
     OR p_by_actor IS NULL OR btrim(p_by_actor) = ''
     OR p_by_sid_hash IS NULL OR p_by_sid_hash !~ '^[0-9a-f]{64}$'
     OR p_client_request_id IS NULL OR char_length(p_client_request_id) NOT BETWEEN 8 AND 128
     OR p_client_request_id !~ '^[A-Za-z0-9_-]+$'
     OR p_request_hash IS NULL OR p_request_hash !~ '^[0-9a-f]{64}$'
     OR jsonb_typeof(v_meta) <> 'object' OR length(v_meta::text) > 2048
  THEN RAISE EXCEPTION 'ORDER_ADJUSTMENT_INVALID' USING ERRCODE='22023'; END IF;
  IF EXISTS (SELECT 1 FROM jsonb_object_keys(v_meta) k WHERE lower(k) = ANY (ARRAY[
    'pin','pin_hash','password','token','access_token','refresh_token','jwt','secret',
    'authorization','api_key','apikey','bearer','cookie','raw_ip','sid','proof'
  ])) THEN RAISE EXCEPTION 'ORDER_ADJUSTMENT_META_INVALID' USING ERRCODE='22023'; END IF;
  IF p_reason IS NULL OR btrim(p_reason) = '' THEN
    RAISE EXCEPTION 'ORDER_ADJUSTMENT_REASON_REQUIRED' USING ERRCODE='22023'; END IF;

  PERFORM 1 FROM public.workspaces WHERE id = p_workspace_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ORDER_ADJUSTMENT_WORKSPACE_NOT_FOUND' USING ERRCODE='P0002'; END IF;

  SELECT * INTO v_actor FROM public.auth_actors
   WHERE workspace_id = p_workspace_id AND actor = p_by_actor FOR UPDATE;
  -- ADJUSTMENT_ROLES, identical to Mesa: admin/owner only (¬ß25, no widening).
  IF NOT FOUND OR v_actor.active IS NOT TRUE OR v_actor.role NOT IN ('admin','owner')
  THEN RAISE EXCEPTION 'ORDER_ADJUSTMENT_FORBIDDEN' USING ERRCODE='42501'; END IF;

  SELECT * INTO v_entity FROM public.order_entities WHERE order_uid = p_order_uid;
  IF NOT FOUND THEN RAISE EXCEPTION 'ORDER_ADJUSTMENT_ORDER_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  IF v_entity.workspace_id <> p_workspace_id THEN
    RAISE EXCEPTION 'ORDER_ADJUSTMENT_WORKSPACE_MISMATCH' USING ERRCODE='22023'; END IF;

  SELECT * INTO v_ord FROM public.ordenes WHERE order_uid = p_order_uid FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ORDER_ADJUSTMENT_ORDER_NOT_FOUND' USING ERRCODE='P0002'; END IF;

  -- Delegates to the SAME shared core Mesa's own wrapper calls -- no
  -- duplicated obligation logic (¬ß15). Any MESA_ADJUSTMENT_* exception
  -- below is this shared core's own vocabulary, unchanged, not renamed by
  -- this adapter.
  v_res := public.order_obligation_apply_adjustment_v1(
    p_order_uid, p_new_gross, 'manual', p_reason,
    p_by_actor, v_actor.role, p_client_request_id, p_request_hash, p_expected_current_gross);
  IF (v_res->>'changed')::boolean IS NOT TRUE AND (v_res->>'idempotent')::boolean IS NOT TRUE THEN
    RAISE EXCEPTION 'ORDER_ADJUSTMENT_NO_CHANGE' USING ERRCODE='55000'; END IF;
  IF (v_res->>'idempotent')::boolean IS NOT TRUE THEN
    INSERT INTO public.auth_audit(event, target_actor, by_actor, meta)
    VALUES ('ORDER_COMMERCIAL_ADJUSTMENT', NULL, p_by_actor, jsonb_build_object(
      'orderUid', p_order_uid, 'orderId', v_ord.id,
      'previousObligation', v_res->'previousObligation', 'currentObligation', v_res->'currentObligation',
      'revision', v_res->'revision', 'cause', 'manual', 'bootstrapped', v_res->'bootstrapped',
      'clientRequestId', p_client_request_id, 'bySidHash', p_by_sid_hash, 'byRole', v_actor.role));
  END IF;

  -- netCollected from order_financial_events, NOT payment_allocations: a
  -- legacy event-only Servicio payment (payment_transaction_id NULL, zero
  -- allocations) is still real money and must still count here, or the
  -- overCollected WARN (¬ß17 of the brief) would silently under-report it.
  SELECT COALESCE(round(sum(CASE WHEN e.type='refund' THEN -e.amount ELSE e.amount END), 2), 0)
    INTO v_net
    FROM public.order_financial_events e
   WHERE e.service_session_id = v_ord.service_session_id AND e.order_id = v_ord.id
     AND e.type IN ('payment','payment_imported','refund');
  v_current := (v_res->>'currentObligation')::numeric;
  RETURN v_res || jsonb_build_object(
    'orderId', v_ord.id, 'orderUid', p_order_uid, 'netCollected', round(v_net, 2),
    'unpaid', GREATEST(0, round(v_current - v_net, 2)),
    'overCollected', GREATEST(0, round(v_net - v_current, 2)));
END;
$function$;

CREATE OR REPLACE FUNCTION public.order_cancel_v1(p_order_id text, p_by_actor text, p_reason text, p_client_request_id text, p_request_hash text, p_target_estado text DEFAULT 'CANCELADO'::text, p_meta jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_actor public.auth_actors%ROWTYPE; v_peek public.ordenes%ROWTYPE; v_ord public.ordenes%ROWTYPE;
  v_meta jsonb := COALESCE(p_meta, '{}'::jsonb); v_target text; v_res jsonb; v_net numeric;
  v_current numeric; v_workspace uuid; v_now timestamptz := now();
BEGIN
  IF p_order_id IS NULL OR btrim(p_order_id) = ''
     OR p_by_actor IS NULL OR btrim(p_by_actor) = ''
     OR p_client_request_id IS NULL OR char_length(p_client_request_id) NOT BETWEEN 8 AND 128
     OR p_client_request_id !~ '^[A-Za-z0-9_-]+$'
     OR p_request_hash IS NULL OR p_request_hash !~ '^[0-9a-f]{64}$'
     OR jsonb_typeof(v_meta) <> 'object' OR length(v_meta::text) > 2048
  THEN RAISE EXCEPTION 'ORDER_CANCEL_INVALID' USING ERRCODE='22023'; END IF;
  IF p_reason IS NULL OR btrim(p_reason) = '' THEN
    RAISE EXCEPTION 'ORDER_CANCEL_REASON_REQUIRED' USING ERRCODE='22023'; END IF;
  v_target := upper(btrim(COALESCE(p_target_estado, 'CANCELADO')));
  IF v_target NOT IN ('CANCELADO','CANCELLED','ANULADO') THEN
    RAISE EXCEPTION 'ORDER_CANCEL_INVALID' USING ERRCODE='22023'; END IF;
  SELECT * INTO v_peek FROM public.ordenes WHERE id = p_order_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'ORDER_CANCEL_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  SELECT oe.workspace_id INTO v_workspace FROM public.order_entities oe WHERE oe.order_uid = v_peek.order_uid;
  SELECT * INTO v_actor FROM public.auth_actors
   WHERE actor = p_by_actor AND (v_workspace IS NULL OR workspace_id = v_workspace) FOR UPDATE;
  IF NOT FOUND OR v_actor.active IS NOT TRUE
     OR v_actor.role NOT IN ('admin','operator','owner','cashier','waiter','legacy_operator')
  THEN RAISE EXCEPTION 'ORDER_CANCEL_FORBIDDEN' USING ERRCODE='42501'; END IF;
  IF v_peek.table_session_id IS NOT NULL THEN
    PERFORM 1 FROM public.table_sessions WHERE id = v_peek.table_session_id FOR UPDATE; END IF;
  SELECT * INTO v_ord FROM public.ordenes WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ORDER_CANCEL_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  IF v_ord.order_uid IS NULL THEN RAISE EXCEPTION 'ORDER_WITHOUT_STABLE_IDENTITY' USING ERRCODE='22023'; END IF;
  IF upper(COALESCE(v_ord.estado,'')) = v_target THEN
    v_current := public.order_canonical_obligation_v1(v_ord.order_uid);
    SELECT COALESCE(sum(CASE WHEN e.type = 'refund' THEN -e.amount ELSE e.amount END), 0)
      INTO v_net FROM public.order_financial_events e
     WHERE e.order_id = v_ord.id AND e.type IN ('payment','payment_imported','refund')
       AND e.service_session_id IS NOT DISTINCT FROM v_ord.service_session_id;
    RETURN jsonb_build_object('ok', true, 'idempotent', true, 'orderId', v_ord.id, 'orderUid', v_ord.order_uid,
      'estado', v_ord.estado, 'currentObligation', round(v_current, 2), 'netCollected', round(v_net, 2),
      'unpaid', GREATEST(0, round(v_current - v_net, 2)), 'overCollected', GREATEST(0, round(v_net - v_current, 2)));
  END IF;
  IF upper(COALESCE(v_ord.estado,'')) NOT IN ('POR_CONFIRMAR','NUEVO','EN_COCINA','LISTO','EN_ENTREGA') THEN
    RAISE EXCEPTION 'ORDER_CANCEL_STATE_INVALID' USING ERRCODE='22023'; END IF;
  v_res := public.order_obligation_apply_adjustment_v1(
    v_ord.order_uid, 0, 'order_cancellation', p_reason, p_by_actor, v_actor.role,
    p_client_request_id, p_request_hash, NULL);
  UPDATE public.ordenes SET estado = v_target, cancelado_at = v_now WHERE id = v_ord.id;
  SELECT COALESCE(sum(CASE WHEN e.type = 'refund' THEN -e.amount ELSE e.amount END), 0)
    INTO v_net FROM public.order_financial_events e
   WHERE e.order_id = v_ord.id AND e.type IN ('payment','payment_imported','refund')
     AND e.service_session_id IS NOT DISTINCT FROM v_ord.service_session_id;
  v_current := (v_res->>'currentObligation')::numeric;
  RETURN jsonb_build_object('ok', true, 'idempotent', false, 'orderId', v_ord.id, 'orderUid', v_ord.order_uid,
    'prevEstado', v_ord.estado, 'estado', v_target, 'previousObligation', v_res->'previousObligation',
    'currentObligation', round(v_current, 2), 'revision', v_res->'revision', 'bootstrapped', v_res->'bootstrapped',
    'netCollected', round(v_net, 2), 'unpaid', GREATEST(0, round(v_current - v_net, 2)),
    'overCollected', GREATEST(0, round(v_net - v_current, 2)));
END;
$function$;

CREATE OR REPLACE FUNCTION public.order_canonical_obligation_v1(p_order_uid uuid)
 RETURNS numeric
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT COALESCE(
    (SELECT ob.gross_amount FROM public.order_obligations ob
      WHERE ob.order_uid = p_order_uid ORDER BY ob.revision DESC LIMIT 1),
    (SELECT CASE WHEN upper(COALESCE(o.estado,'')) IN ('ANULADO','CANCELADO','CANCELLED') THEN 0::numeric
                 ELSE COALESCE(o.totale, 0) END
       FROM public.ordenes o WHERE o.order_uid = p_order_uid),
    0::numeric);
$function$;

CREATE OR REPLACE FUNCTION public.order_economic_basis_lock_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_field text;
  v_old   text;
  v_new   text;
BEGIN
  IF NEW.totale IS DISTINCT FROM OLD.totale THEN
    v_field := 'totale'; v_old := OLD.totale::text; v_new := NEW.totale::text;
  ELSIF NEW.items IS DISTINCT FROM OLD.items THEN
    v_field := 'items'; v_old := OLD.items::text; v_new := NEW.items::text;
  ELSIF NEW.delivery_fee IS DISTINCT FROM OLD.delivery_fee THEN
    v_field := 'delivery_fee'; v_old := OLD.delivery_fee::text; v_new := NEW.delivery_fee::text;
  ELSIF NEW.descuento_tipo IS DISTINCT FROM OLD.descuento_tipo THEN
    v_field := 'descuento_tipo'; v_old := OLD.descuento_tipo; v_new := NEW.descuento_tipo;
  ELSIF NEW.descuento_valor IS DISTINCT FROM OLD.descuento_valor THEN
    v_field := 'descuento_valor'; v_old := OLD.descuento_valor::text; v_new := NEW.descuento_valor::text;
  ELSIF NEW.descuento_importe IS DISTINCT FROM OLD.descuento_importe THEN
    v_field := 'descuento_importe'; v_old := OLD.descuento_importe::text; v_new := NEW.descuento_importe::text;
  ELSE
    -- Nothing economic moved: a state-only / metadata-only update, or an identical
    -- rewrite. Never this guard's business -- and no order_obligations read either.
    RETURN NEW;
  END IF;

  IF OLD.table_session_id IS NOT NULL THEN
    RAISE EXCEPTION 'ORDER_ECONOMIC_BASIS_LOCKED'
      USING ERRCODE = 'P0001',
            DETAIL  = format('order_id=%s field=%s old=%s new=%s table_session_id=%s',
                             OLD.id, v_field, COALESCE(v_old, '<null>'), COALESCE(v_new, '<null>'), OLD.table_session_id),
            HINT    = 'This is a Mesa order. Its economic basis is owned by the table-session commands and the canonical adjustment/cancellation core, never by a generic editor.';
  END IF;

  IF EXISTS (SELECT 1 FROM public.order_obligations ob
              WHERE ob.order_uid = OLD.order_uid
                AND ob.source = 'order_commercial_adjustment_v1') THEN
    RAISE EXCEPTION 'ORDER_ECONOMIC_BASIS_LOCKED'
      USING ERRCODE = 'P0001',
            DETAIL  = format('order_id=%s field=%s old=%s new=%s order_uid=%s',
                             OLD.id, v_field, COALESCE(v_old, '<null>'), COALESCE(v_new, '<null>'), OLD.order_uid),
            HINT    = 'This order already carries a commercial adjustment or cancellation revision. Its economic basis can only change through that same canonical core, never through a generic editor.';
  END IF;

  IF upper(COALESCE(OLD.estado, '')) IN ('CANCELADO', 'CANCELLED', 'ANULADO')
     OR upper(COALESCE(NEW.estado, '')) IN ('CANCELADO', 'CANCELLED', 'ANULADO')
  THEN
    RAISE EXCEPTION 'ORDER_ECONOMIC_BASIS_LOCKED'
      USING ERRCODE = 'P0001',
            DETAIL  = format('order_id=%s field=%s old=%s new=%s estado=%s',
                             OLD.id, v_field, COALESCE(v_old, '<null>'), COALESCE(v_new, '<null>'), OLD.estado),
            HINT    = 'This order is cancelled/annulled. Its economic basis is frozen at cancellation.';
  END IF;

  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.order_entity_anchor_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_workspace       uuid;
  v_business_day    uuid;
  v_epoch           integer;
  v_ticket_number   integer;
  v_uid             uuid;
BEGIN
  IF NEW.service_session_id IS NULL THEN
    RAISE EXCEPTION 'ORDER_WITHOUT_SERVICE_SESSION' USING ERRCODE='P0001';
  END IF;
  IF NEW.order_uid IS NOT NULL THEN
    RAISE EXCEPTION 'ORDER_UID_FORGERY' USING ERRCODE='P0001';   -- callers never supply it
  END IF;

  -- Business Day lineage: deterministic, write-time, immutable -- via the
  -- order's OWN Service Period, established NOT NULL by R-DAY1 for every
  -- live service_sessions row. Fails closed on genuine integrity breakage
  -- only; structurally unreachable in normal operation.
  SELECT business_day_id INTO v_business_day
    FROM public.service_sessions WHERE id = NEW.service_session_id;
  IF v_business_day IS NULL THEN
    RAISE EXCEPTION 'SERVICE_PERIOD_WITHOUT_BUSINESS_DAY' USING ERRCODE='P0001';
  END IF;

  -- Workspace lineage: Mesa orders resolve via their table session (already
  -- workspace_id NOT NULL); every other channel resolves via the singleton
  -- tripwire. Never inferred from client payload.
  IF NEW.table_session_id IS NOT NULL THEN
    SELECT ts.workspace_id INTO v_workspace
      FROM public.table_sessions ts WHERE ts.id = NEW.table_session_id;
    IF v_workspace IS NULL THEN
      RAISE EXCEPTION 'MESA_SESSION_NOT_FOUND' USING ERRCODE='P0002';
    END IF;
  ELSE
    v_workspace := public.mesa_singleton_workspace_v1();
  END IF;

  -- Ticket identity substrate: real values, minted from THIS order's own
  -- Business Day row (resolved above via period lineage, never the
  -- pointer). Isolated counter, no relationship to ordenes.id/#NNN.
  UPDATE public.business_days
     SET next_ticket_number = next_ticket_number + 1, updated_at = now()
   WHERE id = v_business_day
  RETURNING next_ticket_number - 1, ticket_epoch INTO v_ticket_number, v_epoch;

  INSERT INTO public.order_entities
    (workspace_id, display_order_id, service_session_id, table_session_id,
     business_day_id, ticket_epoch, ticket_number, created_at)
  VALUES
    (v_workspace, NEW.id, NEW.service_session_id, NEW.table_session_id,
     v_business_day, v_epoch, v_ticket_number, COALESCE(NEW.created_at, now()))
  RETURNING order_uid INTO v_uid;

  NEW.order_uid := v_uid;
  RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.order_financial_events_append_only()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  -- deterministic, no dynamic SQL, no row contents leaked
  RAISE EXCEPTION 'order_financial_events is append-only' USING ERRCODE='0A000';
END;
$function$;

CREATE OR REPLACE FUNCTION public.order_has_economic_evidence_v1(p_order_id text)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.ordenes o
     WHERE o.id = p_order_id
       AND (
         -- LEGACY economic evidence. Pre-ledger orders declared money with these two
         -- booleans and Economía still reports them through safeTicket's legacy
         -- fallback, so they are money and they block a delete.
         o.ya_pagado IS TRUE
         OR o.cobrado IS TRUE
         -- N-2 CANONICAL OBLIGATION, on the permanent identity. An unpaid order with an
         -- obligation is evidenced: the obligation records what was owed. Matching on
         -- order_uid means a recycled #NNN can never borrow another order's obligation;
         -- an order with a NULL order_uid yields no match, and by the anchor trigger's
         -- own fail-closed contract such an order cannot have an obligation anyway.
         OR EXISTS (
           SELECT 1 FROM public.order_obligations ob
            WHERE ob.order_uid = o.order_uid
         )
         -- CANONICAL PAYMENT/REFUND/VOID evidence, session-scoped exactly as before.
         OR EXISTS (
           SELECT 1 FROM public.order_financial_events e
            WHERE e.order_id = o.id
              AND (o.service_session_id IS NULL OR e.service_session_id IS NULL OR e.service_session_id = o.service_session_id)
         )
         OR EXISTS (
           SELECT 1 FROM public.table_order_lines tol
            WHERE tol.order_id = o.id
              AND (o.service_session_id IS NULL OR tol.service_session_id = o.service_session_id)
         )
         OR EXISTS (
           SELECT 1 FROM public.payment_allocations pa
            JOIN public.payment_transactions pt ON pt.id = pa.payment_transaction_id
            WHERE pa.order_id = o.id
              AND (o.service_session_id IS NULL OR pt.service_session_id IS NULL OR pt.service_session_id = o.service_session_id)
         )
         -- AUDIT evidence. An incident is a record that something happened to this order.
         OR EXISTS (
           SELECT 1 FROM public.service_incidents si
            WHERE si.order_id = o.id
              AND (o.service_session_id IS NULL OR si.service_session_id = o.service_session_id)
         )
       )
  );
$function$;

CREATE OR REPLACE FUNCTION public.order_import_legacy_payment(p_order_id text, p_amount numeric, p_payment_method text, p_reason text, p_by_actor text, p_session_version integer, p_ip_hash text, p_meta jsonb, p_idem_scope_key text, p_confirm text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_by public.auth_actors%ROWTYPE;
  v_ord public.ordenes%ROWTYPE;
  v_existing public.order_financial_events%ROWTYPE;
  v_existing_basis public.order_financial_events%ROWTYPE;
  v_new public.order_financial_events%ROWTYPE;
  v_role text; v_method text; v_reason text; v_amount numeric(10,2);
  v_meta jsonb := COALESCE(p_meta, '{}'::jsonb);
  v_canon jsonb; v_digest text; v_replay_digest text;
BEGIN
  IF jsonb_typeof(v_meta) <> 'object' THEN RAISE EXCEPTION 'AUTH_META_INVALID' USING ERRCODE='22023'; END IF;
  IF length(v_meta::text) > 2048 THEN RAISE EXCEPTION 'AUTH_META_TOO_LARGE' USING ERRCODE='22023'; END IF;
  IF EXISTS (SELECT 1 FROM jsonb_object_keys(v_meta) k WHERE lower(k) = ANY (ARRAY[
       'pin','pin_hash','password','token','access_token','refresh_token','jwt','secret',
       'recovery_secret','authorization','api_key','apikey','bearer','cookie','raw_ip','confirmation']))
  THEN RAISE EXCEPTION 'AUTH_META_SENSITIVE_KEY' USING ERRCODE='22023'; END IF;
  IF p_ip_hash IS NULL OR btrim(p_ip_hash) = '' THEN RAISE EXCEPTION 'AUTH_IP_HASH_REQUIRED' USING ERRCODE='22023'; END IF;
  IF length(p_ip_hash) > 64 THEN RAISE EXCEPTION 'AUTH_IP_HASH_TOO_LONG' USING ERRCODE='22023'; END IF;
  IF p_idem_scope_key IS NULL OR char_length(p_idem_scope_key) < 8 OR char_length(p_idem_scope_key) > 128
     OR p_idem_scope_key !~ '^[A-Za-z0-9_-]+$'
  THEN RAISE EXCEPTION 'AUTH_IDEM_KEY_INVALID' USING ERRCODE='22023'; END IF;
  IF p_session_version IS NULL OR p_session_version < 1 THEN RAISE EXCEPTION 'AUTH_SESSION_STALE' USING ERRCODE='22023'; END IF;

  v_method := lower(btrim(COALESCE(p_payment_method, '')));
  IF v_method NOT IN ('efectivo','tarjeta','bizum') THEN RAISE EXCEPTION 'AUTH_METHOD_INVALID' USING ERRCODE='22023'; END IF;

  IF p_reason IS NULL OR btrim(p_reason) = '' THEN RAISE EXCEPTION 'AUTH_REASON_BLANK' USING ERRCODE='22023'; END IF;
  v_reason := btrim(p_reason);

  v_amount := round(p_amount, 2);
  IF v_amount IS NULL OR v_amount <= 0 THEN RAISE EXCEPTION 'AUTH_AMOUNT_INVALID' USING ERRCODE='22023'; END IF;

  IF p_confirm IS DISTINCT FROM 'IMPORT_LEGACY_PAYMENT' THEN RAISE EXCEPTION 'AUTH_CONFIRMATION_REQUIRED' USING ERRCODE='22023'; END IF;

  SELECT * INTO v_by FROM public.auth_actors WHERE actor = p_by_actor FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'AUTH_ACTOR_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  IF v_by.active <> true THEN RAISE EXCEPTION 'AUTH_INITIATOR_INACTIVE' USING ERRCODE='22023'; END IF;
  v_role := v_by.role;
  IF v_role <> 'admin' THEN RAISE EXCEPTION 'AUTH_FORBIDDEN_ROLE' USING ERRCODE='22023'; END IF;
  IF p_session_version <> v_by.session_version THEN RAISE EXCEPTION 'AUTH_SESSION_STALE' USING ERRCODE='22023'; END IF;

  SELECT * INTO v_ord FROM public.ordenes WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'AUTH_ORDER_NOT_FOUND' USING ERRCODE='P0002'; END IF;

  -- Economic Writer Hardening V1 (migration 126) -- Mesa orders are settled exclusively
  -- through mesa_post_payment_v1/mesa_post_refund_v1; there is no legacy pre-ledger money
  -- to import on a table order (0 live cases), and importing one would create a second,
  -- unfenced money fact beside the canonical per-line ledger.
  IF v_ord.table_session_id IS NOT NULL THEN
    RAISE EXCEPTION 'AUTH_MESA_ORDER_NOT_ALLOWED' USING ERRCODE='22023',
      DETAIL = format('order_id=%s is Mesa-owned (table_session_id=%s) -- legacy import is not permitted on table orders', p_order_id, v_ord.table_session_id);
  END IF;

  -- N-6 — financial ownership must be provable before any historical money is imported.
  IF v_ord.service_session_id IS NULL THEN
    RAISE EXCEPTION 'ORDER_WITHOUT_SERVICE_SESSION' USING ERRCODE='22023',
      DETAIL = format('order_id=%s has no service session -- financial ownership cannot be proven', p_order_id);
  END IF;

  -- Same-scope replay is based on immutable event snapshots plus current request amount/method/reason.
  SELECT * INTO v_existing FROM public.order_financial_events
    WHERE order_id = p_order_id AND type = 'payment_imported' AND idem_scope_key = p_idem_scope_key
      AND service_session_id IS NOT DISTINCT FROM v_ord.service_session_id;
  IF FOUND THEN
    IF v_existing.type <> 'payment_imported'
       OR v_existing.amount IS NULL OR v_existing.amount <= 0
       OR v_existing.payment_method NOT IN ('efectivo','tarjeta','bizum')
       OR v_existing.legacy IS DISTINCT FROM true
       OR v_existing.prev_pay_state <> 'unpaid' OR v_existing.new_pay_state <> 'paid'
       OR v_existing.prev_estado IS DISTINCT FROM v_existing.new_estado
       OR v_existing.original_giro_id IS NOT NULL
    THEN RAISE EXCEPTION 'AUTH_IDEMPOTENCY_CONFLICT' USING ERRCODE='22023'; END IF;

    v_replay_digest := lower(encode(sha256(convert_to((jsonb_build_object(
      'order_id', p_order_id, 'type', 'payment_imported', 'idem_scope_key', p_idem_scope_key,
      'by_actor', p_by_actor, 'by_role', v_role, 'reason', v_reason,
      'prev_estado', v_existing.prev_estado, 'new_estado', v_existing.new_estado,
      'prev_pay_state', v_existing.prev_pay_state, 'new_pay_state', v_existing.new_pay_state,
      'amount', v_amount, 'payment_method', v_method, 'legacy', true))::text, 'UTF8')), 'hex'));
    IF v_existing.payload_digest = v_replay_digest THEN
      RETURN jsonb_build_object('event_id', v_existing.id, 'order_id', v_existing.order_id,
        'type', v_existing.type, 'amount', v_existing.amount, 'payment_method', v_existing.payment_method,
        'prev_estado', v_existing.prev_estado, 'new_estado', v_existing.new_estado,
        'prev_pay_state', v_existing.prev_pay_state, 'new_pay_state', v_existing.new_pay_state,
        'legacy', v_existing.legacy, 'idempotent', true, 'created_at', v_existing.created_at);
    END IF;
    RAISE EXCEPTION 'AUTH_IDEMPOTENCY_CONFLICT' USING ERRCODE='22023';
  END IF;

  v_canon := jsonb_build_object(
    'order_id', p_order_id, 'type', 'payment_imported', 'idem_scope_key', p_idem_scope_key,
    'by_actor', p_by_actor, 'by_role', v_role, 'reason', v_reason,
    'prev_estado', v_ord.estado, 'new_estado', v_ord.estado,
    'prev_pay_state', 'unpaid', 'new_pay_state', 'paid',
    'amount', v_amount, 'payment_method', v_method, 'legacy', true);
  v_digest := lower(encode(sha256(convert_to(v_canon::text, 'UTF8')), 'hex'));

  SELECT * INTO v_existing_basis FROM public.order_financial_events
    WHERE order_id = p_order_id AND type IN ('payment','payment_imported')
      AND service_session_id IS NOT DISTINCT FROM v_ord.service_session_id
    ORDER BY created_at ASC LIMIT 1;
  IF FOUND THEN
    RAISE EXCEPTION 'AUTH_BASIS_EXISTS' USING ERRCODE='22023';
  END IF;

  IF NOT (v_ord.ya_pagado IS TRUE OR v_ord.cobrado IS TRUE) THEN
    RAISE EXCEPTION 'AUTH_NOT_LEGACY_PAID' USING ERRCODE='22023';
  END IF;

  INSERT INTO public.order_financial_events(
    order_id, type, amount, payment_method, reason, legacy, by_actor, by_role,
    prev_estado, new_estado, prev_pay_state, new_pay_state, original_giro_id,
    ip_hash, meta, idem_scope_key, payload_digest)
  VALUES (p_order_id, 'payment_imported', v_amount, v_method, v_reason, true, p_by_actor, v_role,
    v_ord.estado, v_ord.estado, 'unpaid', 'paid', NULL,
    p_ip_hash, v_meta, p_idem_scope_key, v_digest)
  RETURNING * INTO v_new;

  UPDATE public.ordenes SET ya_pagado = true, cobrado = true, metodo_pago = v_method
   WHERE id = p_order_id;

  RETURN jsonb_build_object('event_id', v_new.id, 'order_id', v_new.order_id,
    'type', v_new.type, 'amount', v_new.amount, 'payment_method', v_new.payment_method,
    'prev_estado', v_new.prev_estado, 'new_estado', v_new.new_estado,
    'prev_pay_state', v_new.prev_pay_state, 'new_pay_state', v_new.new_pay_state,
    'legacy', v_new.legacy, 'idempotent', false, 'created_at', v_new.created_at);
END;
$function$;

CREATE OR REPLACE FUNCTION public.order_initial_payment_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_intent jsonb := NEW.initial_payment_intent;
  v_method text;
  v_actor  text;
  v_sid_hash text;
  v_workspace_id uuid;
  v_client_request_id text;
  v_request_hash text;
BEGIN
  -- Defence in depth: the trigger is already WHEN-scoped to a non-null intent.
  IF v_intent IS NULL THEN
    RETURN NEW;
  END IF;

  -- Mesa settles through its own payment hub (payment_transactions /
  -- payment_allocations / mesa_post_payment_v1). A table order must never take a
  -- second, parallel payment here. The frontend already forbids it; this refuses
  -- it at the boundary rather than trusting that.
  IF NEW.table_session_id IS NOT NULL THEN
    RAISE EXCEPTION 'INITIAL_PAYMENT_NOT_FOR_TABLE_ORDER' USING ERRCODE = 'P0001',
      DETAIL = format('order_id=%s table_session=%s', NEW.id, NEW.table_session_id);
  END IF;

  -- The whole point of N-3: legacy-paid authority must NOT precede the canonical
  -- payment. If either flag arrived true, someone is still trying to declare money
  -- with a boolean -- refuse rather than paper over it.
  IF NEW.ya_pagado IS TRUE OR NEW.cobrado IS TRUE THEN
    RAISE EXCEPTION 'INITIAL_PAYMENT_LEGACY_FLAG_PRESENT' USING ERRCODE = 'P0001',
      DETAIL = format('order_id=%s ya_pagado=%s cobrado=%s', NEW.id, NEW.ya_pagado, NEW.cobrado);
  END IF;

  v_method   := lower(btrim(COALESCE(v_intent->>'method', '')));
  v_actor    := btrim(COALESCE(v_intent->>'actor', ''));
  v_sid_hash := lower(btrim(COALESCE(v_intent->>'sid_hash', '')));

  IF v_method NOT IN ('efectivo','tarjeta','bizum') THEN
    RAISE EXCEPTION 'INITIAL_PAYMENT_METHOD_INVALID' USING ERRCODE = 'P0001',
      DETAIL = format('order_id=%s method=%s', NEW.id, v_method);
  END IF;
  IF v_actor = '' OR v_sid_hash !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION 'INITIAL_PAYMENT_CONTEXT_INVALID' USING ERRCODE = 'P0001',
      DETAIL = format('order_id=%s actor_present=%s sid_hash_valid=%s',
                      NEW.id, (v_actor <> ''), (v_sid_hash ~ '^[0-9a-f]{64}$'));
  END IF;

  SELECT oe.workspace_id INTO v_workspace_id
    FROM public.order_entities oe WHERE oe.order_uid = NEW.order_uid;
  IF v_workspace_id IS NULL THEN
    RAISE EXCEPTION 'INITIAL_PAYMENT_WORKSPACE_UNRESOLVED' USING ERRCODE = 'P0001',
      DETAIL = format('order_id=%s order_uid=%s', NEW.id, NEW.order_uid);
  END IF;

  -- SAME deterministic per-order key the legacy path always used -- this is what
  -- makes a replayed order-creation request replay instead of double-paying
  -- (§9/§22 of the brief): payment_transactions_idempotency_uq is (workspace_id,
  -- client_request_id), so this key now plays exactly the role
  -- registerOperatorPayment.js's idem_scope_key played for _ledger_write_payment.
  v_client_request_id := 'pay-order-' || regexp_replace(NEW.id, '[^A-Za-z0-9_-]', '', 'g');
  v_request_hash := encode(extensions.digest(concat_ws('|', 'initial_payment_at_creation', NEW.id,
    NEW.order_uid::text, v_method), 'sha256'), 'hex');

  -- THE canonical check-centric payment writer -- same authority, server-derived
  -- amount, digest, and legacy mirrors as the operator collection path (§R of the
  -- audit). mode='full': a creation-time "ya pagado" always settles the order's
  -- FULL obligation, exactly like _ledger_write_payment/order_mark_paid did.
  PERFORM public.order_post_payment_v1(
    v_workspace_id, v_actor, v_sid_hash, NEW.order_uid, v_method, 'full', NULL,
    v_client_request_id, v_request_hash,
    jsonb_build_object('source', 'initial_payment_at_creation'), false);

  -- The intent has done its one job. Clearing it here keeps the column NULL at
  -- rest; this UPDATE touches no economic column, so neither N-5's guard nor
  -- N-2's revision trigger fires.
  UPDATE public.ordenes SET initial_payment_intent = NULL WHERE id = NEW.id;

  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.order_intake_policy_v1(p_minutes_of_day integer)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT jsonb_build_object(
    'businessDateIsPreviousDay', p_minutes_of_day < 240,
    'serviceKind', CASE WHEN p_minutes_of_day >= 240 AND p_minutes_of_day < 1050
                        THEN 'PRANZO' ELSE 'SERA' END, -- language-guard: allow-legacy PRANZO/SERA are the existing service_kind enum values, reproduced verbatim for economic classification (S-C), not new vocabulary
    -- O-5 — named explicitly for what it actually decides: eligibility to
    -- LAZILY CREATE the Business Day's first Operational Service. An
    -- already-open canonical service is NEVER gated by this fact (Stale
    -- Service Protection V1's continuity fast-path returns earlier, in
    -- both call sites, before this value is even consulted). Reuses the
    -- SAME 04:00 rollover threshold as businessDateIsPreviousDay above --
    -- one authority for both facts, not a second independent literal.
    'mayCreateFirstService', p_minutes_of_day >= 240
  );
$function$;

CREATE OR REPLACE FUNCTION public.order_mark_paid(p_order_id text, p_payment_method text, p_reason text, p_by_actor text, p_session_version integer, p_ip_hash text, p_meta jsonb, p_idem_scope_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  -- RETIREMENT STUB (Economic Writer Hardening V1, migration 126). order_mark_paid
  -- delegated to _ledger_write_payment -- the same OFE-only, totale-based legacy authority
  -- E-2 above just fenced. Zero live FE callers (audit: DORMANT_BUT_REACHABLE, and
  -- dangerous on Mesa -- N-5 blocker L-1); a canonical replacement already exists for every
  -- reachable path (order_post_payment_v1 via Cash V1, mesa_post_payment_v1 via Mesa API).
  -- This function creates NO money under any input, unconditionally.
  RAISE EXCEPTION 'LEGACY_OPERATOR_COLLECTION_RETIRED' USING ERRCODE='22023',
    DETAIL = format('order_id=%s -- order_mark_paid is retired and creates no money', p_order_id),
    HINT = 'Use the canonical cash path: order_post_payment_v1 (Cash V1 API) or mesa_post_payment_v1 (Mesa API).';
END;
$function$;

CREATE OR REPLACE FUNCTION public.order_obligation_anchor_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_workspace uuid;
  v_kind      text;
BEGIN
  IF NEW.order_uid IS NULL THEN
    RAISE EXCEPTION 'ORDER_OBLIGATION_WITHOUT_IDENTITY' USING ERRCODE='P0001';
  END IF;
  IF NEW.service_session_id IS NULL THEN
    RAISE EXCEPTION 'ORDER_OBLIGATION_WITHOUT_SERVICE_SESSION' USING ERRCODE='P0001';
  END IF;

  SELECT oe.workspace_id INTO v_workspace
    FROM public.order_entities oe WHERE oe.order_uid = NEW.order_uid;
  IF v_workspace IS NULL THEN
    RAISE EXCEPTION 'ORDER_OBLIGATION_WITHOUT_WORKSPACE' USING ERRCODE='P0001';
  END IF;

  SELECT ss.service_kind INTO v_kind
    FROM public.service_sessions ss WHERE ss.id = NEW.service_session_id;

  INSERT INTO public.order_obligations
    (order_uid, order_id, service_session_id, workspace_id, revision,
     gross_amount, channel, source, economic_period_kind, created_at)
  VALUES
    (NEW.order_uid, NEW.id, NEW.service_session_id, v_workspace, 1,
     COALESCE(NEW.totale, 0), NEW.canal, 'order_create_v1',
     CASE WHEN v_kind IN ('PRANZO','SERA') THEN v_kind ELSE NULL END,
     COALESCE(NEW.created_at, now()));

  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.order_obligation_apply_adjustment_v1(p_order_uid uuid, p_new_gross numeric, p_cause text, p_reason text, p_by_actor text, p_by_role text, p_client_request_id text, p_request_hash text, p_expected_current_gross numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_ord public.ordenes%ROWTYPE; v_prev public.order_obligations%ROWTYPE; v_workspace uuid;
  v_kind text; v_current numeric; v_revision integer; v_new_rev integer;
  v_bootstrap boolean := false; v_reason text; v_session uuid; v_period text;
BEGIN
  IF p_order_uid IS NULL THEN RAISE EXCEPTION 'ORDER_WITHOUT_STABLE_IDENTITY' USING ERRCODE='22023'; END IF;
  IF p_cause IS NULL OR p_cause NOT IN ('manual','order_cancellation') THEN
    RAISE EXCEPTION 'MESA_ADJUSTMENT_INVALID' USING ERRCODE='22023'; END IF;
  IF p_new_gross IS NULL OR p_new_gross < 0 THEN RAISE EXCEPTION 'MESA_ADJUSTMENT_INVALID' USING ERRCODE='22023'; END IF;
  IF p_reason IS NULL OR btrim(p_reason) = '' THEN RAISE EXCEPTION 'MESA_ADJUSTMENT_REASON_REQUIRED' USING ERRCODE='22023'; END IF;
  v_reason := btrim(p_reason);
  IF p_by_actor IS NULL OR btrim(p_by_actor) = '' OR p_by_role IS NULL THEN
    RAISE EXCEPTION 'MESA_ADJUSTMENT_INVALID' USING ERRCODE='22023'; END IF;
  IF p_client_request_id IS NULL OR p_request_hash IS NULL THEN
    RAISE EXCEPTION 'MESA_ADJUSTMENT_INVALID' USING ERRCODE='22023'; END IF;

  SELECT * INTO v_ord FROM public.ordenes WHERE order_uid = p_order_uid FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'MESA_ADJUSTMENT_ORDER_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  IF v_ord.service_session_id IS NULL THEN RAISE EXCEPTION 'ORDER_WITHOUT_SERVICE_SESSION' USING ERRCODE='22023'; END IF;

  SELECT oe.workspace_id INTO v_workspace FROM public.order_entities oe WHERE oe.order_uid = p_order_uid;
  IF v_workspace IS NULL THEN RAISE EXCEPTION 'ORDER_WITHOUT_STABLE_IDENTITY' USING ERRCODE='22023'; END IF;

  SELECT * INTO v_prev FROM public.order_obligations
   WHERE workspace_id = v_workspace AND client_request_id = p_client_request_id;
  IF FOUND THEN
    IF v_prev.request_hash IS DISTINCT FROM p_request_hash THEN
      RAISE EXCEPTION 'MESA_ADJUSTMENT_IDEMPOTENCY_CONFLICT' USING ERRCODE='23505'; END IF;
    RETURN jsonb_build_object('ok', true, 'idempotent', true, 'changed', true, 'bootstrapped', false,
      'orderUid', v_prev.order_uid, 'revision', v_prev.revision, 'currentObligation', v_prev.gross_amount,
      'previousObligation', (SELECT ob.gross_amount FROM public.order_obligations ob
                              WHERE ob.order_uid = p_order_uid AND ob.revision = v_prev.revision - 1),
      'cause', v_prev.cause);
  END IF;

  SELECT * INTO v_prev FROM public.order_obligations WHERE order_uid = p_order_uid ORDER BY revision DESC LIMIT 1;
  IF NOT FOUND THEN
    v_bootstrap := true; v_current := COALESCE(v_ord.totale, 0); v_revision := 1; v_session := v_ord.service_session_id;
    SELECT ss.service_kind INTO v_kind FROM public.service_sessions ss WHERE ss.id = v_session;
    v_period := CASE WHEN v_kind IN ('PRANZO','SERA') THEN v_kind ELSE NULL END;
    INSERT INTO public.order_obligations
      (order_uid, order_id, service_session_id, workspace_id, revision, gross_amount, channel, source,
       economic_period_kind, created_at, materialized_lazily)
    VALUES (p_order_uid, v_ord.id, v_session, v_workspace, 1, v_current, v_ord.canal, 'order_create_v1',
       v_period, COALESCE(v_ord.created_at, now()), true);
  ELSE
    v_current := v_prev.gross_amount; v_revision := v_prev.revision; v_session := v_prev.service_session_id;
    v_period := v_prev.economic_period_kind;
  END IF;

  IF p_expected_current_gross IS NOT NULL
     AND round(p_expected_current_gross, 2) IS DISTINCT FROM round(v_current, 2) THEN
    RAISE EXCEPTION 'MESA_ADJUSTMENT_STALE_OBLIGATION' USING ERRCODE='55000'; END IF;
  IF round(p_new_gross, 2) > round(v_current, 2) THEN
    RAISE EXCEPTION 'MESA_ADJUSTMENT_EXCEEDS_OBLIGATION' USING ERRCODE='22023'; END IF;
  IF round(p_new_gross, 2) = round(v_current, 2) THEN
    RETURN jsonb_build_object('ok', true, 'idempotent', false, 'changed', false, 'bootstrapped', v_bootstrap,
      'orderUid', p_order_uid, 'revision', CASE WHEN v_bootstrap THEN 1 ELSE v_revision END,
      'currentObligation', v_current, 'previousObligation', v_current, 'cause', p_cause);
  END IF;

  v_new_rev := CASE WHEN v_bootstrap THEN 2 ELSE v_revision + 1 END;
  INSERT INTO public.order_obligations
    (order_uid, order_id, service_session_id, workspace_id, revision, gross_amount, channel, source,
     economic_period_kind, created_at, cause, reason, by_actor, by_role, client_request_id, request_hash)
  VALUES (p_order_uid, v_ord.id, v_session, v_workspace, v_new_rev, round(p_new_gross, 2), v_ord.canal,
     'order_commercial_adjustment_v1', v_period, now(), p_cause, v_reason, p_by_actor, p_by_role,
     p_client_request_id, p_request_hash);

  RETURN jsonb_build_object('ok', true, 'idempotent', false, 'changed', true, 'bootstrapped', v_bootstrap,
    'orderUid', p_order_uid, 'revision', v_new_rev, 'previousObligation', v_current,
    'currentObligation', round(p_new_gross, 2), 'cause', p_cause);
END;
$function$;

CREATE OR REPLACE FUNCTION public.order_obligation_revision_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_prev   public.order_obligations%ROWTYPE;
BEGIN
  IF NEW.totale IS NOT DISTINCT FROM OLD.totale THEN
    RETURN NEW;
  END IF;

  SELECT * INTO v_prev FROM public.order_obligations
   WHERE order_uid = NEW.order_uid
   ORDER BY revision DESC LIMIT 1;

  IF NOT FOUND THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.order_obligations
    (order_uid, order_id, service_session_id, workspace_id, revision,
     gross_amount, channel, source, economic_period_kind, created_at)
  VALUES
    (NEW.order_uid, NEW.id, v_prev.service_session_id, v_prev.workspace_id,
     v_prev.revision + 1, COALESCE(NEW.totale, 0), NEW.canal,
     'order_total_revision_v1', v_prev.economic_period_kind, now());

  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.order_obligations_append_only_v1()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    RAISE EXCEPTION 'order_obligations is append-only: UPDATE is forbidden (order_uid=%, revision=%)', OLD.order_uid, OLD.revision
      USING ERRCODE = '0A000';
  END IF;
  RAISE EXCEPTION 'order_obligations is append-only: DELETE is forbidden (order_uid=%, revision=%)', OLD.order_uid, OLD.revision
    USING ERRCODE = '0A000';
END;
$function$;

CREATE OR REPLACE FUNCTION public.order_post_payment_v1(p_workspace_id uuid, p_by_actor text, p_by_sid_hash text, p_order_uid uuid, p_payment_method text, p_mode text, p_amount numeric, p_client_request_id text, p_request_hash text, p_meta jsonb, p_confirm_duplicate boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE
  v_actor public.auth_actors%ROWTYPE;
  v_entity public.order_entities%ROWTYPE;
  v_ord public.ordenes%ROWTYPE;
  v_existing public.payment_transactions%ROWTYPE;
  v_tx public.payment_transactions%ROWTYPE;
  v_meta jsonb := COALESCE(p_meta, '{}'::jsonb);
  v_now timestamptz := now();
  v_obligation_cents bigint;
  v_paid_before_cents bigint;
  v_outstanding_cents bigint;
  v_amount_cents bigint;
  v_receipt_service_id uuid;
  v_duplicate_candidate boolean;
  v_prev_state text;
  v_new_state text;
  v_new_paid_cents bigint;
  v_scope text;
  v_method_count integer;
  v_method_max text;
  v_is_paid boolean;
  v_method_projection text;
BEGIN
  IF p_workspace_id IS NULL OR p_order_uid IS NULL
     OR p_by_actor IS NULL OR btrim(p_by_actor) = ''
     OR p_by_sid_hash IS NULL OR p_by_sid_hash !~ '^[0-9a-f]{64}$'
     OR p_payment_method NOT IN ('efectivo','tarjeta','bizum')
     OR p_mode NOT IN ('full','custom_amount')
     OR p_client_request_id IS NULL OR length(p_client_request_id) NOT BETWEEN 8 AND 128
     OR p_client_request_id !~ '^[A-Za-z0-9_-]+$'
     OR p_request_hash IS NULL OR p_request_hash !~ '^[0-9a-f]{64}$'
     OR jsonb_typeof(v_meta) <> 'object' OR length(v_meta::text) > 2048
  THEN RAISE EXCEPTION 'ORDER_PAYMENT_INVALID' USING ERRCODE='22023'; END IF;
  IF EXISTS (SELECT 1 FROM jsonb_object_keys(v_meta) k WHERE lower(k) = ANY (ARRAY[
    'pin','pin_hash','password','token','access_token','refresh_token','jwt','secret',
    'authorization','api_key','apikey','bearer','cookie','raw_ip','sid','proof'
  ])) THEN RAISE EXCEPTION 'ORDER_PAYMENT_META_INVALID' USING ERRCODE='22023'; END IF;

  PERFORM 1 FROM public.workspaces WHERE id = p_workspace_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ORDER_PAYMENT_WORKSPACE_NOT_FOUND' USING ERRCODE='P0002'; END IF;

  SELECT * INTO v_actor FROM public.auth_actors
   WHERE workspace_id = p_workspace_id AND actor = p_by_actor FOR UPDATE;
  -- Preserve the existing Servicio payment gate exactly (order_mark_paid):
  -- admin/operator ONLY. Do NOT widen to Mesa's broader PAYMENT_ROLES
  -- (owner/cashier/legacy_operator) -- an authorization change this slice
  -- does not own (frozen brief §25).
  IF NOT FOUND OR v_actor.active IS NOT TRUE OR v_actor.role NOT IN ('admin','operator')
  THEN RAISE EXCEPTION 'ORDER_PAYMENT_FORBIDDEN' USING ERRCODE='42501'; END IF;

  SELECT * INTO v_existing FROM public.payment_transactions
   WHERE workspace_id = p_workspace_id AND client_request_id = p_client_request_id;
  IF FOUND THEN
    IF v_existing.request_hash <> p_request_hash THEN
      RAISE EXCEPTION 'ORDER_PAYMENT_IDEMPOTENCY_CONFLICT' USING ERRCODE='23505'; END IF;
    IF p_by_actor <> v_existing.by_actor THEN
      INSERT INTO public.auth_audit(event, target_actor, by_actor, meta)
      VALUES ('PAYMENT_REPLAY_DIFFERENT_ACTOR', v_existing.by_actor, p_by_actor,
        jsonb_build_object('transactionId', v_existing.id, 'clientRequestId', p_client_request_id,
          'originalBySidHash', v_existing.by_sid_hash, 'replayingBySidHash', p_by_sid_hash,
          'replayingRole', v_actor.role));
    END IF;
    RETURN jsonb_build_object('ok', true, 'idempotent', true, 'transactionId', v_existing.id,
      'amount', v_existing.amount, 'paymentMethod', v_existing.payment_method, 'mode', v_existing.mode,
      'orderUid', p_order_uid);
  END IF;

  -- The permanent identity anchor -- resolves workspace/service/display id
  -- without trusting the client. A Mesa order's entity carries a non-null
  -- table_session_id; refuse it here so a table order can never bypass
  -- mesa_post_payment_v1's covers/line authority through this route.
  SELECT * INTO v_entity FROM public.order_entities WHERE order_uid = p_order_uid FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ORDER_PAYMENT_ORDER_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  IF v_entity.workspace_id <> p_workspace_id THEN
    RAISE EXCEPTION 'ORDER_PAYMENT_WORKSPACE_MISMATCH' USING ERRCODE='22023'; END IF;
  IF v_entity.table_session_id IS NOT NULL THEN
    RAISE EXCEPTION 'ORDER_PAYMENT_NOT_FOR_TABLE_ORDER' USING ERRCODE='22023',
      DETAIL = format('order_uid=%s table_session=%s', p_order_uid, v_entity.table_session_id);
  END IF;

  SELECT * INTO v_ord FROM public.ordenes WHERE order_uid = p_order_uid FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ORDER_PAYMENT_ORDER_NOT_FOUND' USING ERRCODE='P0002'; END IF;

  -- Economic Writer Hardening V1 (migration 126) — refuse a cancelled/annulled order
  -- BEFORE any money fact is created. order_cancel_v1 already revises the obligation to 0,
  -- so ORDER_PAYMENT_ALREADY_SETTLED would eventually catch a zero-outstanding order too --
  -- but a cancelled order predating N-2 (fallback totale, no obligation row) or one
  -- cancelled while still carrying an outstanding balance must never be allowed to look
  -- like an ordinary payment. No payment_transaction, allocation, OFE row or mirror update
  -- happens.
  IF upper(COALESCE(v_ord.estado, '')) IN ('CANCELADO', 'CANCELLED', 'ANULADO') THEN
    RAISE EXCEPTION 'ORDER_PAYMENT_ORDER_CANCELLED' USING ERRCODE='22023',
      DETAIL = format('order_uid=%s estado=%s -- payment refused on a cancelled/annulled order', p_order_uid, v_ord.estado);
  END IF;

  v_obligation_cents := round(public.order_canonical_obligation_v1(p_order_uid) * 100)::bigint;
  SELECT COALESCE(round(sum(CASE WHEN e.type='refund' THEN -e.amount ELSE e.amount END) * 100), 0)::bigint
    INTO v_paid_before_cents
    FROM public.order_financial_events e
   WHERE e.service_session_id = v_ord.service_session_id AND e.order_id = v_ord.id
     AND e.type IN ('payment','payment_imported','refund');
  v_outstanding_cents := GREATEST(0, v_obligation_cents - v_paid_before_cents);
  IF v_outstanding_cents <= 0 THEN RAISE EXCEPTION 'ORDER_PAYMENT_ALREADY_SETTLED' USING ERRCODE='55000'; END IF;

  IF p_mode = 'full' THEN
    v_amount_cents := v_outstanding_cents;
  ELSE
    v_amount_cents := round(COALESCE(p_amount, 0) * 100)::bigint;
  END IF;
  IF v_amount_cents <= 0 OR v_amount_cents > v_outstanding_cents THEN
    RAISE EXCEPTION 'ORDER_PAYMENT_AMOUNT_INVALID' USING ERRCODE='22023'; END IF;

  SELECT EXISTS (
    SELECT 1 FROM public.payment_transactions pt
    JOIN public.payment_allocations pa ON pa.payment_transaction_id = pt.id
     WHERE pa.order_uid = p_order_uid
       AND pt.client_request_id <> p_client_request_id
       AND pt.kind = 'payment' AND pt.mode = p_mode
       AND pt.amount = (v_amount_cents / 100.0) AND pt.payment_method = p_payment_method
       AND pt.created_at > (v_now - interval '120 seconds')
  ) INTO v_duplicate_candidate;
  IF v_duplicate_candidate AND NOT p_confirm_duplicate THEN
    RAISE EXCEPTION 'ORDER_PAYMENT_POSSIBLE_DUPLICATE' USING ERRCODE='55000';
  ELSIF v_duplicate_candidate AND p_confirm_duplicate THEN
    INSERT INTO public.auth_audit(event, target_actor, by_actor, meta)
    VALUES ('PAYMENT_DUPLICATE_CONFIRMED', NULL, p_by_actor,
      jsonb_build_object('orderUid', p_order_uid, 'clientRequestId', p_client_request_id,
        'amount', v_amount_cents / 100.0, 'mode', p_mode, 'paymentMethod', p_payment_method));
  END IF;

  SELECT ss.id INTO v_receipt_service_id
    FROM public.service_session_state sst
    JOIN public.service_sessions ss ON ss.id = sst.current_session_id AND ss.status = 'open'
   WHERE sst.singleton = true;
  IF v_receipt_service_id IS NULL THEN
    RAISE EXCEPTION 'ORDER_PAYMENT_NO_OPEN_SERVICE' USING ERRCODE='55000'; END IF;

  INSERT INTO public.payment_transactions(
    workspace_id, table_session_id, service_session_id, kind, mode, amount,
    payment_method, covers_settled, by_actor, by_role, by_sid_hash,
    client_request_id, request_hash, meta, created_at
  ) VALUES (
    p_workspace_id, NULL, v_receipt_service_id, 'payment', p_mode,
    v_amount_cents / 100.0, p_payment_method, 0,
    p_by_actor, v_actor.role, p_by_sid_hash, p_client_request_id,
    p_request_hash, v_meta, v_now
  ) RETURNING * INTO v_tx;

  -- ONE allocation, order_uid-targeted -- the check-centric invariant (§8/§11/
  -- §28 of the brief): one payment_transactions row = one physical money
  -- movement; for a check, that movement is imputed to exactly one order.
  INSERT INTO public.payment_allocations(
    payment_transaction_id, table_order_line_id, order_id, order_uid, amount, created_at
  ) VALUES (v_tx.id, NULL, v_ord.id, p_order_uid, v_amount_cents / 100.0, v_now);

  v_new_paid_cents := v_paid_before_cents + v_amount_cents;
  v_prev_state := CASE
    WHEN v_paid_before_cents <= 0 THEN 'unpaid'
    WHEN v_paid_before_cents >= v_obligation_cents THEN 'paid'
    ELSE 'partially_paid' END;
  v_new_state := CASE
    WHEN v_new_paid_cents >= v_obligation_cents THEN 'paid'
    ELSE 'partially_paid' END;
  v_scope := 'order_' || replace(v_tx.id::text, '-', '');

  INSERT INTO public.order_financial_events(
    order_id, type, amount, payment_method, reason, legacy, by_actor, by_role,
    prev_estado, new_estado, prev_pay_state, new_pay_state, original_giro_id,
    ip_hash, meta, idem_scope_key, payload_digest, service_session_id,
    event_service_session_id, payment_transaction_id, created_at
  )
  SELECT o.id, 'payment', v_amount_cents / 100.0, p_payment_method,
    NULL, false, p_by_actor, v_actor.role, o.estado, o.estado,
    v_prev_state, v_new_state, NULL, NULL,
    jsonb_build_object('source','order','mode',p_mode,'transaction_id',v_tx.id),
    v_scope,
    encode(digest(concat_ws('|', o.id, v_tx.id::text, v_amount_cents::text,
      p_payment_method, p_by_actor, p_request_hash), 'sha256'), 'hex'),
    o.service_session_id, v_receipt_service_id, v_tx.id, v_now
  FROM public.ordenes o WHERE o.order_uid = p_order_uid;

  -- Same compatibility-mirror projection mesa_post_payment_v1 uses (§12 of
  -- the brief): 'MIXTO' on mixed tender, computed from order_financial_events
  -- so a legacy event-only collection is never lost from the projection.
  SELECT count(DISTINCT e.payment_method), max(e.payment_method)
    INTO v_method_count, v_method_max
    FROM public.order_financial_events e
   WHERE e.service_session_id = v_ord.service_session_id AND e.order_id = v_ord.id
     AND e.type IN ('payment','payment_imported');
  v_is_paid := CASE WHEN v_obligation_cents <= 0 THEN v_new_paid_cents > 0
                     ELSE v_new_paid_cents >= v_obligation_cents END;
  v_method_projection := CASE WHEN v_method_count > 1 THEN 'MIXTO' ELSE v_method_max END;

  UPDATE public.ordenes SET
    cobrado = v_is_paid, ya_pagado = v_is_paid,
    metodo_pago = CASE WHEN v_is_paid THEN v_method_projection ELSE COALESCE(metodo_pago,'') END
  WHERE order_uid = p_order_uid;

  RETURN jsonb_build_object(
    'ok', true, 'idempotent', false, 'transactionId', v_tx.id,
    'amount', v_tx.amount, 'paymentMethod', v_tx.payment_method, 'mode', v_tx.mode,
    'orderUid', p_order_uid, 'displayOrderId', v_entity.display_order_id,
    'currentObligation', v_obligation_cents / 100.0,
    'netCollectedBefore', v_paid_before_cents / 100.0,
    'netCollectedAfter', v_new_paid_cents / 100.0,
    'unpaid', GREATEST(0, v_obligation_cents - v_new_paid_cents) / 100.0,
    'overCollected', GREATEST(0, v_new_paid_cents - v_obligation_cents) / 100.0,
    'serviceSessionId', v_receipt_service_id
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.order_post_refund_v1(p_workspace_id uuid, p_by_actor text, p_by_sid_hash text, p_order_uid uuid, p_original_transaction_id uuid, p_reason text, p_client_request_id text, p_request_hash text, p_amount numeric, p_meta jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE
  v_actor public.auth_actors%ROWTYPE;
  v_entity public.order_entities%ROWTYPE;
  v_ord public.ordenes%ROWTYPE;
  v_existing public.payment_transactions%ROWTYPE;
  v_original public.payment_transactions%ROWTYPE;
  v_alloc public.payment_allocations%ROWTYPE;
  v_refund_tx public.payment_transactions%ROWTYPE;
  v_now timestamptz := now();
  v_meta jsonb := COALESCE(p_meta, '{}'::jsonb);
  v_reason text;
  v_remaining_cents bigint;
  v_amount_cents bigint;
  v_remaining_after_cents bigint;
  v_receipt_service_id uuid;
  v_settlement text;
  v_obligation_cents bigint;
  v_paid_before_cents bigint;
  v_new_paid_cents bigint;
  v_prev_state text;
  v_new_state text;
  v_scope text;
  v_method_count integer;
  v_method_max text;
  v_is_paid boolean;
  v_method_projection text;
  v_audit_id bigint;
BEGIN
  IF p_workspace_id IS NULL OR p_order_uid IS NULL OR p_original_transaction_id IS NULL
     OR p_by_actor IS NULL OR btrim(p_by_actor) = ''
     OR p_by_sid_hash IS NULL OR p_by_sid_hash !~ '^[0-9a-f]{64}$'
     OR p_client_request_id IS NULL OR length(p_client_request_id) NOT BETWEEN 8 AND 128
     OR p_client_request_id !~ '^[A-Za-z0-9_-]+$'
     OR p_request_hash IS NULL OR p_request_hash !~ '^[0-9a-f]{64}$'
     OR jsonb_typeof(v_meta) <> 'object' OR length(v_meta::text) > 2048
  THEN RAISE EXCEPTION 'ORDER_REFUND_INVALID' USING ERRCODE='22023'; END IF;

  IF p_reason IS NULL OR btrim(p_reason) = '' THEN
    RAISE EXCEPTION 'ORDER_REFUND_REASON_REQUIRED' USING ERRCODE='22023'; END IF;
  v_reason := btrim(p_reason);

  IF p_amount IS NOT NULL AND p_amount <= 0 THEN
    RAISE EXCEPTION 'ORDER_REFUND_AMOUNT_INVALID' USING ERRCODE='22023'; END IF;

  IF EXISTS (SELECT 1 FROM jsonb_object_keys(v_meta) k WHERE lower(k) = ANY (ARRAY[
    'pin','pin_hash','password','token','access_token','refresh_token','jwt','secret',
    'authorization','api_key','apikey','bearer','cookie','raw_ip','sid','proof'
  ])) THEN RAISE EXCEPTION 'ORDER_REFUND_META_INVALID' USING ERRCODE='22023'; END IF;

  PERFORM 1 FROM public.workspaces WHERE id = p_workspace_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ORDER_REFUND_WORKSPACE_NOT_FOUND' USING ERRCODE='P0002'; END IF;

  SELECT * INTO v_actor FROM public.auth_actors
   WHERE workspace_id = p_workspace_id AND actor = p_by_actor FOR UPDATE;
  -- REFUND_ROLES, identical to Mesa: admin/owner only (¬ß25, no widening --
  -- the role that takes money is deliberately not the one that returns it).
  IF NOT FOUND OR v_actor.active IS NOT TRUE OR v_actor.role NOT IN ('admin','owner')
  THEN RAISE EXCEPTION 'ORDER_REFUND_FORBIDDEN' USING ERRCODE='42501'; END IF;

  SELECT * INTO v_existing FROM public.payment_transactions
   WHERE workspace_id = p_workspace_id AND client_request_id = p_client_request_id;
  IF FOUND THEN
    IF v_existing.request_hash <> p_request_hash THEN
      RAISE EXCEPTION 'ORDER_REFUND_IDEMPOTENCY_CONFLICT' USING ERRCODE='23505'; END IF;
    IF p_by_actor <> v_existing.by_actor THEN
      INSERT INTO public.auth_audit(event, target_actor, by_actor, meta)
      VALUES ('PAYMENT_REPLAY_DIFFERENT_ACTOR', v_existing.by_actor, p_by_actor,
        jsonb_build_object('transactionId', v_existing.id, 'clientRequestId', p_client_request_id,
          'originalBySidHash', v_existing.by_sid_hash, 'replayingBySidHash', p_by_sid_hash,
          'replayingRole', v_actor.role));
    END IF;
    SELECT round(pt.amount*100)::bigint - COALESCE((
        SELECT sum(round(r.amount*100))::bigint FROM public.payment_transactions r
         WHERE r.kind='refund' AND r.reverses_transaction_id = pt.id
      ),0) INTO v_remaining_after_cents
      FROM public.payment_transactions pt WHERE pt.id = v_existing.reverses_transaction_id;
    RETURN jsonb_build_object('ok', true, 'idempotent', true,
      'refundTransactionId', v_existing.id, 'reversesTransactionId', v_existing.reverses_transaction_id,
      'amount', v_existing.amount, 'paymentMethod', v_existing.payment_method,
      'refundableRemainingOnOriginal', COALESCE(v_remaining_after_cents,0) / 100.0,
      'orderUid', p_order_uid);
  END IF;

  SELECT * INTO v_entity FROM public.order_entities WHERE order_uid = p_order_uid;
  IF NOT FOUND THEN RAISE EXCEPTION 'ORDER_REFUND_ORDER_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  IF v_entity.workspace_id <> p_workspace_id THEN
    RAISE EXCEPTION 'ORDER_REFUND_WORKSPACE_MISMATCH' USING ERRCODE='22023'; END IF;

  SELECT * INTO v_ord FROM public.ordenes WHERE order_uid = p_order_uid FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ORDER_REFUND_ORDER_NOT_FOUND' USING ERRCODE='P0002'; END IF;

  -- Lock the ORIGINAL transaction -- serialises concurrent over-refund
  -- attempts exactly like mesa_post_refund_v1.
  SELECT * INTO v_original FROM public.payment_transactions
   WHERE id = p_original_transaction_id AND workspace_id = p_workspace_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ORDER_REFUND_TRANSACTION_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  IF v_original.kind <> 'payment' THEN RAISE EXCEPTION 'ORDER_REFUND_NOT_REFUNDABLE' USING ERRCODE='55000'; END IF;
  -- A Mesa (table-bound) transaction can never be refunded through this
  -- check-centric route -- symmetric to the null-safe guard mesa_post_
  -- refund_v1 now carries (¬ß28 of the brief).
  IF v_original.table_session_id IS NOT NULL THEN
    RAISE EXCEPTION 'ORDER_REFUND_NOT_CHECK_CENTRIC' USING ERRCODE='55000'; END IF;

  SELECT * INTO v_alloc FROM public.payment_allocations
   WHERE payment_transaction_id = v_original.id AND table_order_line_id IS NULL;
  IF NOT FOUND OR v_alloc.order_uid IS DISTINCT FROM p_order_uid THEN
    RAISE EXCEPTION 'ORDER_REFUND_TRANSACTION_MISMATCH' USING ERRCODE='55000'; END IF;

  SELECT round(v_original.amount*100)::bigint - COALESCE((
      SELECT sum(round(r.amount*100))::bigint FROM public.payment_transactions r
       WHERE r.kind='refund' AND r.reverses_transaction_id = v_original.id
    ),0) INTO v_remaining_cents;
  IF v_remaining_cents <= 0 THEN RAISE EXCEPTION 'ORDER_REFUND_ALREADY_FULL' USING ERRCODE='55000'; END IF;

  v_amount_cents := CASE WHEN p_amount IS NULL THEN v_remaining_cents ELSE round(p_amount*100)::bigint END;
  IF v_amount_cents <= 0 THEN RAISE EXCEPTION 'ORDER_REFUND_AMOUNT_INVALID' USING ERRCODE='22023'; END IF;
  IF v_amount_cents > v_remaining_cents THEN RAISE EXCEPTION 'ORDER_REFUND_EXCEEDS_REMAINING' USING ERRCODE='55000'; END IF;

  SELECT ss.id INTO v_receipt_service_id
    FROM public.service_session_state sst
    JOIN public.service_sessions ss ON ss.id = sst.current_session_id AND ss.status = 'open'
   WHERE sst.singleton = true;

  -- ¬ßH.4 -- record, don't claim: tarjeta/bizum note that La Dieci is
  -- RECORDING an externally executed return, never that it executed a
  -- bank/POS operation. Identical language to mesa_post_refund_v1.
  v_settlement := CASE WHEN v_original.payment_method = 'efectivo' THEN 'drawer' ELSE 'external' END;

  -- The refund's payment_method is FORCED from the original -- same-tender
  -- invariant, no caller-supplied method exists in this signature.
  INSERT INTO public.payment_transactions(
    workspace_id, table_session_id, service_session_id, kind, mode, amount,
    payment_method, covers_settled, reverses_transaction_id, by_actor, by_role,
    by_sid_hash, client_request_id, request_hash, meta, created_at
  ) VALUES (
    p_workspace_id, NULL, v_receipt_service_id, 'refund', 'refund',
    v_amount_cents / 100.0, v_original.payment_method, 0, v_original.id,
    p_by_actor, v_actor.role, p_by_sid_hash, p_client_request_id, p_request_hash, v_meta, v_now
  ) RETURNING * INTO v_refund_tx;

  INSERT INTO public.payment_allocations(
    payment_transaction_id, table_order_line_id, order_id, order_uid, amount, created_at
  ) VALUES (v_refund_tx.id, NULL, v_alloc.order_id, p_order_uid, v_amount_cents / 100.0, v_now);

  v_obligation_cents := round(public.order_canonical_obligation_v1(p_order_uid) * 100)::bigint;
  SELECT COALESCE(round(sum(CASE WHEN e.type='refund' THEN -e.amount ELSE e.amount END) * 100), 0)::bigint
    INTO v_paid_before_cents
    FROM public.order_financial_events e
   WHERE e.service_session_id = v_ord.service_session_id AND e.order_id = v_ord.id
     AND e.type IN ('payment','payment_imported','refund');
  v_prev_state := CASE
    WHEN v_paid_before_cents <= 0 THEN 'unpaid'
    WHEN v_paid_before_cents >= v_obligation_cents THEN 'paid'
    ELSE 'partially_paid' END;
  v_new_paid_cents := v_paid_before_cents - v_amount_cents;
  v_new_state := CASE
    WHEN v_new_paid_cents <= 0 THEN 'unpaid'
    WHEN v_new_paid_cents >= v_obligation_cents THEN 'paid'
    ELSE 'partially_paid' END;
  v_scope := 'order_' || replace(v_refund_tx.id::text, '-', '');

  INSERT INTO public.order_financial_events(
    order_id, type, amount, payment_method, reason, legacy, by_actor, by_role,
    prev_estado, new_estado, prev_pay_state, new_pay_state, original_giro_id,
    ip_hash, meta, idem_scope_key, payload_digest, service_session_id,
    event_service_session_id, payment_transaction_id, created_at
  )
  SELECT o.id, 'refund', v_amount_cents / 100.0, v_original.payment_method,
    v_reason, false, p_by_actor, v_actor.role, o.estado, o.estado,
    v_prev_state, v_new_state, NULL, NULL,
    jsonb_build_object('source','order','mode','refund','transaction_id',v_refund_tx.id,
      'reverses_transaction_id', v_original.id, 'settlement', v_settlement),
    v_scope,
    encode(digest(concat_ws('|', o.id, v_refund_tx.id::text, v_amount_cents::text,
      v_original.payment_method, p_by_actor, p_request_hash), 'sha256'), 'hex'),
    o.service_session_id, v_receipt_service_id, v_refund_tx.id, v_now
  FROM public.ordenes o WHERE o.order_uid = p_order_uid;

  SELECT count(DISTINCT e.payment_method), max(e.payment_method)
    INTO v_method_count, v_method_max
    FROM public.order_financial_events e
   WHERE e.service_session_id = v_ord.service_session_id AND e.order_id = v_ord.id
     AND e.type IN ('payment','payment_imported');
  v_is_paid := CASE WHEN v_obligation_cents <= 0 THEN v_new_paid_cents > 0
                     ELSE v_new_paid_cents >= v_obligation_cents END;
  v_method_projection := CASE WHEN v_method_count > 1 THEN 'MIXTO' ELSE v_method_max END;

  -- ordenes.refunded is deliberately never set here -- it means "fully
  -- refunded" in the LEGACY sense and would misstate a partial reversal
  -- (identical reasoning to mesa_post_refund_v1).
  UPDATE public.ordenes SET
    cobrado = v_is_paid, ya_pagado = v_is_paid,
    metodo_pago = CASE WHEN v_is_paid THEN v_method_projection ELSE COALESCE(metodo_pago,'') END
  WHERE order_uid = p_order_uid;

  v_remaining_after_cents := v_remaining_cents - v_amount_cents;

  INSERT INTO public.auth_audit(event, target_actor, by_actor, meta)
  VALUES ('ORDER_PAYMENT_REFUNDED', v_original.by_actor, p_by_actor,
    jsonb_build_object('orderUid', p_order_uid, 'originalTransactionId', v_original.id,
      'refundTransactionId', v_refund_tx.id, 'amount', v_amount_cents / 100.0,
      'paymentMethod', v_original.payment_method, 'reason', v_reason,
      'clientRequestId', p_client_request_id,
      'refundableRemainingAfter', v_remaining_after_cents / 100.0)
  ) RETURNING id INTO v_audit_id;

  RETURN jsonb_build_object(
    'ok', true, 'idempotent', false,
    'refundTransactionId', v_refund_tx.id, 'reversesTransactionId', v_original.id,
    'amount', v_refund_tx.amount, 'paymentMethod', v_refund_tx.payment_method,
    'originalAmount', v_original.amount,
    'refundedTotalOnOriginal', (round(v_original.amount*100)::bigint - v_remaining_after_cents) / 100.0,
    'refundableRemainingOnOriginal', v_remaining_after_cents / 100.0,
    'orderUid', p_order_uid,
    'currentObligation', v_obligation_cents / 100.0,
    'netCollectedAfter', v_new_paid_cents / 100.0,
    'unpaidAfter', GREATEST(0, v_obligation_cents - v_new_paid_cents) / 100.0,
    'overCollectedAfter', GREATEST(0, v_new_paid_cents - v_obligation_cents) / 100.0,
    'auditId', v_audit_id
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.order_refund(p_order_id text, p_reason text, p_by_actor text, p_session_version integer, p_ip_hash text, p_meta jsonb, p_idem_scope_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_by public.auth_actors%ROWTYPE; v_ord public.ordenes%ROWTYPE;
  v_basis public.order_financial_events%ROWTYPE; v_existing public.order_financial_events%ROWTYPE;
  v_existing_refund public.order_financial_events%ROWTYPE; v_new public.order_financial_events%ROWTYPE;
  v_role text; v_reason text; v_meta jsonb := COALESCE(p_meta, '{}'::jsonb);
  v_canon jsonb; v_digest text; v_replay_digest text;
BEGIN
  IF jsonb_typeof(v_meta) <> 'object' THEN RAISE EXCEPTION 'AUTH_META_INVALID' USING ERRCODE='22023'; END IF;
  IF length(v_meta::text) > 2048 THEN RAISE EXCEPTION 'AUTH_META_TOO_LARGE' USING ERRCODE='22023'; END IF;
  IF EXISTS (SELECT 1 FROM jsonb_object_keys(v_meta) k WHERE lower(k) = ANY (ARRAY[
       'pin','pin_hash','password','token','access_token','refresh_token','jwt','secret',
       'recovery_secret','authorization','api_key','apikey','bearer','cookie','raw_ip','confirmation']))
  THEN RAISE EXCEPTION 'AUTH_META_SENSITIVE_KEY' USING ERRCODE='22023'; END IF;
  IF p_ip_hash IS NULL OR btrim(p_ip_hash) = '' THEN RAISE EXCEPTION 'AUTH_IP_HASH_REQUIRED' USING ERRCODE='22023'; END IF;
  IF length(p_ip_hash) > 64 THEN RAISE EXCEPTION 'AUTH_IP_HASH_TOO_LONG' USING ERRCODE='22023'; END IF;
  IF p_idem_scope_key IS NULL OR char_length(p_idem_scope_key) < 8 OR char_length(p_idem_scope_key) > 128
     OR p_idem_scope_key !~ '^[A-Za-z0-9_-]+$'
  THEN RAISE EXCEPTION 'AUTH_IDEM_KEY_INVALID' USING ERRCODE='22023'; END IF;
  IF p_session_version IS NULL OR p_session_version < 1 THEN RAISE EXCEPTION 'AUTH_SESSION_STALE' USING ERRCODE='22023'; END IF;
  IF p_reason IS NULL OR btrim(p_reason) = '' THEN RAISE EXCEPTION 'AUTH_REASON_BLANK' USING ERRCODE='22023'; END IF;
  v_reason := btrim(p_reason);
  SELECT * INTO v_by FROM public.auth_actors WHERE actor = p_by_actor FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'AUTH_ACTOR_NOT_FOUND' USING ERRCODE='P0002'; END IF;
  IF v_by.active <> true THEN RAISE EXCEPTION 'AUTH_INITIATOR_INACTIVE' USING ERRCODE='22023'; END IF;
  v_role := v_by.role;
  IF v_role <> 'admin' THEN RAISE EXCEPTION 'AUTH_FORBIDDEN_ROLE' USING ERRCODE='22023'; END IF;
  IF p_session_version <> v_by.session_version THEN RAISE EXCEPTION 'AUTH_SESSION_STALE' USING ERRCODE='22023'; END IF;
  SELECT * INTO v_ord FROM public.ordenes WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'AUTH_ORDER_NOT_FOUND' USING ERRCODE='P0002'; END IF;

  -- Economic Writer Hardening V1 (migration 126) -- Mesa orders are refunded exclusively
  -- through mesa_post_refund_v1 (a reversal of an exact payment_transaction). This legacy
  -- "first basis" refund has no way to name a transaction and must never touch a table
  -- order's per-line settlement.
  IF v_ord.table_session_id IS NOT NULL THEN
    RAISE EXCEPTION 'AUTH_MESA_ORDER_NOT_ALLOWED' USING ERRCODE='22023',
      DETAIL = format('order_id=%s is Mesa-owned (table_session_id=%s) -- legacy refund is not permitted on table orders, use mesa_post_refund_v1', p_order_id, v_ord.table_session_id);
  END IF;

  -- N-6 — financial ownership must be provable before any money is touched.
  IF v_ord.service_session_id IS NULL THEN
    RAISE EXCEPTION 'ORDER_WITHOUT_SERVICE_SESSION' USING ERRCODE='22023',
      DETAIL = format('order_id=%s has no service session -- financial ownership cannot be proven', p_order_id);
  END IF;
  -- REFUND V1 §J.1 — refuse, never delegate. order_refund has no amount parameter
  -- and no way to name a transaction, so delegating to mesa_post_refund_v1 would
  -- mean GUESSING which payment and how much — the exact defect this closes.
  -- Keyed on transaction-backed EVIDENCE, not on table_session_id: a non-Mesa order
  -- can never carry a payment_transaction_id, so this changes nothing for legacy
  -- non-Mesa orders.
  IF EXISTS (SELECT 1 FROM public.order_financial_events e
              WHERE e.order_id = p_order_id
                AND e.service_session_id IS NOT DISTINCT FROM v_ord.service_session_id
                AND e.payment_transaction_id IS NOT NULL)
  THEN RAISE EXCEPTION 'AUTH_REFUND_TRANSACTION_BACKED' USING ERRCODE='22023',
    DETAIL = format('order_id=%s settled through payment_transactions -- use mesa_post_refund_v1', p_order_id);
  END IF;
  SELECT * INTO v_existing FROM public.order_financial_events
    WHERE order_id = p_order_id AND type = 'refund' AND idem_scope_key = p_idem_scope_key
      AND service_session_id IS NOT DISTINCT FROM v_ord.service_session_id;
  IF FOUND THEN
    SELECT * INTO v_basis FROM public.order_financial_events
      WHERE order_id = p_order_id AND type IN ('payment','payment_imported')
        AND service_session_id IS NOT DISTINCT FROM v_ord.service_session_id
      ORDER BY created_at ASC LIMIT 1;
    IF NOT FOUND OR v_basis.amount IS DISTINCT FROM v_existing.amount
       OR v_basis.payment_method IS DISTINCT FROM v_existing.payment_method
    THEN RAISE EXCEPTION 'AUTH_REFUND_BASIS_INTEGRITY' USING ERRCODE='22023'; END IF;
    v_replay_digest := lower(encode(sha256(convert_to((jsonb_build_object(
      'order_id', v_existing.order_id, 'type', 'refund', 'idem_scope_key', v_existing.idem_scope_key,
      'by_actor', p_by_actor, 'by_role', v_role, 'reason', v_reason,
      'prev_estado', v_existing.prev_estado, 'new_estado', v_existing.new_estado,
      'prev_pay_state', v_existing.prev_pay_state, 'new_pay_state', v_existing.new_pay_state,
      'basis_event_id', v_basis.id, 'amount', v_existing.amount,
      'payment_method', v_existing.payment_method, 'legacy', v_existing.legacy))::text, 'UTF8')), 'hex'));
    IF v_existing.payload_digest = v_replay_digest THEN
      RETURN jsonb_build_object('event_id', v_existing.id, 'order_id', v_existing.order_id,
        'type', v_existing.type, 'amount', v_existing.amount, 'payment_method', v_existing.payment_method,
        'prev_estado', v_existing.prev_estado, 'new_estado', v_existing.new_estado,
        'prev_pay_state', v_existing.prev_pay_state, 'new_pay_state', v_existing.new_pay_state,
        'legacy', v_existing.legacy, 'original_giro_id', v_existing.original_giro_id,
        'idempotent', true, 'created_at', v_existing.created_at);
    END IF;
    RAISE EXCEPTION 'AUTH_IDEMPOTENCY_CONFLICT' USING ERRCODE='22023';
  END IF;
  SELECT * INTO v_basis FROM public.order_financial_events
    WHERE order_id = p_order_id AND type IN ('payment','payment_imported')
      AND service_session_id IS NOT DISTINCT FROM v_ord.service_session_id
    ORDER BY created_at ASC LIMIT 1;
  IF NOT FOUND THEN RAISE EXCEPTION 'AUTH_NO_PAYMENT_BASIS' USING ERRCODE='22023'; END IF;
  SELECT * INTO v_existing_refund FROM public.order_financial_events
    WHERE order_id = p_order_id AND type = 'refund'
      AND service_session_id IS NOT DISTINCT FROM v_ord.service_session_id
    ORDER BY created_at ASC LIMIT 1;
  IF FOUND THEN RAISE EXCEPTION 'AUTH_ALREADY_REFUNDED' USING ERRCODE='22023'; END IF;
  v_canon := jsonb_build_object(
    'order_id', p_order_id, 'type', 'refund', 'idem_scope_key', p_idem_scope_key,
    'by_actor', p_by_actor, 'by_role', v_role, 'reason', v_reason,
    'prev_estado', v_ord.estado, 'new_estado', v_ord.estado,
    'prev_pay_state', 'paid', 'new_pay_state', 'refunded',
    'basis_event_id', v_basis.id, 'amount', v_basis.amount,
    'payment_method', v_basis.payment_method, 'legacy', false);
  v_digest := lower(encode(sha256(convert_to(v_canon::text, 'UTF8')), 'hex'));
  INSERT INTO public.order_financial_events(
    order_id, type, amount, payment_method, reason, legacy, by_actor, by_role,
    prev_estado, new_estado, prev_pay_state, new_pay_state, original_giro_id,
    ip_hash, meta, idem_scope_key, payload_digest)
  VALUES (p_order_id, 'refund', v_basis.amount, v_basis.payment_method, v_reason, false, p_by_actor, v_role,
    v_ord.estado, v_ord.estado, 'paid', 'refunded', NULL,
    p_ip_hash, v_meta, p_idem_scope_key, v_digest)
  RETURNING * INTO v_new;
  UPDATE public.ordenes SET refunded = true WHERE id = p_order_id;
  RETURN jsonb_build_object('event_id', v_new.id, 'order_id', v_new.order_id,
    'type', v_new.type, 'amount', v_new.amount, 'payment_method', v_new.payment_method,
    'prev_estado', v_new.prev_estado, 'new_estado', v_new.new_estado,
    'prev_pay_state', v_new.prev_pay_state, 'new_pay_state', v_new.new_pay_state,
    'legacy', v_new.legacy, 'original_giro_id', v_new.original_giro_id,
    'idempotent', false, 'created_at', v_new.created_at);
END;
$function$;

CREATE OR REPLACE FUNCTION public.order_void(p_order_id text, p_reason text, p_by_actor text, p_session_version integer, p_ip_hash text, p_meta jsonb, p_idem_scope_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  -- RETIREMENT STUB (Economic Writer Hardening V1, migration 126). order_void duplicated
  -- order_cancel_v1's cancellation core with a weaker pay-state inference (first event
  -- wins) and no Mesa fence -- a race hazard the audit classed DORMANT_BUT_REACHABLE with
  -- zero live events. This function changes NO order's state or obligation, unconditionally.
  RAISE EXCEPTION 'LEGACY_VOID_RETIRED_USE_ORDER_CANCEL' USING ERRCODE='22023',
    DETAIL = format('order_id=%s -- order_void is retired', p_order_id),
    HINT = 'Cancel through order_cancel_v1 (updateEstado / cambiaStato with estado=CANCELADO), the canonical cancellation core shared by Mesa and Nuevo Pedido.';
END;
$function$;

CREATE OR REPLACE FUNCTION public.paid_order_economic_mutation_guard_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_field   text;
  v_old     text;
  v_new     text;
  v_session uuid := OLD.service_session_id;
BEGIN
  -- STEP 1 — did the economic basis actually MOVE? Column presence in the SET
  -- list is not a change; only a differing VALUE is. IS DISTINCT FROM is also
  -- NULL-correct on the three nullable descuento columns.
  IF NEW.totale IS DISTINCT FROM OLD.totale THEN
    v_field := 'totale'; v_old := OLD.totale::text; v_new := NEW.totale::text;
  ELSIF NEW.delivery_fee IS DISTINCT FROM OLD.delivery_fee THEN
    v_field := 'delivery_fee'; v_old := OLD.delivery_fee::text; v_new := NEW.delivery_fee::text;
  ELSIF NEW.descuento_tipo IS DISTINCT FROM OLD.descuento_tipo THEN
    v_field := 'descuento_tipo'; v_old := OLD.descuento_tipo; v_new := NEW.descuento_tipo;
  ELSIF NEW.descuento_valor IS DISTINCT FROM OLD.descuento_valor THEN
    v_field := 'descuento_valor'; v_old := OLD.descuento_valor::text; v_new := NEW.descuento_valor::text;
  ELSIF NEW.descuento_importe IS DISTINCT FROM OLD.descuento_importe THEN
    v_field := 'descuento_importe'; v_old := OLD.descuento_importe::text; v_new := NEW.descuento_importe::text;
  ELSE
    -- Nothing economic moved: a state-only / metadata-only update, or an
    -- identical rewrite. Never this guard's business.
    RETURN NEW;
  END IF;

  -- STEP 2 — has any money ever been evidenced for THIS order, in ITS service?
  IF OLD.ya_pagado IS TRUE OR OLD.cobrado IS TRUE
     OR NEW.ya_pagado IS TRUE OR NEW.cobrado IS TRUE
     OR EXISTS (
          SELECT 1 FROM public.order_financial_events e
           WHERE e.order_id = OLD.id
             AND (v_session IS NULL OR e.service_session_id IS NULL OR e.service_session_id = v_session)
        )
     OR EXISTS (
          SELECT 1 FROM public.payment_allocations pa
            JOIN public.payment_transactions pt ON pt.id = pa.payment_transaction_id
           WHERE pa.order_id = OLD.id
             AND (v_session IS NULL OR pt.service_session_id IS NULL OR pt.service_session_id = v_session)
        )
  THEN
    RAISE EXCEPTION 'PAID_ORDER_ECONOMIC_MUTATION_FORBIDDEN'
      USING ERRCODE = 'P0001',
            DETAIL  = format('order_id=%s field=%s old=%s new=%s',
                             OLD.id, v_field, COALESCE(v_old, '<null>'), COALESCE(v_new, '<null>')),
            HINT    = 'This order already carries payment evidence. Its economic basis can only be changed through an explicit financial adjustment workflow.';
  END IF;

  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.payment_transactions_stamp_economic_period_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  NEW.economic_period_kind := public.classify_economic_period_v1(clock_timestamp());
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.resolve_order_intake_context_v1(p_actor text DEFAULT 'order_intake_v1'::text, p_source text DEFAULT 'order_intake_v1'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_madrid              timestamp;
  v_minutes_of_day      integer;
  v_policy              jsonb;
  v_business_date       date;
  v_service_kind        text;
  v_can_create_order    boolean;
  v_pointer             public.business_day_lifecycle_state%ROWTYPE;
  v_day                 public.business_days%ROWTYPE;
  v_period               public.service_sessions%ROWTYPE;
  v_open_result          jsonb;
  v_open_reason          text;
  v_open_source          text;
  v_had_open_or_closing  boolean;
  v_continuity           boolean;
  v_ticket_epoch          integer;
BEGIN
  v_madrid := clock_timestamp() AT TIME ZONE 'Europe/Madrid';
  v_minutes_of_day := extract(hour FROM v_madrid)::integer * 60 + extract(minute FROM v_madrid)::integer;

  v_policy := public.order_intake_policy_v1(v_minutes_of_day);
  v_business_date := CASE WHEN (v_policy->>'businessDateIsPreviousDay')::boolean
                          THEN (v_madrid::date - 1) ELSE v_madrid::date END;
  v_service_kind     := v_policy->>'serviceKind';
  v_can_create_order := (v_policy->>'mayCreateFirstService')::boolean;

  PERFORM pg_advisory_xact_lock(hashtext('service_session_lifecycle'));

  SELECT * INTO v_period FROM public.service_sessions WHERE status IN ('open','closing') FOR UPDATE;
  v_had_open_or_closing := FOUND;

  IF v_had_open_or_closing AND v_period.lifecycle_semantics = 'operational_service_v1' THEN
    -- STALE SERVICE PROTECTION V1 — the Business Day is the grace boundary.
    -- O-3 gave this branch unconditional continuity; it is now bounded to
    -- "the service's own business_date is still the canonical Business Day"
    -- (overnight span included, since v_business_date carries the 04:00
    -- rollover). Once a full Business Day has elapsed the service is stale:
    -- fail closed with a typed refusal so the trigger raises it and no new
    -- order can attach. The JS staleServiceRecovery layer then auto-finalizes
    -- (if AUTO_CLOSE_SAFE) through the one V3 authority, or surfaces
    -- PREVIOUS_SERVICE_PENDING for operator resolution.
    IF v_period.business_date < v_business_date THEN
      RETURN jsonb_build_object(
        'ok', false,
        'code', 'PREVIOUS_SERVICE_PENDING',
        'staleServiceSessionId', v_period.id,
        'staleBusinessDate', v_period.business_date,
        'currentBusinessDate', v_business_date,
        'serviceKind', v_service_kind
      );
    ELSIF v_period.business_date > v_business_date THEN
      -- REVIEW FIX — a FUTURE-dated open service is a lifecycle/business-date
      -- anomaly, never a "previous" service and never ordinary continuity.
      -- Fail closed with the canonical code the opener primitive already uses
      -- for "an active service under a business day other than canonical"
      -- (open_operational_service_v1, ledger 93/96). No recovery path: the JS
      -- layer must not auto-close or reclassify a future-dated service.
      RETURN jsonb_build_object(
        'ok', false,
        'code', 'ACTIVE_SERVICE_BUSINESS_DAY_MISMATCH',
        'serviceSessionId', v_period.id,
        'serviceBusinessDate', v_period.business_date,
        'currentBusinessDate', v_business_date,
        'serviceKind', v_service_kind
      );
    END IF;
    SELECT ticket_epoch INTO v_ticket_epoch FROM public.business_days WHERE id = v_period.business_day_id;
    RETURN jsonb_build_object(
      'ok', true,
      'code', 'RESOLVED',
      'businessDayId', v_period.business_day_id,
      'businessDate', v_period.business_date,
      'periodId', v_period.id,
      'serviceKind', v_service_kind,
      'ticketEpoch', v_ticket_epoch,
      'advanced', false
    );
  END IF;

  v_continuity := false;

  IF NOT v_can_create_order AND NOT v_continuity THEN
    RETURN jsonb_build_object('ok', false, 'code', 'ORDER_INTAKE_CLOSED',
      'businessDate', v_business_date, 'serviceKind', v_service_kind);
  END IF;

  SELECT * INTO v_pointer FROM public.business_day_lifecycle_state WHERE singleton = true FOR UPDATE;

  SELECT * INTO v_day FROM public.business_days WHERE business_date = v_business_date;
  IF NOT FOUND THEN
    INSERT INTO public.business_days (business_date, opened_by, open_source, ticket_epoch, next_ticket_number)
    VALUES (v_business_date, COALESCE(p_actor,'system'), COALESCE(p_source,'order_intake'), 1, 1)
    ON CONFLICT (business_date) DO NOTHING
    RETURNING * INTO v_day;
    IF NOT FOUND THEN
      SELECT * INTO v_day FROM public.business_days WHERE business_date = v_business_date;
    END IF;
  END IF;
  IF v_day.id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'BUSINESS_DAY_UNRESOLVED');
  END IF;

  PERFORM set_config('ladieci.business_day_pointer_authorized', 'true', true);
  UPDATE public.business_day_lifecycle_state
     SET current_business_day_id = v_day.id,
         current_ticket_epoch    = v_day.ticket_epoch,
         updated_at = now()
   WHERE singleton = true;

  SELECT * INTO v_period FROM public.service_sessions
   WHERE business_day_id = v_day.id AND status IN ('open','closing');
  IF NOT FOUND THEN
    IF EXISTS (SELECT 1 FROM public.service_sessions WHERE business_day_id = v_day.id) THEN
      v_open_reason := 'next_service_of_business_day';
      v_open_source := COALESCE(p_source, 'order_intake') || '_next_service';
    ELSE
      v_open_reason := 'first_open_of_business_day';
      v_open_source := COALESCE(p_source, 'order_intake');
    END IF;

    v_open_result := public.open_operational_service_v1(
      COALESCE(p_actor, 'system'), v_open_reason, v_open_source
    );
    IF (v_open_result->>'ok')::boolean IS NOT TRUE THEN
      RETURN jsonb_build_object('ok', false, 'code', 'OPEN_OPERATIONAL_SERVICE_FAILED',
        'reason', v_open_result->>'code', 'openReason', v_open_reason, 'businessDate', v_business_date);
    END IF;
    SELECT * INTO v_period FROM public.service_sessions WHERE id = (v_open_result->'session'->>'id')::uuid;
  END IF;

  v_pointer.current_period_id := v_period.id;

  PERFORM set_config('ladieci.business_day_pointer_authorized', 'true', true);
  UPDATE public.business_day_lifecycle_state
     SET current_period_id = v_pointer.current_period_id, updated_at = now()
   WHERE singleton = true;

  UPDATE public.service_session_state
     SET current_session_id = v_pointer.current_period_id, updated_at = now()
   WHERE singleton = true;

  IF v_period.business_day_id IS DISTINCT FROM v_day.id THEN
    RAISE EXCEPTION 'BUSINESS_DAY_POINTER_MISMATCH' USING ERRCODE='P0001';
  END IF;
  IF (SELECT current_period_id FROM public.business_day_lifecycle_state WHERE singleton = true) IS DISTINCT FROM v_period.id THEN
    RAISE EXCEPTION 'BUSINESS_DAY_POINTER_MISMATCH' USING ERRCODE='P0001';
  END IF;
  IF (SELECT current_ticket_epoch FROM public.business_day_lifecycle_state WHERE singleton = true) IS DISTINCT FROM v_day.ticket_epoch THEN
    RAISE EXCEPTION 'TICKET_EPOCH_MIRROR_MISMATCH' USING ERRCODE='P0001';
  END IF;

  RETURN jsonb_build_object(
    'ok', true, 'code', 'RESOLVED',
    'businessDayId', v_day.id,
    'businessDate', v_business_date,
    'periodId', v_period.id,
    'serviceKind', v_service_kind,
    'ticketEpoch', v_day.ticket_epoch,
    'advanced', true
  );
END $function$;

CREATE OR REPLACE FUNCTION public.resolve_service_incident(p_incident_id uuid, p_resolved_by text, p_actor_role text, p_resolution_type text, p_resolution_status text DEFAULT 'resolved'::text, p_resolution_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_row public.service_incidents%ROWTYPE;
BEGIN
  IF p_actor_role IS DISTINCT FROM 'admin' THEN
    RETURN jsonb_build_object('ok',false,'code','INCIDENT_RESOLUTION_FORBIDDEN');
  END IF;
  IF p_resolved_by IS NULL OR btrim(p_resolved_by) = '' THEN
    RETURN jsonb_build_object('ok',false,'code','INVALID_ACTOR');
  END IF;
  IF p_resolution_status NOT IN ('acknowledged','resolved') THEN
    RETURN jsonb_build_object('ok',false,'code','INVALID_RESOLUTION_STATUS');
  END IF;
  IF p_resolution_type IS NULL OR btrim(p_resolution_type) = '' THEN
    RETURN jsonb_build_object('ok',false,'code','INVALID_RESOLUTION_TYPE');
  END IF;

  SELECT * INTO v_row FROM public.service_incidents WHERE id = p_incident_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'code','INCIDENT_NOT_FOUND');
  END IF;

  IF v_row.resolution_status = 'resolved' THEN
    RETURN jsonb_build_object('ok',true,'code','ALREADY_RESOLVED','idempotent',true,'incident',to_jsonb(v_row));
  END IF;

  UPDATE public.service_incidents SET
    resolution_status = p_resolution_status,
    resolution_type   = p_resolution_type,
    resolution_note   = p_resolution_note,
    resolved_by       = CASE WHEN p_resolution_status = 'resolved' THEN p_resolved_by ELSE resolved_by END,
    resolved_at        = CASE WHEN p_resolution_status = 'resolved' THEN now() ELSE resolved_at END,
    updated_at         = now()
  WHERE id = p_incident_id
  RETURNING * INTO v_row;

  INSERT INTO public.service_incident_resolutions(
    incident_id, resolution_status, resolution_type, resolution_note, actor, role
  ) VALUES (
    p_incident_id, p_resolution_status, p_resolution_type, p_resolution_note, p_resolved_by, p_actor_role
  );

  RETURN jsonb_build_object(
    'ok',true,
    'code', CASE WHEN p_resolution_status = 'resolved' THEN 'RESOLVED' ELSE 'ACKNOWLEDGED' END,
    'incident', to_jsonb(v_row)
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.rider_collect_and_complete_stop(p_order_id text, p_metodo_pago text, p_by_actor text, p_session_version integer, p_ip_hash text, p_meta jsonb, p_idem_scope_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_by       public.auth_actors%ROWTYPE;
  v_ds       jsonb;
  v_active   jsonb;
  v_canon    jsonb;
  v_estado   text;
  v_updated  int;
  v_method   text;
  v_meta     jsonb;
  v_pay      jsonb := NULL;
  v_pay_note text := NULL;
BEGIN
  v_method := lower(btrim(COALESCE(p_metodo_pago, '')));

  -- Only real door-collection methods. Anything else (notably the operator override
  -- "manual", or an empty string for an already-prepaid order) means NO money is claimed:
  -- the stop still completes, but nothing is written to the ledger and no flag is invented.
  IF v_method <> '' AND v_method NOT IN ('efectivo','tarjeta','bizum') THEN
    RETURN jsonb_build_object('ok', false, 'code', 'AUTH_METHOD_INVALID');
  END IF;

  IF p_session_version IS NULL OR p_session_version < 1 THEN
    RETURN jsonb_build_object('ok', false, 'code', 'AUTH_SESSION_STALE');
  END IF;

  -- L0 (W6.1 protocol) -- MOVED UP by W6.3, from after the auth_actors row lock to here:
  -- after pure input validation, before EVERY other lock. trip_authority.trips.rider_actor
  -- has a FOREIGN KEY to auth_actors, so start_rider_trip_v2's INSERT implicitly takes
  -- FOR KEY SHARE on the rider's actor row; with the old ordering that was a real ABBA
  -- deadlock against the FOR UPDATE below the moment v2 went live. Nothing else about
  -- this function's ordering, refusal codes or lock strengths changes.
  PERFORM pg_advisory_xact_lock(hashtext('LA_DIECI_DRIVER_STATO'));

  -- IDENTITY. Role must be exactly 'rider' — this contract never serves admin/operator,
  -- and never lets a rider borrow their authority.
  SELECT * INTO v_by FROM public.auth_actors WHERE actor = p_by_actor FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'code', 'AUTH_ACTOR_NOT_FOUND'); END IF;
  IF v_by.active <> true THEN RETURN jsonb_build_object('ok', false, 'code', 'AUTH_INITIATOR_INACTIVE'); END IF;
  IF v_by.role <> 'rider' THEN RETURN jsonb_build_object('ok', false, 'code', 'AUTH_FORBIDDEN_ROLE'); END IF;
  IF p_session_version <> v_by.session_version THEN
    RETURN jsonb_build_object('ok', false, 'code', 'AUTH_SESSION_STALE');
  END IF;

  SELECT COALESCE(NULLIF(valore,'')::jsonb, '{}'::jsonb) INTO v_ds
  FROM public.config WHERE chiave = 'DRIVER_STATO' FOR UPDATE;
  v_active := NULLIF(v_ds->'active_trip', 'null'::jsonb);

  -- W6.3 -- ASSIGNMENT. The order must belong to the currently active delivery.
  -- Membership is the rider's authority to collect on it; without this any rider could
  -- pay off any order. When a CANONICAL trip exists, trip_authority.trip_members is that
  -- authority and DRIVER_STATO is only a compatibility projection, so the canonical path
  -- always wins. With no canonical trip the pre-135 legacy path runs unchanged, so an
  -- in-flight pre-cutover DRIVER_STATO trip can still be collected and closed safely.
  -- A display order id that does not resolve to a frozen member is NON_MEMBER on both
  -- paths -- identical to the legacy behaviour for an id absent from the snapshot.
  v_canon := public.trip_authority_active_trip_v1();
  IF COALESCE((v_canon->>'exists')::boolean, false) THEN
    IF NOT (v_canon->'member_order_ids' ? p_order_id) THEN
      RETURN jsonb_build_object('ok', false, 'code', 'NON_MEMBER');
    END IF;
  ELSE
    IF v_active IS NULL OR jsonb_typeof(v_active) <> 'object' OR (v_active->>'status') <> 'ACTIVE' THEN
      RETURN jsonb_build_object('ok', false, 'code', 'NO_ACTIVE_TRIP');
    END IF;
    IF NOT (v_active->'order_ids' ? p_order_id) THEN
      RETURN jsonb_build_object('ok', false, 'code', 'NON_MEMBER');
    END IF;
  END IF;

  SELECT estado INTO v_estado FROM public.ordenes WHERE id = p_order_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'code', 'NOT_FOUND');
  END IF;

  -- Server-forced provenance. The client cannot claim a different source.
  v_meta := COALESCE(p_meta, '{}'::jsonb) || jsonb_build_object('source', 'rider_delivery');

  IF v_estado = 'RETIRADO' THEN
    -- Operative replay. The collection may still need reconciling: a rider whose first
    -- request completed the stop but died before the money was recorded must be able to
    -- retry. The deterministic key makes an honest retry a digest-identical replay.
    IF v_method <> '' THEN
      BEGIN
        v_pay := public._ledger_write_payment(
          p_order_id, v_method, NULL, p_by_actor, v_by.role, p_ip_hash, v_meta, p_idem_scope_key);
      EXCEPTION WHEN SQLSTATE '22023' OR SQLSTATE 'P0002' THEN
        v_pay_note := SQLERRM;
        IF v_pay_note <> 'AUTH_LEGACY_IMPORT_REQUIRED' THEN
          RETURN jsonb_build_object('ok', false, 'code', 'PAYMENT_REFUSED', 'payment_code', v_pay_note);
        END IF;
      END;
    END IF;
    RETURN jsonb_build_object('ok', true, 'code', 'IDEMPOTENT', 'order_id', p_order_id,
                              'payment', v_pay, 'payment_note', v_pay_note);
  END IF;

  IF v_estado <> 'EN_ENTREGA' THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_STATE');
  END IF;

  -- MONEY FIRST. A refusal here returns before the stop is completed, and the subtransaction
  -- has already rolled the attempted payment back: nothing half-written either way.
  -- AUTH_LEGACY_IMPORT_REQUIRED is the single tolerated refusal — that money is already on
  -- record in the pre-ledger representation, and re-recording it would double-count.
  IF v_method <> '' THEN
    BEGIN
      v_pay := public._ledger_write_payment(
        p_order_id, v_method, NULL, p_by_actor, v_by.role, p_ip_hash, v_meta, p_idem_scope_key);
    EXCEPTION WHEN SQLSTATE '22023' OR SQLSTATE 'P0002' THEN
      v_pay_note := SQLERRM;
      IF v_pay_note <> 'AUTH_LEGACY_IMPORT_REQUIRED' THEN
        RETURN jsonb_build_object('ok', false, 'code', 'PAYMENT_REFUSED', 'payment_code', v_pay_note);
      END IF;
    END;
  END IF;

  -- OPERATIVE completion ONLY. cobrado / metodo_pago are deliberately absent here:
  -- RETIRADO does not mean paid, and _ledger_write_payment is the sole writer of those
  -- columns. A prepaid or unpaid-on-delivery stop completes with the flags untouched.
  UPDATE public.ordenes
    SET estado       = 'RETIRADO',
        hora_entrega = (extract(epoch FROM now()) * 1000)::bigint
  WHERE id = p_order_id AND estado = 'EN_ENTREGA';
  GET DIAGNOSTICS v_updated = ROW_COUNT;

  IF v_updated = 0 THEN
    -- Lost the race after taking the money: ABORT so the recorded payment cannot survive
    -- a stop that did not complete. Must RAISE, never RETURN.
    RAISE EXCEPTION 'RIDER_STOP_LOST_RACE' USING ERRCODE='40001';
  END IF;

  RETURN jsonb_build_object('ok', true, 'code', 'OK', 'order_id', p_order_id,
                            'payment', v_pay, 'payment_note', v_pay_note);
END;
$function$;

CREATE OR REPLACE FUNCTION public.roll_service_session_economic_v1(p_service_session_id uuid, p_closeout_correlation_id uuid, p_actor text, p_source text, p_next_service_kind text, p_next_business_date date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
