CREATE OR REPLACE FUNCTION public.service_session_assign_financial_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_session_id     uuid;
  v_table_session  uuid;
  v_candidates     uuid[];
  v_order_created_at timestamptz;
BEGIN
  SELECT o.service_session_id, o.created_at INTO v_session_id, v_order_created_at
    FROM public.ordenes o WHERE o.id = NEW.order_id;

  IF v_session_id IS NULL AND NEW.payment_transaction_id IS NOT NULL THEN
    SELECT pt.table_session_id INTO v_table_session
      FROM public.payment_transactions pt WHERE pt.id = NEW.payment_transaction_id;

    SELECT array_agg(DISTINCT l.service_session_id) INTO v_candidates
      FROM public.payment_allocations pa
      JOIN public.table_order_lines   l ON l.id = pa.table_order_line_id
     WHERE pa.payment_transaction_id = NEW.payment_transaction_id
       AND l.table_session_id        = v_table_session
       AND l.order_id                = NEW.order_id;

    IF v_candidates IS NOT NULL AND cardinality(v_candidates) > 1 THEN
      RAISE EXCEPTION 'ORDER_OBLIGATION_AMBIGUOUS' USING ERRCODE='P0001',
        DETAIL = format('order=%s table_session=%s candidates=%s',
                        NEW.order_id, v_table_session, v_candidates);
    END IF;
    IF v_candidates IS NOT NULL AND cardinality(v_candidates) = 1 THEN
      v_session_id := v_candidates[1];
    END IF;
  END IF;

  IF v_session_id IS NULL THEN
    RAISE EXCEPTION 'ORDER_WITHOUT_SERVICE_SESSION' USING ERRCODE='P0001';
  END IF;

  NEW.service_session_id := v_session_id;

  NEW.obligation_economic_period_kind := CASE WHEN v_order_created_at IS NOT NULL
    THEN public.classify_economic_period_v1(v_order_created_at) ELSE NULL END;
  NEW.event_economic_period_kind := public.classify_economic_period_v1(clock_timestamp());

  RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.service_session_assign_order()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_ctx jsonb;
BEGIN
  v_ctx := public.resolve_order_intake_context_v1('order_intake_v1', 'order_intake_v1');
  IF (v_ctx->>'ok')::boolean IS NOT TRUE THEN
    RAISE EXCEPTION '%', COALESCE(v_ctx->>'code', 'ORDER_INTAKE_REJECTED') USING ERRCODE='P0001';
  END IF;

  IF NEW.service_session_id IS NOT NULL
     AND NEW.service_session_id <> (v_ctx->>'periodId')::uuid THEN
    RAISE EXCEPTION 'SERVICE_SESSION_FORGERY' USING ERRCODE='P0001';
  END IF;
  IF NEW.service_order_number IS NOT NULL THEN
    RAISE EXCEPTION 'SERVICE_ORDER_NUMBER_FORGERY' USING ERRCODE='P0001';
  END IF;

  NEW.service_session_id := (v_ctx->>'periodId')::uuid;
  UPDATE public.service_sessions
     SET next_order_number = next_order_number + 1,
         updated_at = now()
   WHERE id = NEW.service_session_id
  RETURNING next_order_number - 1 INTO NEW.service_order_number;

  RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.service_session_business_day_derive_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_business_day uuid;
BEGIN
  SELECT id INTO v_business_day FROM public.business_days WHERE business_date = NEW.business_date;
  IF v_business_day IS NULL THEN
    INSERT INTO public.business_days (business_date, opened_by, open_source, ticket_epoch, next_ticket_number)
    VALUES (NEW.business_date, COALESCE(NEW.opened_by, 'service_session_business_day_derive_v1'), 'service_session_insert', 1, 1)
    ON CONFLICT (business_date) DO NOTHING
    RETURNING id INTO v_business_day;
    IF v_business_day IS NULL THEN
      -- A concurrent INSERT for the same business_date won the race;
      -- business_days_business_date_uq is the actual serialization
      -- primitive here, this re-read just resolves the loser's own value.
      SELECT id INTO v_business_day FROM public.business_days WHERE business_date = NEW.business_date;
    END IF;
  END IF;
  NEW.business_day_id := v_business_day;
  RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.service_session_immutable_order()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.service_session_id IS DISTINCT FROM OLD.service_session_id THEN
    RAISE EXCEPTION 'SERVICE_SESSION_IMMUTABLE' USING ERRCODE='P0001';
  END IF;
  IF NEW.service_order_number IS DISTINCT FROM OLD.service_order_number THEN
    RAISE EXCEPTION 'SERVICE_ORDER_NUMBER_IMMUTABLE' USING ERRCODE='P0001';
  END IF;
  RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.service_session_validate_archive()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_session_id uuid;
BEGIN
  SELECT o.service_session_id INTO v_session_id FROM public.ordenes o WHERE o.id=NEW.orden_id;
  IF v_session_id IS NULL THEN RAISE EXCEPTION 'ORDER_WITHOUT_SERVICE_SESSION' USING ERRCODE='P0001'; END IF;
  IF NEW.service_session_id IS NOT NULL AND NEW.service_session_id <> v_session_id THEN RAISE EXCEPTION 'ARCHIVE_SESSION_MISMATCH' USING ERRCODE='P0001'; END IF;
  NEW.service_session_id := v_session_id;
  RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.service_session_validate_summary()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_session public.service_sessions%ROWTYPE;
BEGIN
  SELECT * INTO v_session FROM public.service_sessions WHERE id=NEW.service_session_id FOR SHARE;
  IF NOT FOUND OR v_session.status <> 'closing' OR v_session.business_date <> NEW.fecha THEN
    RAISE EXCEPTION 'SUMMARY_SESSION_MISMATCH' USING ERRCODE='P0001';
  END IF;
  RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.start_rider_trip(p_anchor_order_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_ds        jsonb;
  v_active    jsonb;
  v_anchor    public.ordenes%ROWTYPE;
  v_giro      text;
  v_order_ids text[];
  v_zones     text[];
  v_salidas   text[];
  v_giros     text[];
  v_trip_id   text;
  v_trip_seq  int;
  v_now       timestamptz := now();
  v_snapshot  jsonb;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('LA_DIECI_DRIVER_STATO'));

  INSERT INTO public.config(chiave, valore)
  VALUES ('DRIVER_STATO', '{}')
  ON CONFLICT (chiave) DO NOTHING;

  SELECT COALESCE(NULLIF(valore,'')::jsonb, '{}'::jsonb) INTO v_ds
  FROM public.config WHERE chiave = 'DRIVER_STATO' FOR UPDATE;

  v_active := v_ds->'active_trip';

  -- S2-1H — crash-safe service close gate. Any existing marker blocks new trips until
  -- the exact close_id is explicitly ended; there is no automatic timeout.
  IF v_ds ? 'service_closing' THEN
    RETURN jsonb_build_object('ok', false, 'code', 'SERVICE_CLOSING');
  END IF;

  SELECT * INTO v_anchor FROM public.ordenes WHERE id = p_anchor_order_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'code', 'NOT_FOUND');
  END IF;
  IF upper(COALESCE(v_anchor.tipo_consegna,'')) <> 'DOMICILIO' THEN
    RETURN jsonb_build_object('ok', false, 'code', 'BAD_REQUEST');
  END IF;

  -- Idempotent when the anchor already belongs to the active trip (same trip, incl.
  -- a second-member Salgo tap); conflict only for a genuinely different trip start.
  IF v_active IS NOT NULL AND (v_active->>'status') = 'ACTIVE' THEN
    IF (v_active->'order_ids' ? p_anchor_order_id)
       OR (v_active->>'anchor_order_id') = p_anchor_order_id THEN
      RETURN jsonb_build_object('ok', true, 'code', 'IDEMPOTENT', 'snapshot', v_active);
    ELSE
      RETURN jsonb_build_object('ok', false, 'code', 'ACTIVE_TRIP_CONFLICT');
    END IF;
  END IF;

  v_giro := v_anchor.manual_giro_id;
  IF v_giro IS NOT NULL THEN
    SELECT array_agg(id ORDER BY ts) INTO v_order_ids
    FROM public.ordenes
    WHERE manual_giro_id = v_giro AND estado IN ('LISTO','EN_ENTREGA');
  ELSE
    v_order_ids := ARRAY[p_anchor_order_id];
  END IF;

  -- Every selected member must be a delivery order in an eligible state; else roll back.
  IF EXISTS (
    SELECT 1 FROM public.ordenes
    WHERE id = ANY(v_order_ids)
      AND (estado NOT IN ('LISTO','EN_ENTREGA') OR upper(COALESCE(tipo_consegna,'')) <> 'DOMICILIO')
  ) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_STATE');
  END IF;

  UPDATE public.ordenes
    SET estado = 'EN_ENTREGA',
        hora_salida = (extract(epoch FROM v_now) * 1000)::bigint
  WHERE id = ANY(v_order_ids) AND estado = 'LISTO';

  SELECT array_agg(DISTINCT zona) FILTER (WHERE zona IS NOT NULL),
         array_agg(DISTINCT manual_giro_id) FILTER (WHERE manual_giro_id IS NOT NULL)
    INTO v_zones, v_giros
  FROM public.ordenes WHERE id = ANY(v_order_ids);

  IF v_giros IS NOT NULL THEN
    SELECT array_agg(DISTINCT salida_ref) FILTER (WHERE salida_ref IS NOT NULL)
      INTO v_salidas
    FROM public.manual_giros WHERE id = ANY(v_giros);
  END IF;

  v_trip_id  := gen_random_uuid()::text;
  v_trip_seq := COALESCE((v_ds->>'trip_seq')::int, 0) + 1;

  v_snapshot := jsonb_build_object(
    'trip_id',         v_trip_id,
    'anchor_order_id', p_anchor_order_id,
    'order_ids',       to_jsonb(v_order_ids),
    'manual_giro_ids', to_jsonb(COALESCE(v_giros,   ARRAY[]::text[])),
    'salida_refs',     to_jsonb(COALESCE(v_salidas, ARRAY[]::text[])),
    'zone_sequence',   to_jsonb(COALESCE(v_zones,   ARRAY[]::text[])),
    'n_orders',        COALESCE(array_length(v_order_ids,1), 0),
    'started_at',      to_jsonb(v_now),
    'closed_at',       'null'::jsonb,
    'trip_version',    1,
    'status',          'ACTIVE'
  );

  v_ds := v_ds || jsonb_build_object(
    'schema',          2,
    'stato',           'IN_GIRO',
    'zona',            to_jsonb(v_zones[1]),
    'partito_alle',    to_jsonb(v_now),
    'n_ordini',        COALESCE(array_length(v_order_ids,1), 0),
    'rientro_stimato', 'null'::jsonb,
    'trip_seq',        v_trip_seq,
    'active_trip',     v_snapshot
  );

  UPDATE public.config SET valore = v_ds::text WHERE chiave = 'DRIVER_STATO';

  RETURN jsonb_build_object('ok', true, 'code', 'OK', 'snapshot', v_snapshot,
                            'stato', 'IN_GIRO', 'trip_seq', v_trip_seq);
END;
$function$;

CREATE OR REPLACE FUNCTION public.start_rider_trip_v2(p_anchor_order_uid uuid, p_actor text, p_session_version integer, p_operational_session_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  v_by            public.auth_actors%ROWTYPE;
  v_legacy_trip   jsonb;
  v_existing      trip_authority.trips%ROWTYPE;
  v_giro_id       text;
  v_uids          uuid[];
  v_dates         date[];
  v_anchor_sess   uuid;
  v_trip_id       uuid;
  v_ids           text[];
  v_zones         text[];
  v_snapshot      jsonb;
  v_ds            jsonb;
  v_raw           text;
  d               record;
  r               record;
  v_svc           record; -- 138:DECL
BEGIN
  -- L0 (W6.1 protocol): the same dispatch lock every live Giro Authority command and
  -- the real start_rider_trip/rider_collect_and_complete_stop already take first.
  PERFORM pg_advisory_xact_lock(hashtext('LA_DIECI_DRIVER_STATO'));

  IF p_anchor_order_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_INPUT');
  END IF;
  IF p_session_version IS NULL OR p_session_version < 1 THEN
    RETURN jsonb_build_object('ok', false, 'code', 'AUTH_SESSION_STALE');
  END IF;

  -- IDENTITY (B1, migration 137). The departure is a dispatch/logistics action, not a
  -- money-collection one — legacyActionRoles.js already lets admin/operator call this
  -- legacy action, so the canonical departure gate now matches it exactly. This does
  -- NOT touch rider_collect_and_complete_stop, which stays rider-exclusive on purpose.
  -- W6.3: deliberately NOT "FOR UPDATE". A departure writes no money, and L0 -- taken
  -- first, and exclusive -- already serializes every trip writer, so a plain read is
  -- sufficient here. Note that the INSERT into trip_authority.trips further down still
  -- takes an implicit FOR KEY SHARE on this row through the dispatched_by foreign key
  -- (always populated, unlike rider_actor which may now be NULL); that is precisely why
  -- rider_collect_and_complete_stop's own L0 had to move ahead of ITS auth_actors FOR
  -- UPDATE in migration 135 (header, correction 2(d)) -- the same structural hazard,
  -- now guarded by dispatched_by instead of rider_actor whenever the caller is not a rider.
  SELECT * INTO v_by FROM public.auth_actors WHERE actor = p_actor;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'code', 'AUTH_ACTOR_NOT_FOUND'); END IF;
  IF v_by.active <> true THEN RETURN jsonb_build_object('ok', false, 'code', 'AUTH_INITIATOR_INACTIVE'); END IF;
  IF v_by.role NOT IN ('rider', 'admin', 'operator') THEN
    RETURN jsonb_build_object('ok', false, 'code', 'AUTH_FORBIDDEN_ROLE');
  END IF;
  IF p_session_version <> v_by.session_version THEN
    RETURN jsonb_build_object('ok', false, 'code', 'AUTH_SESSION_STALE');
  END IF;

  IF NOT giro_authority.scope_valid_v1(p_operational_session_ids) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'SCOPE_UNAVAILABLE');
  END IF;

  -- S2-1H crash-safe service-close gate, restored from legacy start_rider_trip: ANY
  -- existing marker blocks a new trip until the exact close_id is explicitly ended.
  -- Activating v2 without this would have silently dropped a live safety guard.
  SELECT c.valore INTO v_raw FROM public.config c WHERE c.chiave = 'DRIVER_STATO';
  IF v_raw IS NOT NULL AND btrim(v_raw) <> '' THEN
    BEGIN
      IF (v_raw::jsonb) ? 'service_closing' THEN
        RETURN jsonb_build_object('ok', false, 'code', 'SERVICE_CLOSING');
      END IF;
    EXCEPTION WHEN others THEN
      RETURN jsonb_build_object('ok', false, 'code', 'UNVERIFIABLE', 'reason', 'DRIVER_STATO_UNPARSEABLE');
    END;
  END IF;

  -- SINGLE-RIDER GLOBAL CHECK (D-2). Read under L0, which already fully serializes
  -- every writer (canonical or legacy) -- no second lock is needed to make this safe.
  SELECT * INTO v_existing FROM trip_authority.trips WHERE status = 'ACTIVE';
  IF FOUND THEN
    IF v_existing.anchor_order_uid = p_anchor_order_uid THEN
      RETURN jsonb_build_object('ok', true, 'code', 'IDEMPOTENT', 'trip_id', v_existing.trip_id,
        'giro_id', v_existing.giro_id, 'anchor_order_uid', v_existing.anchor_order_uid,
        'order_uids', COALESCE((SELECT jsonb_agg(tm.order_uid ORDER BY tm.stop_seq)
                                   FROM trip_authority.trip_members tm WHERE tm.trip_id = v_existing.trip_id), '[]'::jsonb));
    END IF;
    RETURN jsonb_build_object('ok', false, 'code', 'ACTIVE_TRIP_CONFLICT');
  END IF;

  -- No canonical trip is active. Also refuse if the LEGACY (DRIVER_STATO-only) path
  -- shows one active -- trip_facts_v1() falls through to DRIVER_STATO whenever
  -- trip_authority.trips is empty, which it is at this point in the function, so this
  -- read is exactly the legacy compatibility signal, closing the gap a mixed v1/v2
  -- calling environment would otherwise leave open.
  v_legacy_trip := giro_authority.trip_facts_v1();
  IF NOT (v_legacy_trip->>'available')::boolean THEN
    RETURN jsonb_build_object('ok', false, 'code', 'UNVERIFIABLE', 'reason', v_legacy_trip->>'reason');
  END IF;
  IF (v_legacy_trip->>'active')::boolean THEN
    RETURN jsonb_build_object('ok', false, 'code', 'ACTIVE_TRIP_CONFLICT', 'reason', 'LEGACY_TRIP_ACTIVE');
  END IF;

  -- CANONICAL GIRO MEMBERSHIP. Resolved exclusively from giro_authority -- never
  -- ordenes.manual_giro_id.
  v_giro_id := giro_authority.order_effective_giro_v1(p_anchor_order_uid, p_operational_session_ids, v_legacy_trip);

  IF v_giro_id IS NOT NULL THEN
    PERFORM 1 FROM public.manual_giros mg WHERE mg.id = v_giro_id FOR UPDATE;   -- L1
    -- Re-derive NOW that the giro row is locked -- same discipline as every other
    -- Giro Authority command (the unlocked read above may already be stale).
    SELECT * INTO d FROM giro_authority.derive_giros_v1(ARRAY[v_giro_id], p_operational_session_ids, v_legacy_trip);
    IF d.giro_id IS NULL OR d.giro_state <> 'PLANNED' OR NOT (p_anchor_order_uid = ANY (d.effective_order_uids)) THEN
      -- Gone/departed/anchor no longer effective between the unlocked read and the
      -- lock -- fall back to a single-order departure on just the anchor, exactly
      -- like legacy start_rider_trip does when no manual_giro_id match is found.
      v_uids := ARRAY[p_anchor_order_uid];
      v_giro_id := NULL;
    ELSE
      -- W6.3 -- CANONICAL_GIRO_DEPARTURE_IS_ATOMIC. The COMPLETE effective member set
      -- departs, or nothing does. This deliberately does NOT narrow the set to the
      -- members that happen to be LISTO right now (migration 134's body did, which
      -- would have allowed a PARTIAL DEPARTURE of a canonical giro): the eligibility
      -- loop below then refuses the whole departure with the existing INVALID_STATE
      -- code if ANY required member is not LISTO, before a single order transitions
      -- and before any trip row is created. derive_giros_v1 already returns this array
      -- ordered by order_uid, which is exactly the ordering the previous body produced.
      v_uids := d.effective_order_uids;
      IF v_uids IS NULL OR NOT (p_anchor_order_uid = ANY (v_uids)) THEN
        RETURN jsonb_build_object('ok', false, 'code', 'INVALID_STATE', 'order_uid', p_anchor_order_uid);
      END IF;
    END IF;
  ELSE
    v_uids := ARRAY[p_anchor_order_uid];
  END IF;

  PERFORM giro_authority.lock_orders_v1(v_uids);                                                  -- L2
  PERFORM 1 FROM public.ordenes o WHERE o.order_uid = ANY (v_uids) ORDER BY o.order_uid FOR SHARE; -- L4

  FOR r IN SELECT * FROM giro_authority.order_facts_v1(v_uids, v_legacy_trip) LOOP
    IF NOT r.present THEN
      RETURN jsonb_build_object('ok', false, 'code', 'ORDER_NOT_FOUND', 'order_uid', r.order_uid);
    END IF;
    IF r.delivery_type <> 'DOMICILIO' THEN
      RETURN jsonb_build_object('ok', false, 'code', 'ORDER_NOT_ELIGIBLE', 'order_uid', r.order_uid, 'reason', 'NOT_DOMICILIO');
    END IF;
    IF r.table_session_id IS NOT NULL THEN
      RETURN jsonb_build_object('ok', false, 'code', 'ORDER_NOT_ELIGIBLE', 'order_uid', r.order_uid, 'reason', 'TABLE_ORDER');
    END IF;
    IF NOT COALESCE(r.service_session_id = ANY (p_operational_session_ids), false) THEN
      RETURN jsonb_build_object('ok', false, 'code', 'SCOPE_MISMATCH', 'order_uid', r.order_uid);
    END IF;
    IF r.estado IS DISTINCT FROM 'LISTO' THEN
      RETURN jsonb_build_object('ok', false, 'code', 'INVALID_STATE', 'order_uid', r.order_uid, 'estado', r.estado);
    END IF;
    IF r.order_uid = p_anchor_order_uid THEN v_anchor_sess := r.service_session_id; END IF;
  END LOOP;

  SELECT array_agg(DISTINCT f.business_date) INTO v_dates FROM giro_authority.order_facts_v1(v_uids, v_legacy_trip) f;
  IF cardinality(v_dates) <> 1 OR v_dates[1] IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'SCOPE_MISMATCH');
  END IF;

  -- 138:BEGIN start_service_open
  -- ACTIVE_TRIP_SERVICE_CLOSE_EXCLUSION (migration 138). A trip may only become ACTIVE for a
  -- service that is STILL open at this atomic moment. L0 -- this function's first statement -- is
  -- the SAME lock close_service_session_v3 now takes before it closes a service, so the status read
  -- below cannot go stale before this transaction commits: a close that won L0 first has already
  -- committed 'closed' (seen here, so refused); a close that comes later waits for L0 and then
  -- finds this trip ACTIVE (so it refuses). The scope array was resolved by the caller BEFORE
  -- this call and is NOT trusted for liveness. EVERY distinct service of the departing orders is
  -- judged (the anchor's is the trip's own service_session_id): a missing row, or any status other
  -- than 'open' ('closing', 'closed', 'rolled_over'), refuses the departure. No other service is
  -- substituted, no order is reassigned and nothing is reopened.
  FOR v_svc IN
    SELECT s.sid, ss.status
      FROM (SELECT DISTINCT f.service_session_id AS sid
              FROM giro_authority.order_facts_v1(v_uids, v_legacy_trip) f) s
      LEFT JOIN public.service_sessions ss ON ss.id = s.sid
     ORDER BY (s.sid IS NOT DISTINCT FROM v_anchor_sess) DESC, s.sid
  LOOP
    IF v_svc.status IS DISTINCT FROM 'open' THEN
      RETURN jsonb_build_object('ok', false, 'code', 'SERVICE_NOT_OPEN',
        'service_session_id', v_svc.sid, 'status', v_svc.status);
    END IF;
  END LOOP;
  -- 138:END start_service_open

  -- CREATE exactly one canonical trip + freeze its members. The trips_one_active_v1
  -- partial unique index is the DB-level backstop; L0 above is the real serialization.
  -- trips_one_trip_per_giro_v1 (W6.3) is the second backstop: a canonical giro can
  -- produce at most ONE trip in its lifetime. rider_actor (B1, migration 137) is the
  -- caller ONLY when the caller is actually a rider; dispatched_by is always the caller.
  v_trip_id := gen_random_uuid();
  INSERT INTO trip_authority.trips
    (trip_id, business_date, service_session_id, rider_actor, dispatched_by, anchor_order_uid, giro_id, departed_at, status, seq)
  VALUES
    (v_trip_id, v_dates[1], v_anchor_sess, CASE WHEN v_by.role = 'rider' THEN p_actor ELSE NULL END, p_actor,
     p_anchor_order_uid, v_giro_id, now(), 'ACTIVE', nextval('trip_authority.trips_seq_v1'));
  PERFORM trip_authority.freeze_members_v1(v_trip_id, v_uids, p_actor);

  -- Transition eligible orders to EN_ENTREGA atomically. Order stop state stays
  -- authoritative in ordenes.estado/hora_entrega -- never duplicated in trip_members.
  UPDATE public.ordenes
     SET estado = 'EN_ENTREGA', hora_salida = (extract(epoch FROM now()) * 1000)::bigint
   WHERE order_uid = ANY (v_uids) AND estado = 'LISTO';

  -- DRIVER_STATO COMPATIBILITY PROJECTION ONLY -- derived from the canonical facts
  -- just created, never independently authoritative (D-1). Legacy readers/writers
  -- (Cocina/Entregas dashboards, delete_order_if_not_active) keep working unmodified
  -- against this row during the W6 compatibility window.
  SELECT array_agg(o.id ORDER BY u.ord) INTO v_ids
    FROM unnest(v_uids) WITH ORDINALITY AS u(order_uid, ord) JOIN public.ordenes o ON o.order_uid = u.order_uid;
  SELECT array_agg(DISTINCT o.zona) FILTER (WHERE o.zona IS NOT NULL) INTO v_zones
    FROM public.ordenes o WHERE o.order_uid = ANY (v_uids);
  v_snapshot := jsonb_build_object(
    'trip_id', v_trip_id::text, 'anchor_order_id', (SELECT id FROM public.ordenes WHERE order_uid = p_anchor_order_uid),
    'order_ids', to_jsonb(v_ids), 'manual_giro_ids', CASE WHEN v_giro_id IS NULL THEN '[]'::jsonb ELSE jsonb_build_array(v_giro_id) END,
    'salida_refs', '[]'::jsonb, 'zone_sequence', to_jsonb(COALESCE(v_zones, ARRAY[]::text[])),
    'n_orders', COALESCE(array_length(v_uids, 1), 0), 'started_at', to_jsonb(now()), 'closed_at', 'null'::jsonb,
    'trip_version', 1, 'status', 'ACTIVE');

  INSERT INTO public.config (chiave, valore) VALUES ('DRIVER_STATO', '{}')
  ON CONFLICT (chiave) DO NOTHING;
  SELECT COALESCE(NULLIF(valore, '')::jsonb, '{}'::jsonb) INTO v_ds
    FROM public.config WHERE chiave = 'DRIVER_STATO' FOR UPDATE;                                   -- L5
  v_ds := v_ds || jsonb_build_object(
    'schema', 2, 'stato', 'IN_GIRO', 'zona', to_jsonb(v_zones[1]),
    -- language-guard: allow-legacy n_ordini is the existing DRIVER_STATO snapshot field name (start_rider_trip's own convention), not new vocabulary
    'partito_alle', to_jsonb(now()), 'n_ordini', COALESCE(array_length(v_uids, 1), 0),
    'rientro_stimato', 'null'::jsonb, 'trip_seq', COALESCE((v_ds->>'trip_seq')::int, 0) + 1,
    'active_trip', v_snapshot);
  UPDATE public.config SET valore = v_ds::text WHERE chiave = 'DRIVER_STATO';

  RETURN jsonb_build_object('ok', true, 'code', 'OK', 'trip_id', v_trip_id, 'giro_id', v_giro_id,
    'anchor_order_uid', p_anchor_order_uid, 'order_uids', to_jsonb(v_uids), 'business_date', v_dates[1]);
END $function$;

CREATE OR REPLACE FUNCTION public.supersede_closeout_attempt(p_closeout_correlation_id uuid, p_actor text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_row public.service_closeout_attempts%ROWTYPE;
BEGIN
  IF p_closeout_correlation_id IS NULL THEN
    RETURN jsonb_build_object('ok',false,'code','INVALID_ARGUMENTS');
  END IF;
  IF p_actor IS NULL OR btrim(p_actor) = '' THEN
    RETURN jsonb_build_object('ok',false,'code','INVALID_ACTOR');
  END IF;

  SELECT * INTO v_row FROM public.service_closeout_attempts
   WHERE closeout_correlation_id = p_closeout_correlation_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok',false,'code','ATTEMPT_NOT_FOUND');
  END IF;

  IF v_row.status = 'completed' THEN
    RETURN jsonb_build_object('ok',false,'code','CANNOT_SUPERSEDE_COMPLETED_ATTEMPT');
  END IF;
  IF v_row.status = 'superseded' THEN
    RETURN jsonb_build_object('ok',true,'code','ALREADY_SUPERSEDED','idempotent',true,'attempt',to_jsonb(v_row));
  END IF;

  UPDATE public.service_closeout_attempts
     SET status = 'superseded', superseded_at = now(), supersession_reason = p_reason, updated_at = now()
   WHERE closeout_correlation_id = p_closeout_correlation_id
  RETURNING * INTO v_row;

  UPDATE public.service_incidents
     SET resolution_status = 'superseded',
         resolution_type   = 'closeout_attempt_superseded',
         resolved_by       = p_actor,
         resolved_at       = now(),
         updated_at        = now()
   WHERE closeout_correlation_id = p_closeout_correlation_id
     AND resolution_status IN ('pending','acknowledged');

  RETURN jsonb_build_object('ok',true,'code','SUPERSEDED','idempotent',false,'attempt',to_jsonb(v_row));
END;
$function$;

CREATE OR REPLACE FUNCTION public.table_order_lines_stamp_economic_period_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  NEW.economic_period_kind := public.classify_economic_period_v1(clock_timestamp());
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.trip_authority_active_trip_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  v_trip      trip_authority.trips%ROWTYPE;
  v_ids       jsonb;
  v_zones     jsonb;
  v_n         integer;
  v_missing   integer;
  v_nonterm   integer;
  v_anchor_id text;
BEGIN
  SELECT * INTO v_trip FROM trip_authority.trips WHERE status = 'ACTIVE';
  IF NOT FOUND THEN
    RETURN jsonb_build_object('exists', false);
  END IF;

  SELECT COALESCE(jsonb_agg(o.id ORDER BY tm.stop_seq) FILTER (WHERE o.id IS NOT NULL), '[]'::jsonb),
         count(*)::integer,
         count(*) FILTER (WHERE o.id IS NULL)::integer,
         count(*) FILTER (WHERE o.id IS NOT NULL
                            AND NOT (o.estado = ANY (trip_authority.close_terminal_states_v1())))::integer
    INTO v_ids, v_n, v_missing, v_nonterm
    FROM trip_authority.trip_members tm
    LEFT JOIN public.ordenes o ON o.order_uid = tm.order_uid
   WHERE tm.trip_id = v_trip.trip_id;

  SELECT COALESCE(jsonb_agg(DISTINCT o.zona) FILTER (WHERE o.zona IS NOT NULL), '[]'::jsonb) INTO v_zones
    FROM trip_authority.trip_members tm
    JOIN public.ordenes o ON o.order_uid = tm.order_uid
   WHERE tm.trip_id = v_trip.trip_id;

  SELECT o.id INTO v_anchor_id FROM public.ordenes o WHERE o.order_uid = v_trip.anchor_order_uid;

  RETURN jsonb_build_object(
    'exists', true,
    'trip_id', v_trip.trip_id,
    'giro_id', v_trip.giro_id,
    'anchor_order_uid', v_trip.anchor_order_uid,
    'anchor_order_id', to_jsonb(v_anchor_id),
    'service_session_id', v_trip.service_session_id,
    'business_date', v_trip.business_date,
    'rider_actor', v_trip.rider_actor,
    'departed_at', v_trip.departed_at,
    'member_order_ids', v_ids,
    'member_count', v_n,
    'missing_member_count', v_missing,
    'non_terminal_member_count', v_nonterm,
    'zone_sequence', v_zones);
END $function$;

CREATE OR REPLACE FUNCTION public.trip_authority_close_active_trip_v1(p_trip_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  v_trip    trip_authority.trips%ROWTYPE;
  v_missing integer;
  v_nonterm integer;
  v_updated integer;
BEGIN
  IF p_trip_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'code', 'INVALID_INPUT');
  END IF;
  SELECT * INTO v_trip FROM trip_authority.trips WHERE trip_id = p_trip_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'code', 'NO_ACTIVE_TRIP');
  END IF;
  IF v_trip.status = 'CLOSED' THEN
    RETURN jsonb_build_object('ok', true, 'code', 'IDEMPOTENT', 'trip_id', p_trip_id);
  END IF;

  SELECT count(*) FILTER (WHERE o.id IS NULL)::integer,
         count(*) FILTER (WHERE o.id IS NOT NULL
                            AND NOT (o.estado = ANY (trip_authority.close_terminal_states_v1())))::integer
    INTO v_missing, v_nonterm
    FROM trip_authority.trip_members tm
    LEFT JOIN public.ordenes o ON o.order_uid = tm.order_uid
   WHERE tm.trip_id = p_trip_id;

  IF v_missing > 0 THEN
    RETURN jsonb_build_object('ok', false, 'code', 'MISSING_TRIP_MEMBER');
  END IF;
  IF v_nonterm > 0 THEN
    RETURN jsonb_build_object('ok', false, 'code', 'EARLY_CLOSE');
  END IF;

  UPDATE trip_authority.trips
     SET status = 'CLOSED', closed_at = now()
   WHERE trip_id = p_trip_id AND status = 'ACTIVE';
  GET DIAGNOSTICS v_updated = ROW_COUNT;
  IF v_updated <> 1 THEN
    RETURN jsonb_build_object('ok', false, 'code', 'NO_ACTIVE_TRIP');
  END IF;
  RETURN jsonb_build_object('ok', true, 'code', 'OK', 'trip_id', p_trip_id);
END $function$;

CREATE OR REPLACE FUNCTION public.trip_projection_v1(p_operational_session_ids uuid[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  v_trip    trip_authority.trips%ROWTYPE;
  v_members jsonb;
BEGIN
  IF NOT giro_authority.scope_valid_v1(p_operational_session_ids) THEN
    RETURN jsonb_build_object('ok', false, 'code', 'SCOPE_UNAVAILABLE');
  END IF;
  SELECT * INTO v_trip FROM trip_authority.trips
   WHERE status = 'ACTIVE' AND service_session_id = ANY (p_operational_session_ids);
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', true, 'active', false);
  END IF;
  SELECT jsonb_agg(jsonb_build_object('order_uid', tm.order_uid, 'stop_seq', tm.stop_seq) ORDER BY tm.stop_seq)
    INTO v_members FROM trip_authority.trip_members tm WHERE tm.trip_id = v_trip.trip_id;
  RETURN jsonb_build_object('ok', true, 'active', true, 'trip_id', v_trip.trip_id,
    'anchor_order_uid', v_trip.anchor_order_uid, 'giro_id', v_trip.giro_id,
    'departed_at', v_trip.departed_at, 'members', COALESCE(v_members, '[]'::jsonb));
END $function$;

CREATE OR REPLACE FUNCTION public.user_profiles_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.id <> OLD.id THEN
    RAISE EXCEPTION 'USER_PROFILE_ID_IMMUTABLE' USING ERRCODE = 'P0001';
  END IF;
  IF NEW.created_at <> OLD.created_at THEN
    RAISE EXCEPTION 'USER_PROFILE_CREATED_AT_IMMUTABLE' USING ERRCODE = 'P0001';
  END IF;
  NEW.created_at := OLD.created_at;
  NEW.updated_at := now();
  RETURN NEW;
END $function$;

CREATE OR REPLACE FUNCTION public.workspace_account_audit_append_only()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  RAISE EXCEPTION 'workspace_account_audit is append-only' USING ERRCODE = '0A000';
END $function$;

CREATE OR REPLACE FUNCTION public.workspace_activation_integrity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.lifecycle_status = 'active' THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.workspace_memberships
       WHERE workspace_id = NEW.id AND role = 'workspace_owner' AND status = 'active'
    ) THEN
      RAISE EXCEPTION 'WORKSPACE_ACTIVATE_REQUIRES_OWNER (workspace %)', NEW.id USING ERRCODE = 'P0001';
    END IF;
  END IF;
  RETURN NULL;
END $function$;

CREATE OR REPLACE FUNCTION public.workspace_owner_integrity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_ws uuid; v_life text; v_cnt int;
BEGIN
  v_ws := COALESCE(NEW.workspace_id, OLD.workspace_id);
  SELECT lifecycle_status INTO v_life FROM public.workspaces WHERE id = v_ws;
  IF v_life IS NULL THEN RETURN NULL; END IF;
  IF v_life = 'active' THEN
    SELECT count(*) INTO v_cnt FROM public.workspace_memberships
     WHERE workspace_id = v_ws AND role = 'workspace_owner' AND status = 'active';
    IF v_cnt = 0 THEN
      RAISE EXCEPTION 'WORKSPACE_ACTIVE_REQUIRES_OWNER (workspace %)', v_ws USING ERRCODE = 'P0001';
    END IF;
  END IF;
  RETURN NULL;
END $function$;

CREATE OR REPLACE FUNCTION trip_authority.close_terminal_states_v1()
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
  -- language-guard: allow-legacy these are close_rider_trip's own pre-135 ordenes.estado literals, copied verbatim
  SELECT ARRAY['RETIRADO', 'COMPLETADO', 'COMPLETATO', 'CANCELADO', 'ANULADO']::text[]
$function$;

CREATE OR REPLACE FUNCTION trip_authority.departed_hhmm_v1(p_departed_at timestamp with time zone)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
  SELECT CASE WHEN p_departed_at IS NULL THEN NULL
              ELSE to_char(p_departed_at AT TIME ZONE 'Europe/Madrid', 'HH24:MI') END
$function$;

CREATE OR REPLACE FUNCTION trip_authority.freeze_members_v1(p_trip_id uuid, p_order_uids uuid[], p_actor text)
 RETURNS void
 LANGUAGE sql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
  INSERT INTO trip_authority.trip_members (trip_id, order_uid, stop_seq, created_by)
  SELECT p_trip_id, u.order_uid, u.ord::integer, btrim(p_actor)
  FROM unnest(p_order_uids) WITH ORDINALITY AS u(order_uid, ord)
$function$;

CREATE OR REPLACE FUNCTION trip_authority.progress_terminal_states_v1()
 RETURNS text[]
 LANGUAGE sql
 STABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
  SELECT giro_authority.delivered_states_v1() || giro_authority.cancelled_states_v1()
$function$;

CREATE OR REPLACE FUNCTION trip_authority.trip_facts_canonical_v1()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  v_trip      trip_authority.trips%ROWTYPE;
  v_order_ids jsonb;
BEGIN
  SELECT * INTO v_trip FROM trip_authority.trips WHERE status = 'ACTIVE';
  IF NOT FOUND THEN
    RETURN jsonb_build_object('available', true, 'active', false, 'order_ids', '[]'::jsonb, 'giro_ids', '[]'::jsonb,
                              'canonical_trip_exists', false);
  END IF;
  SELECT COALESCE(jsonb_agg(o.id ORDER BY tm.stop_seq) FILTER (WHERE o.id IS NOT NULL), '[]'::jsonb)
    INTO v_order_ids
    FROM trip_authority.trip_members tm
    LEFT JOIN public.ordenes o ON o.order_uid = tm.order_uid
   WHERE tm.trip_id = v_trip.trip_id;
  RETURN jsonb_build_object('available', true, 'active', true, 'trip_id', v_trip.trip_id::text,
    'order_ids', v_order_ids,
    'giro_ids', CASE WHEN v_trip.giro_id IS NULL THEN '[]'::jsonb ELSE jsonb_build_array(v_trip.giro_id) END,
    'canonical_trip_exists', true);
END $function$;

CREATE OR REPLACE FUNCTION trip_authority.trip_members_append_only_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
BEGIN
  RAISE EXCEPTION 'TRIP_MEMBERS_APPEND_ONLY' USING ERRCODE = 'P0001';
END $function$;

-- 5. column defaults
ALTER TABLE giro_authority.giro_intents ALTER COLUMN order_context SET DEFAULT '{}'::jsonb;
ALTER TABLE giro_authority.giro_intents ALTER COLUMN captured_at SET DEFAULT now();
ALTER TABLE giro_authority.giro_members ALTER COLUMN created_at SET DEFAULT now();
ALTER TABLE public.access_management_idempotency ALTER COLUMN created_at SET DEFAULT now();
ALTER TABLE public.analisi_serata ALTER COLUMN n_conversazioni SET DEFAULT 0;
ALTER TABLE public.analisi_serata ALTER COLUMN n_ordini SET DEFAULT 0;
ALTER TABLE public.analisi_serata ALTER COLUMN punti_attenzione SET DEFAULT '[]'::jsonb;
ALTER TABLE public.analisi_serata ALTER COLUMN cosa_funzionato SET DEFAULT '[]'::jsonb;
ALTER TABLE public.archived_order_financial_resolutions ALTER COLUMN id SET DEFAULT gen_random_uuid();
ALTER TABLE public.archived_order_financial_resolutions ALTER COLUMN created_at SET DEFAULT clock_timestamp();
ALTER TABLE public.archived_order_financial_resolutions ALTER COLUMN lifecycle_semantics SET DEFAULT 'economic_period_v1'::text;
ALTER TABLE public.archivio_conv ALTER COLUMN created_at SET DEFAULT now();
ALTER TABLE public.auth_actor_pin_fingerprints ALTER COLUMN created_at SET DEFAULT now();
ALTER TABLE public.auth_actors ALTER COLUMN session_version SET DEFAULT 1;
ALTER TABLE public.auth_actors ALTER COLUMN active SET DEFAULT true;
ALTER TABLE public.auth_actors ALTER COLUMN failed_count SET DEFAULT 0;
ALTER TABLE public.auth_actors ALTER COLUMN updated_at SET DEFAULT now();
ALTER TABLE public.auth_actors ALTER COLUMN created_at SET DEFAULT now();
