-- 6. constraints
ALTER TABLE giro_authority.giro_intents ADD CONSTRAINT giro_intents_phase_check CHECK ((phase = ANY (ARRAY['CAPTURE'::text, 'CONSUME'::text, 'EXPIRY'::text])));
ALTER TABLE giro_authority.giro_intents ADD CONSTRAINT giro_intents_pkey PRIMARY KEY (order_uid);
ALTER TABLE giro_authority.giro_intents ADD CONSTRAINT giro_intents_state_shape_chk CHECK ((((status = 'PENDING'::text) AND (phase = 'CAPTURE'::text) AND (resolved_at IS NULL) AND (resolution_code IS NULL) AND (resulting_giro_id IS NULL) AND (target_fingerprint IS NOT NULL) AND (((target_kind = 'GIRO'::text) AND (target_giro_id IS NOT NULL) AND (target_order_uid IS NULL)) OR ((target_kind = 'ANCHOR'::text) AND (target_order_uid IS NOT NULL) AND (target_giro_id IS NULL)))) OR ((status = 'CONSUMED'::text) AND (phase = 'CONSUME'::text) AND (resolved_at IS NOT NULL) AND (resolution_code = ANY (ARRAY['ATTACHED'::text, 'GIRO_CREATED'::text])) AND (resulting_giro_id IS NOT NULL)) OR ((status = 'REJECTED'::text) AND (resolved_at IS NOT NULL) AND (resulting_giro_id IS NULL) AND (((phase = 'CAPTURE'::text) AND (resolution_code = ANY (ARRAY['CAPTURE_MALFORMED'::text, 'CAPTURE_UNTRUSTED_SOURCE'::text, 'CAPTURE_NOT_ELIGIBLE'::text, 'CAPTURE_TARGET_NOT_FOUND'::text, 'CAPTURE_INTERNAL'::text]))) OR ((phase = 'CONSUME'::text) AND (resolution_code = ANY (ARRAY['TARGET_CHANGED'::text, 'TARGET_DEPARTED'::text, 'TARGET_GONE'::text, 'ORDER_CHANGED'::text, 'ORDER_NOT_ELIGIBLE'::text, 'SCOPE_UNAVAILABLE'::text, 'UNVERIFIABLE'::text]))))) OR ((status = 'EXPIRED'::text) AND (phase = 'EXPIRY'::text) AND (resolved_at IS NOT NULL) AND (resolution_code = 'SERVICE_CLOSED'::text) AND (resulting_giro_id IS NULL))));
ALTER TABLE giro_authority.giro_intents ADD CONSTRAINT giro_intents_status_check CHECK ((status = ANY (ARRAY['PENDING'::text, 'CONSUMED'::text, 'REJECTED'::text, 'EXPIRED'::text])));
ALTER TABLE giro_authority.giro_intents ADD CONSTRAINT giro_intents_target_kind_check CHECK ((target_kind = ANY (ARRAY['GIRO'::text, 'ANCHOR'::text])));
ALTER TABLE giro_authority.giro_members ADD CONSTRAINT giro_members_created_by_check CHECK ((btrim(created_by) <> ''::text));
ALTER TABLE giro_authority.giro_members ADD CONSTRAINT giro_members_pkey PRIMARY KEY (order_uid);
ALTER TABLE public.access_management_idempotency ADD CONSTRAINT access_management_idempotency_pkey PRIMARY KEY (workspace_id, by_actor, by_sid_hash, action, client_request_id);
ALTER TABLE public.analisi_serata ADD CONSTRAINT analisi_serata_pkey PRIMARY KEY (data);
ALTER TABLE public.archived_order_financial_resolutions ADD CONSTRAINT aofr_correlation_uq UNIQUE (action_correlation_id);
ALTER TABLE public.archived_order_financial_resolutions ADD CONSTRAINT aofr_payment_method_chk CHECK ((((resolution_type = 'recovered_payment'::text) AND (payment_method = ANY (ARRAY['efectivo'::text, 'tarjeta'::text, 'bizum'::text]))) OR ((resolution_type <> 'recovered_payment'::text) AND (payment_method IS NULL))));
ALTER TABLE public.archived_order_financial_resolutions ADD CONSTRAINT aofr_reversal_target_chk CHECK ((((resolution_type = 'reversal'::text) AND (reversed_event_id IS NOT NULL)) OR ((resolution_type <> 'reversal'::text) AND (reversed_event_id IS NULL))));
ALTER TABLE public.archived_order_financial_resolutions ADD CONSTRAINT archived_order_financial_resolut_remaining_exposure_cents_check CHECK ((remaining_exposure_cents >= 0));
ALTER TABLE public.archived_order_financial_resolutions ADD CONSTRAINT archived_order_financial_resoluti_original_exposure_cents_check CHECK ((original_exposure_cents >= 0));
ALTER TABLE public.archived_order_financial_resolutions ADD CONSTRAINT archived_order_financial_resolutions_actor_check CHECK ((btrim(actor) <> ''::text));
ALTER TABLE public.archived_order_financial_resolutions ADD CONSTRAINT archived_order_financial_resolutions_amount_cents_check CHECK ((amount_cents > 0));
ALTER TABLE public.archived_order_financial_resolutions ADD CONSTRAINT archived_order_financial_resolutions_archived_order_id_check CHECK ((btrim(archived_order_id) <> ''::text));
ALTER TABLE public.archived_order_financial_resolutions ADD CONSTRAINT archived_order_financial_resolutions_kind_era_chk CHECK ((((lifecycle_semantics = 'economic_period_v1'::text) AND (service_kind IS NOT NULL)) OR ((lifecycle_semantics = 'operational_service_v1'::text) AND (service_kind IS NULL))));
ALTER TABLE public.archived_order_financial_resolutions ADD CONSTRAINT archived_order_financial_resolutions_lifecycle_semantics_chk CHECK ((lifecycle_semantics = ANY (ARRAY['economic_period_v1'::text, 'operational_service_v1'::text])));
ALTER TABLE public.archived_order_financial_resolutions ADD CONSTRAINT archived_order_financial_resolutions_lineage_sequence_check CHECK ((lineage_sequence > 0));
ALTER TABLE public.archived_order_financial_resolutions ADD CONSTRAINT archived_order_financial_resolutions_pkey PRIMARY KEY (id);
ALTER TABLE public.archived_order_financial_resolutions ADD CONSTRAINT archived_order_financial_resolutions_reason_check CHECK ((btrim(reason) <> ''::text));
ALTER TABLE public.archived_order_financial_resolutions ADD CONSTRAINT archived_order_financial_resolutions_resolution_type_check CHECK ((resolution_type = ANY (ARRAY['recovered_payment'::text, 'write_off'::text, 'reversal'::text])));
