  WHERE (SELECT md5(p.prosrc) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
          WHERE n.nspname = x.nsp AND p.proname = x.fn AND pg_get_function_identity_arguments(p.oid) = x.args) IS DISTINCT FROM x.want;
  IF v_bad IS NOT NULL THEN RAISE EXCEPTION 'V3_BASELINE post-condition: function body differs from the catalog: %', v_bad; END IF;
  IF (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname IN ('public','giro_authority','trip_authority')) <> 163 THEN RAISE EXCEPTION 'V3_BASELINE post-condition: function count'; END IF;
  IF (SELECT count(*) FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname IN ('public','giro_authority','trip_authority') AND c.relkind = 'r') <> 62 THEN RAISE EXCEPTION 'V3_BASELINE post-condition: table count'; END IF;
END $post$;

COMMIT;
